module sign_injection_result #(
    parameter WORD_W = 16
) (
    input  wire                  clk,
    input  wire                  rst_n,
    input  wire                  in_valid,
    output wire                  in_ready,
    input  wire [WORD_W-1:0]     operand_a,
    input  wire [WORD_W-1:0]     operand_b,
    input  wire                  invert_sign,
    input  wire                  xor_sign,
    input  wire                  close_scope,
    output reg                   out_valid,
    input  wire                  out_ready,
    output reg  [WORD_W-1:0]     result
);
    // Historical request fields associated with the held result.
    reg [WORD_W-1:0] operand_a_shadow;
    reg [WORD_W-1:0] operand_b_shadow;
    reg invert_shadow;
    reg xor_shadow;
    reg before_end;
    reg past_valid;

    assign in_ready = !out_valid || out_ready;
    wire accept = in_valid && in_ready;
    wire retire = out_valid && out_ready;
    wire injected_sign = operand_b[WORD_W-1] ^
                         (xor_sign ? operand_a[WORD_W-1] : invert_sign);

    initial begin
        operand_a_shadow = {WORD_W{1'b0}};
        operand_b_shadow = {WORD_W{1'b0}};
        invert_shadow = 1'b0;
        xor_shadow = 1'b0;
        result = {WORD_W{1'b0}};
        out_valid = 1'b0;
        before_end = 1'b1;
        past_valid = 1'b0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            operand_a_shadow <= {WORD_W{1'b0}};
            operand_b_shadow <= {WORD_W{1'b0}};
            invert_shadow <= 1'b0;
            xor_shadow <= 1'b0;
            result <= {WORD_W{1'b0}};
            out_valid <= 1'b0;
            before_end <= 1'b1;
            past_valid <= 1'b0;
        end else begin
            if (accept) begin
                operand_a_shadow <= operand_a;
                operand_b_shadow <= operand_b;
                invert_shadow <= invert_sign;
                xor_shadow <= xor_sign;
                result <= {injected_sign, operand_a[WORD_W-2:0]};
                out_valid <= 1'b1;
                past_valid <= 1'b1;
                if (close_scope)
                    before_end <= 1'b0;
            end else if (retire) begin
                out_valid <= 1'b0;
            end
        end
    end

    // Before the first accepted scope-closing request, a result change
    // requires a change in the recorded, previously accepted request.
    always @(posedge clk) begin
        if (past_valid && before_end && out_valid &&
            $stable({operand_a_shadow, operand_b_shadow,
                     invert_shadow, xor_shadow}))
            assert ($stable(result));
    end
endmodule

module i2c_config_slave #(
    parameter integer DATA_WIDTH = 16,
    parameter [15:0] BYTE_BITS = 16'd8,
    parameter [DATA_WIDTH-1:0] SLAVE_ADDRESS = 16'h0052
) (
    input  wire clk,
    input  wire scl_tick,
    input  wire start_seen,
    input  wire sda_in,
    output wire sda_drive_low,
    output wire busy,
    output wire [DATA_WIDTH-1:0] config_word
);
    // scl_tick enables one sampled rising bus-clock event.
    // An addressed write receives one byte and acknowledges it.
    // config_word retains the most recently shifted configuration bits.
    localparam [DATA_WIDTH-1:0] LAST_BIT = BYTE_BITS - 16'd1;
    localparam [DATA_WIDTH-1:0] RESPONSE_LIMIT = BYTE_BITS + 16'd2;

    typedef enum logic [2:0] {
        IDLE     = 3'd0,
        RX_ADDR  = 3'd1,
        ADDR_ACK = 3'd2,
        RX_DATA  = 3'd3,
        DATA_ACK = 3'd4
    } state_t;

    state_t state;
    logic [DATA_WIDTH-1:0] address_shift;
    logic [DATA_WIDTH-1:0] data_shift;
    logic [DATA_WIDTH-1:0] bit_index;
    logic [DATA_WIDTH-1:0] deadline;
    logic address_match;
    logic outstanding;
    logic armed;

    wire [DATA_WIDTH-1:0] address_next;
    wire selected_write;
    assign address_next = {address_shift[DATA_WIDTH-2:0], sda_in};
    assign selected_write =
        (address_next[BYTE_BITS-1:1] == SLAVE_ADDRESS[BYTE_BITS-2:0]) &&
        (address_next[0] == 1'b0);

    assign sda_drive_low = (state == ADDR_ACK) || (state == DATA_ACK);
    assign busy = outstanding;
    assign config_word = data_shift;

    initial begin
        state = IDLE;
        address_shift = 16'd0;
        data_shift = 16'd0;
        bit_index = 16'd0;
        deadline = 16'd0;
        address_match = 1'b0;
        outstanding = 1'b0;
        armed = 1'b0;
    end

    always @(posedge clk) begin
        if (scl_tick) begin
            if (outstanding && (deadline != 16'd0))
                deadline <= deadline - 16'd1;

            case (state)
                IDLE: begin
                    if (start_seen) begin
                        address_shift <= 16'd0;
                        bit_index <= 16'd0;
                        state <= RX_ADDR;
                    end
                end

                RX_ADDR: begin
                    address_shift <= address_next;
                    if (bit_index == LAST_BIT) begin
                        bit_index <= 16'd0;
                        address_match <= selected_write;
                        if (selected_write) begin
                            // Q: the first addressed write is accepted.
                            armed <= 1'b1;
                            outstanding <= 1'b1;
                            deadline <= RESPONSE_LIMIT;
                            state <= ADDR_ACK;
                        end else begin
                            state <= IDLE;
                        end
                    end else begin
                        bit_index <= bit_index + 16'd1;
                    end
                end

                ADDR_ACK: begin
                    bit_index <= 16'd0;
                    state <= RX_DATA;
                end

                RX_DATA: begin
                    data_shift <= {data_shift[DATA_WIDTH-2:0], sda_in};
                    if (bit_index == LAST_BIT) begin
                        bit_index <= 16'd0;
                        state <= DATA_ACK;
                    end else begin
                        bit_index <= bit_index + 16'd1;
                    end
                end

                DATA_ACK: begin
                    outstanding <= 1'b0;
                    address_match <= 1'b0;
                    deadline <= 16'd0;
                    bit_index <= 16'd0;
                    state <= IDLE;
                end

                default: begin
                    state <= IDLE;
                    bit_index <= 16'd0;
                    deadline <= 16'd0;
                    address_match <= 1'b0;
                    outstanding <= 1'b0;
                end
            endcase
        end
    end

    // After Q, an accepted request must finish before its bus-event budget expires.
    always @(*) assert (!armed || !outstanding || (deadline != 16'd0));
endmodule

module serial_ladder_core #(
    parameter WORD_BITS = 32,
    parameter SCALAR_BITS = 32,
    parameter POINT_ENTRIES = 3
) (
    input  wire                   clk,
    input  wire                   rst_n,
    input  wire                   ce,
    input  wire                   q_open,
    input  wire                   r_close,
    input  wire                   arm_req,
    input  wire                   start_req,
    input  wire [SCALAR_BITS-1:0] scalar_in,
    output wire [WORD_BITS-1:0]   result_point,
    output reg                    finish
);
    localparam [WORD_BITS-1:0] WORD_ZERO = WORD_BITS'(32'd0);
    localparam [WORD_BITS-1:0] WORD_ONE  = WORD_BITS'(32'd1);
    localparam [WORD_BITS-1:0] TOTAL_BITS = WORD_BITS'(SCALAR_BITS);
    localparam [WORD_BITS-1:0] LAST_INDEX = WORD_BITS'(SCALAR_BITS - 1);

    // Fixed-base elliptic-curve subgroup over F17: y^2 = x^3 + 1.
    // P=(0,1), -P=(0,16), and 3P=O. Point words encode these
    // actual points as 0, 1, and 16, respectively.
    localparam [WORD_BITS-1:0] POINT_O = WORD_BITS'(32'd0);
    localparam [WORD_BITS-1:0] POINT_P = WORD_BITS'(32'd1);
    localparam [WORD_BITS-1:0] POINT_N = WORD_BITS'(32'd16);

    localparam [1:0] PH_IDLE  = 2'd0;
    localparam [1:0] PH_ARMED = 2'd1;
    localparam [1:0] PH_RUN   = 2'd2;
    localparam [1:0] PH_DONE  = 2'd3;

    // Entries 0 and 1 are the ladder pair; entry 2 holds the base.
    reg [WORD_BITS-1:0] point_bank [0:POINT_ENTRIES-1];
    reg [SCALAR_BITS-1:0] scalar_reg;
    reg [WORD_BITS-1:0] bit_index;
    reg [1:0] phase;
    reg window;
    reg arm_seen;
    reg start_seen;
    reg pv;

    // Exact elliptic-curve addition table for the order-three subgroup.
    function automatic [WORD_BITS-1:0] ec_add;
        input [WORD_BITS-1:0] a;
        input [WORD_BITS-1:0] b;
        begin
            if (a == POINT_O)
                ec_add = b;
            else if (b == POINT_O)
                ec_add = a;
            else if ((a == POINT_P) && (b == POINT_P))
                ec_add = POINT_N;
            else if ((a == POINT_N) && (b == POINT_N))
                ec_add = POINT_P;
            else
                ec_add = POINT_O;
        end
    endfunction

    wire [WORD_BITS-1:0] ladder_sum;
    wire [WORD_BITS-1:0] double_r0;
    wire [WORD_BITS-1:0] double_r1;
    assign ladder_sum = ec_add(point_bank[0], point_bank[1]);
    assign double_r0 = ec_add(point_bank[0], point_bank[0]);
    assign double_r1 = ec_add(point_bank[1], point_bank[1]);
    assign result_point = point_bank[0];

    initial begin
        window = 1'b0;
        phase = PH_IDLE;
        arm_seen = 1'b0;
        start_seen = 1'b0;
        finish = 1'b0;
        scalar_reg = {SCALAR_BITS{1'b0}};
        bit_index = WORD_ZERO;
        pv = 1'b0;
        for (integer k = 0; k < POINT_ENTRIES; k = k + 1)
            point_bank[k] = ((k == 1) || (k == 2)) ? POINT_P : POINT_O;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            window <= 1'b0;
            phase <= PH_IDLE;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
            finish <= 1'b0;
            scalar_reg <= {SCALAR_BITS{1'b0}};
            bit_index <= WORD_ZERO;
            pv <= 1'b0;
            for (integer k = 0; k < POINT_ENTRIES; k = k + 1)
                point_bank[k] <= ((k == 1) || (k == 2)) ? POINT_P : POINT_O;
        end else if (ce) begin
            pv <= 1'b1;

            // Q opens a fresh command window; R closes it. Windows repeat.
            if (r_close || (q_open && !window)) begin
                window <= !r_close;
                phase <= PH_IDLE;
                arm_seen <= 1'b0;
                start_seen <= 1'b0;
                finish <= 1'b0;
                scalar_reg <= {SCALAR_BITS{1'b0}};
                bit_index <= WORD_ZERO;
                for (integer k = 0; k < POINT_ENTRIES; k = k + 1)
                    point_bank[k] <= ((k == 1) || (k == 2)) ? POINT_P : POINT_O;
            end else if (window) begin
                case (phase)
                    PH_IDLE: begin
                        if (arm_req) begin
                            scalar_reg <= scalar_in;
                            point_bank[0] <= POINT_O;
                            point_bank[1] <= point_bank[2];
                            bit_index <= WORD_ZERO;
                            arm_seen <= 1'b1;
                            phase <= PH_ARMED;
                        end
                    end
                    PH_ARMED: begin
                        if (start_req) begin
                            start_seen <= 1'b1;
                            phase <= PH_RUN;
                        end
                    end
                    PH_RUN: begin
                        // MSB-first Montgomery ladder: one add and one
                        // selected doubling per scalar bit.
                        if (scalar_reg[SCALAR_BITS-1]) begin
                            point_bank[0] <= ladder_sum;
                            point_bank[1] <= double_r1;
                        end else begin
                            point_bank[0] <= double_r0;
                            point_bank[1] <= ladder_sum;
                        end
                        scalar_reg <= {scalar_reg[SCALAR_BITS-2:0], 1'b0};
                        bit_index <= bit_index + WORD_ONE;
                        if (bit_index == LAST_INDEX) begin
                            finish <= 1'b1;
                            phase <= PH_DONE;
                        end
                    end
                    PH_DONE: begin
                        // Preserve the result until the window closes.
                    end
                endcase
            end
        end
    end

    // Within an open window, completion requires the earlier arm/start chain.
    always @(posedge clk)
        if (pv && window && $rose(finish))
            assert (arm_seen && start_seen);
endmodule

module snapshot_capture_queue #(
    parameter integer DEPTH = 4
) (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        i_src_step,
    input  wire        i_req_valid,
    output wire        o_req_ready,
    output wire        o_valid,
    input  wire        i_out_ready,
    output wire [63:0] o_data,
    output wire [63:0] o_tag
);
    localparam [63:0] CAPACITY = DEPTH;

    // Source clock edges are modeled by i_src_step on enabled clk edges.
    // The destination advances on every enabled clk edge.
    reg [63:0] running_value;
    reg [63:0] snapshot;
    reg req_toggle;
    reg src_req_meta, src_req_sync;
    reg src_ack_toggle;
    reg dst_ack_meta, dst_ack_sync;

    reg busy;
    reg armed;
    reg [63:0] pending_id;
    reg [63:0] request_count;
    reg [63:0] completion_count;
    reg [63:0] consumed_count;

    reg [63:0] q_data [0:DEPTH-1];
    reg [63:0] q_tag  [0:DEPTH-1];
    reg [DEPTH-1:0] q_valid;
    reg [63:0] rd_ptr, wr_ptr;
    reg [63:0] queued_count;
    wire [63:0] slot_offset [0:DEPTH-1];

    initial begin
        running_value = 64'd0;
        snapshot = 64'd0;
        req_toggle = 1'b0;
        src_req_meta = 1'b0;
        src_req_sync = 1'b0;
        src_ack_toggle = 1'b0;
        dst_ack_meta = 1'b0;
        dst_ack_sync = 1'b0;
        busy = 1'b0;
        armed = 1'b0;
        pending_id = 64'd0;
        request_count = 64'd0;
        completion_count = 64'd0;
        consumed_count = 64'd0;
        q_valid = {DEPTH{1'b0}};
        rd_ptr = 64'd0;
        wr_ptr = 64'd0;
        queued_count = 64'd0;
    end

    genvar g;
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin : slots
            localparam [63:0] SLOT = g;
            assign slot_offset[g] = (SLOT >= rd_ptr)
                ? SLOT - rd_ptr : SLOT + CAPACITY - rd_ptr;
            initial begin
                q_data[g] = 64'd0;
                q_tag[g] = 64'd0;
            end
        end
    endgenerate

    // Accepting a request reserves one FIFO slot until its snapshot returns.
    assign o_req_ready = i_ce && !busy && queued_count < CAPACITY;
    assign o_valid = (queued_count != 64'd0) && q_valid[rd_ptr];
    assign o_data = q_data[rd_ptr];
    assign o_tag = q_tag[rd_ptr];

    wire take_request = i_req_valid && o_req_ready;
    wire return_snapshot = busy && (dst_ack_sync == req_toggle);
    wire take_output = o_valid && i_out_ready;

    // All transfers are qualified by the common clock enable.
    always @(posedge clk) begin
        if (i_ce) begin
            if (i_src_step) begin
                running_value <= running_value + 64'd1;
                src_req_meta <= req_toggle;
                src_req_sync <= src_req_meta;
                if (src_req_sync != src_ack_toggle) begin
                    snapshot <= running_value;
                    src_ack_toggle <= src_req_sync;
                end
            end

            dst_ack_meta <= src_ack_toggle;
            dst_ack_sync <= dst_ack_meta;

            if (take_request) begin
                req_toggle <= !req_toggle;
                pending_id <= request_count;
                request_count <= request_count + 64'd1;
                busy <= 1'b1;
                // Q: the first accepted snapshot request permanently arms P.
                armed <= 1'b1;
            end

            if (take_output) begin
                q_valid[rd_ptr] <= 1'b0;
                consumed_count <= consumed_count + 64'd1;
                if (rd_ptr == CAPACITY - 64'd1)
                    rd_ptr <= 64'd0;
                else
                    rd_ptr <= rd_ptr + 64'd1;
            end

            if (return_snapshot) begin
                // The completion crossed two destination stages. The source
                // snapshot stays frozen until a later request reaches it.
                q_data[wr_ptr] <= snapshot;
                q_tag[wr_ptr] <= pending_id;
                q_valid[wr_ptr] <= 1'b1;
                completion_count <= completion_count + 64'd1;
                busy <= 1'b0;
                if (wr_ptr == CAPACITY - 64'd1)
                    wr_ptr <= 64'd0;
                else
                    wr_ptr <= wr_ptr + 64'd1;
            end

            case ({return_snapshot, take_output})
                2'b10: queued_count <= queued_count + 64'd1;
                2'b01: queued_count <= queued_count - 64'd1;
                default: queued_count <= queued_count;
            endcase
        end
    end

    always @(posedge clk)
        if (armed)
            assert (request_count - completion_count <= 64'd1);
endmodule

module metric_exp2_pipe #(
    parameter integer PIPE_DEPTH = 32'd32,
    parameter integer LUT_ENTRIES = 32'd32
) (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        i_valid,
    input  wire [63:0] i_x,
    output wire        o_ready,
    output wire        o_valid,
    output wire [63:0] o_exp2,
    input  wire        i_out_ready
);
    // PIPE_DEPTH >= 3. LUT_ENTRIES is a power of two from 2 through 32.
    // Binary64 input and output; a table plus linear residual polynomial
    // approximates exp2. Inputs outside [0,32) are clamped before evaluation.
    localparam integer LUT_BITS = $clog2(LUT_ENTRIES);
    localparam [63:0] PIPE_CAPACITY = PIPE_DEPTH;
    localparam [63:0] LUT_SIZE = LUT_ENTRIES;
    localparam [63:0] Q30_ONE = 64'h0000000040000000;
    localparam [63:0] LN2_Q30 = 64'd744261118;
    localparam [63:0] RESIDUAL_MASK =
        (64'd1 << (32'd30 - LUT_BITS)) - 64'd1;

    reg [63:0] coeff_rom [0:LUT_ENTRIES-1];
    reg [LUT_ENTRIES-1:0] coeff_valid;
    reg [63:0] data_pipe [0:PIPE_DEPTH-1];
    reg [PIPE_DEPTH-1:0] pipe_valid;
    reg [63:0] integer_s0, integer_s1, residual_s0;
    reg [63:0] outstanding;

    // Q1.31 samples of 2^(j/32). Smaller supported tables subsample this ROM.
    function [63:0] rom_word;
        input [63:0] slot;
        reg [63:0] sample;
        begin
            sample = (slot * 64'd32) / LUT_SIZE;
            case (sample)
                64'd0:  rom_word = 64'h0000000080000000;
                64'd1:  rom_word = 64'h0000000082cd8699;
                64'd2:  rom_word = 64'h0000000085aac368;
                64'd3:  rom_word = 64'h0000000088980e81;
                64'd4:  rom_word = 64'h000000008b95c1e4;
                64'd5:  rom_word = 64'h000000008ea4398b;
                64'd6:  rom_word = 64'h0000000091c3d373;
                64'd7:  rom_word = 64'h0000000094f4efa9;
                64'd8:  rom_word = 64'h000000009837f052;
                64'd9:  rom_word = 64'h000000009b8d39ba;
                64'd10: rom_word = 64'h000000009ef53261;
                64'd11: rom_word = 64'h00000000a2704303;
                64'd12: rom_word = 64'h00000000a5fed6aa;
                64'd13: rom_word = 64'h00000000a9a15ab5;
                64'd14: rom_word = 64'h00000000ad583eea;
                64'd15: rom_word = 64'h00000000b123f582;
                64'd16: rom_word = 64'h00000000b504f334;
                64'd17: rom_word = 64'h00000000b8fbaf47;
                64'd18: rom_word = 64'h00000000bd08a39f;
                64'd19: rom_word = 64'h00000000c12c4cca;
                64'd20: rom_word = 64'h00000000c5672a11;
                64'd21: rom_word = 64'h00000000c9b9bd86;
                64'd22: rom_word = 64'h00000000ce248c15;
                64'd23: rom_word = 64'h00000000d2a81d91;
                64'd24: rom_word = 64'h00000000d744fcca;
                64'd25: rom_word = 64'h00000000dbfbb798;
                64'd26: rom_word = 64'h00000000e0ccdeec;
                64'd27: rom_word = 64'h00000000e5b906e7;
                64'd28: rom_word = 64'h00000000eac0c6e8;
                64'd29: rom_word = 64'h00000000efe4b99c;
                64'd30: rom_word = 64'h00000000f5257d15;
                64'd31: rom_word = 64'h00000000fa83b2db;
                default: rom_word = 64'h0000000080000000;
            endcase
        end
    endfunction

    initial begin
        coeff_valid = {LUT_ENTRIES{1'b1}};
        pipe_valid = {PIPE_DEPTH{1'b0}};
        integer_s0 = 64'd0;
        integer_s1 = 64'd0;
        residual_s0 = 64'd0;
        outstanding = 64'd0;
        for (integer n = 32'd0; n < LUT_ENTRIES; n = n + 32'd1)
            coeff_rom[n] = rom_word(n);
        for (integer n = 32'd0; n < PIPE_DEPTH; n = n + 32'd1)
            data_pipe[n] = 64'd0;
    end

    // Convert binary64 to unsigned Q5.59, saturating at the upper endpoint.
    wire [63:0] input_exponent = {53'd0, i_x[62:52]};
    wire [63:0] input_significand = {11'd0, 1'b1, i_x[51:0]};
    wire [63:0] x_fixed = i_x[63] ? 64'd0 :
        ((input_exponent >= 64'd1028) ? 64'hffffffffffffffff :
         ((input_exponent >= 64'd1016) ?
          (input_significand << (input_exponent - 64'd1016)) :
          (input_significand >> (64'd1016 - input_exponent))));

    wire [63:0] table_index =
        (x_fixed >> (32'd59 - LUT_BITS)) & (LUT_SIZE - 64'd1);
    wire [63:0] input_integer = x_fixed >> 64'd59;
    wire [63:0] input_residual = (x_fixed >> 64'd29) & RESIDUAL_MASK;

    // The entire pipeline freezes behind a blocked output. Thus an occupied
    // stage is never overwritten before its item advances or is consumed.
    wire advance = i_ce && (!pipe_valid[PIPE_DEPTH-1] || i_out_ready);
    wire take = i_valid && coeff_valid[table_index];
    assign o_ready = advance && coeff_valid[table_index];
    assign o_valid = i_ce && pipe_valid[PIPE_DEPTH-1];
    assign o_exp2 = data_pipe[PIPE_DEPTH-1];

    // Stage 1: table_base * (1 + ln(2)*residual).
    // The table is Q1.31 and the residual polynomial is Q2.30.
    wire [63:0] linear_product = LN2_Q30 * residual_s0;
    wire [63:0] residual_polynomial =
        Q30_ONE + (linear_product >> 64'd30);
    wire [63:0] fractional_product = data_pipe[0] * residual_polynomial;
    wire [63:0] fractional_q30 = fractional_product >> 64'd31;
    wire [63:0] result_exponent = 64'd1023 + integer_s1;

    always @(posedge clk) begin
        if (advance) begin
            pipe_valid <= {pipe_valid[PIPE_DEPTH-2:0], take};
            data_pipe[0] <= coeff_rom[table_index];
            integer_s0 <= input_integer;
            residual_s0 <= input_residual;
            data_pipe[1] <= fractional_q30;
            integer_s1 <= integer_s0;
            // Stage 2: put the integer part in the binary64 exponent.
            data_pipe[2] <= {
                1'b0, result_exponent[10:0], data_pipe[1][29:0], 22'd0
            };
            for (integer s = 32'd3; s < PIPE_DEPTH; s = s + 32'd1)
                data_pipe[s] <= data_pipe[s-1];

            case ({take, pipe_valid[PIPE_DEPTH-1]})
                2'b10: outstanding <= outstanding + 64'd1;
                2'b01: outstanding <= outstanding - 64'd1;
                default: outstanding <= outstanding;
            endcase
        end
    end

    // Fixed stage positions encode order; no arbitration or age tags are used.
    reg [63:0] occupied_slots;
    always @(*) begin
        occupied_slots = 64'd0;
        for (integer p = 32'd0; p < PIPE_DEPTH; p = p + 32'd1)
            occupied_slots = occupied_slots + {63'd0, pipe_valid[p]};
    end

    assert property (outstanding <= PIPE_CAPACITY);
endmodule

module shadowed_serial_divider #(
    parameter integer ENTRIES = 4
) (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        cfg_write,
    input  wire [31:0] cfg_index,
    input  wire [31:0] cfg_ratio,
    output wire        cfg_ready,
    input  wire        shadow_load,
    input  wire [31:0] shadow_index,
    output wire        shadow_ready,
    input  wire        scope_begin,
    input  wire        scope_end,
    output reg         boundary_tick
);
    localparam [31:0] ENTRY_LIMIT = ENTRIES;
    localparam [31:0] BOOT_RATIO = 32'd4;

    reg [31:0] ratio_mem [0:ENTRIES-1];
    reg [ENTRIES-1:0] valid;
    reg [31:0] active_slot;
    reg [31:0] shadow_slot;
    reg [31:0] active_ratio;
    reg [31:0] shadow_ratio;
    reg [31:0] period_count;
    reg window;
    reg pv;

    wire [ENTRIES-1:0] entry_nonzero;
    genvar g;
    generate
        for (g = 32'd0; g < ENTRIES; g = g + 32'd1) begin : entry_checks
            assign entry_nonzero[g] = !valid[g] ||
                                      (ratio_mem[g] != 32'd0);
        end
    endgenerate

    // Active and shadow entries are reserved: software must wait rather
    // than overwrite a ratio that the divider still needs.
    assign cfg_ready = i_ce && (cfg_index < ENTRY_LIMIT) &&
                       (cfg_index != active_slot) &&
                       (cfg_index != shadow_slot);

    // Writes take priority over shadow selections, avoiding a read/write
    // collision when both operations name the same table entry.
    assign shadow_ready = i_ce && !cfg_write &&
                          (shadow_index < ENTRY_LIMIT) &&
                          valid[shadow_index];

    integer k;
    initial begin
        for (k = 32'd0; k < ENTRIES; k = k + 32'd1)
            ratio_mem[k] = BOOT_RATIO;
        valid = {ENTRIES{1'b0}};
        valid[0] = 1'b1;
        active_slot = 32'd0;
        shadow_slot = 32'd0;
        active_ratio = BOOT_RATIO;
        shadow_ratio = BOOT_RATIO;
        period_count = 32'd0;
        boundary_tick = 1'b0;
        window = 1'b0;
        pv = 1'b0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            // Gating pv also makes a disabled cycle a complete state hold.
            pv <= 1'b1;

            if (scope_end)
                window <= 1'b0;
            else if (scope_begin)
                window <= 1'b1;

            if (cfg_write && cfg_ready) begin
                ratio_mem[cfg_index] <= (cfg_ratio == 32'd0)
                                       ? 32'd1 : cfg_ratio;
                valid[cfg_index] <= 1'b1;
            end else if (shadow_load && shadow_ready) begin
                shadow_slot <= shadow_index;
                shadow_ratio <= ratio_mem[shadow_index];
            end

            boundary_tick <= (period_count == active_ratio - 32'd1);
            if (period_count == active_ratio - 32'd1) begin
                period_count <= 32'd0;
                active_ratio <= shadow_ratio;
                active_slot <= shadow_slot;
            end else begin
                period_count <= period_count + 32'd1;
            end
        end
    end

    // Within the latched scope, each enabled result must report whether
    // the previous count reached the terminal value in its active entry.
    always @(posedge clk)
        if (pv && window && $past(i_ce))
            assert (boundary_tick ==
                    $past(period_count ==
                          (ratio_mem[active_slot] - 32'd1)));
endmodule

module rsqrt_seed_rom #(
    parameter DEPTH = 32'd48
) (
    input  wire        i_clk,
    input  wire        i_ce,
    input  wire [31:0] i_exponent,
    input  wire [31:0] i_significand_fraction,
    output wire [31:0] o_estimate,
    output wire        o_estimate_parity
);
    // DEPTH is even: one bank for each exponent parity.
    localparam [31:0] HALF_DEPTH = DEPTH / 32'd2;

    reg [31:0] seed_rom [0:DEPTH-1];
    reg [DEPTH-1:0] rom_valid;
    reg [31:0] pending_index;
    reg        pending_parity;
    reg [31:0] completed_index;
    reg [31:0] estimate;
    reg        estimate_parity;
    integer init_entry;

    // Constant ROM construction. For m = 2^parity * (1 + bin/HALF_DEPTH),
    // choose floor(16/sqrt(m)), then encode it as a Q16 seed.
    // The result has four effective fractional bits; all arithmetic is 32-bit.
    function automatic [31:0] seed_value(input [31:0] index);
        reg [31:0] bin;
        reg [31:0] mantissa_q10;
        reg [31:0] trial;
        begin
            bin = index % HALF_DEPTH;
            mantissa_q10 = 32'd1024 +
                           ((bin * 32'd1024) / HALF_DEPTH);
            if (index >= HALF_DEPTH)
                mantissa_q10 = mantissa_q10 << 32'd1;
            seed_value = 32'd0;
            for (trial = 32'd0; trial <= 32'd16;
                 trial = trial + 32'd1) begin
                if ((trial * trial * mantissa_q10) <= 32'd262144)
                    seed_value = trial << 32'd12;
            end
        end
    endfunction

    initial begin
        rom_valid = {DEPTH{1'b1}};
        pending_index = 32'd0;
        pending_parity = 1'b0;
        completed_index = 32'd0;
        estimate = seed_value(32'd0);
        estimate_parity = 1'b0;
        for (init_entry = 32'd0; init_entry < DEPTH;
             init_entry = init_entry + 32'd1)
            seed_rom[init_entry] = seed_value(init_entry);
    end

    // Five leading fraction bits select a bin within the parity bank.
    wire [31:0] fraction_slot;
    wire [31:0] lookup_index;
    assign fraction_slot =
        (((i_significand_fraction >> 32'd27) * HALF_DEPTH) >> 32'd5);
    assign lookup_index = fraction_slot +
                          (i_exponent[0] ? HALF_DEPTH : 32'd0);

    // Address/metadata stage followed by the registered ROM response.
    // Deasserting i_ce freezes every state register and the entire table.
    always @(posedge i_clk) begin
        if (i_ce) begin
            pending_index <= lookup_index;
            pending_parity <= i_exponent[0];
            if (rom_valid[pending_index]) begin
                estimate <= seed_rom[pending_index];
                completed_index <= pending_index;
                estimate_parity <= pending_parity;
            end
        end
    end

    assign o_estimate = estimate;
    assign o_estimate_parity = estimate_parity;

    // Absence: even-exponent responses never occupy the low-only range.
    always @(posedge i_clk)
        if (!estimate_parity)
            assert (!(estimate < 32'h0000b000));

    // Absence: odd-exponent responses never occupy the high-only range.
    always @(posedge i_clk)
        if (estimate_parity)
            assert (!(estimate > 32'h0000b000));
endmodule

module power_capped_issue_queue #(
    parameter integer DEPTH = 32
) (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_valid,
    output wire       i_ready,
    input  wire [7:0] i_activity,
    input  wire [7:0] i_budget,
    output wire       o_valid,
    input  wire       o_ready,
    output wire [7:0] o_activity,
    output wire [7:0] o_energy,
    output wire [7:0] o_throttle
);
    localparam integer PTR_W = (DEPTH > 1) ? $clog2(DEPTH) : 1;
    localparam integer COUNT_W = (DEPTH > 1) ? $clog2(DEPTH + 1) : 1;
    localparam [PTR_W-1:0] PTR_LAST = DEPTH - 1;
    localparam [COUNT_W-1:0] CAPACITY = DEPTH;
    localparam [COUNT_W:0] DEPTH_EXT = DEPTH;

    reg [7:0] activity [0:DEPTH-1];
    reg [1:0] power_cost [0:DEPTH-1];
    reg [PTR_W-1:0] rd_ptr, wr_ptr;
    reg [COUNT_W-1:0] queued;
    reg [7:0] energy, budget, throttle;

    wire [COUNT_W:0] rd_ext = rd_ptr;
    wire [COUNT_W:0] wr_ext = wr_ptr;
    wire [COUNT_W:0] tail_sum = rd_ext + {1'b0, queued};
    wire [COUNT_W:0] expected_tail = (tail_sum >= DEPTH_EXT)
                                    ? tail_sum - DEPTH_EXT : tail_sum;
    wire [PTR_W-1:0] next_rd = (rd_ptr == PTR_LAST)
                              ? {PTR_W{1'b0}} : rd_ptr + 1'b1;
    wire [PTR_W-1:0] next_wr = (wr_ptr == PTR_LAST)
                              ? {PTR_W{1'b0}} : wr_ptr + 1'b1;

    wire [1:0] incoming_cost = i_activity[7:6];
    wire [7:0] incoming_budget = (i_budget < 8'd3) ? 8'd3 : i_budget;

    // Neither interface waits for the opposite side to advertise readiness.
    // i_ce gates both handshakes and freezes every register when low.
    assign i_ready = i_ce && (queued < CAPACITY);
    assign o_valid = i_ce && (queued != 0) && (throttle == 8'd0);
    wire push = i_valid && i_ready;
    wire pop = o_valid && o_ready;

    wire [8:0] head_need = {1'b0, energy}
                           + {7'd0, power_cost[rd_ptr]};
    wire [8:0] head_excess = (head_need > {1'b0, budget})
                             ? head_need - {1'b0, budget} : 9'd0;
    wire [1:0] following_cost = (queued > 1)
                                ? power_cost[next_rd] : incoming_cost;
    wire [8:0] following_need = head_need + {7'd0, following_cost};
    wire [8:0] following_excess = (following_need > {1'b0, budget})
                                  ? following_need - {1'b0, budget} : 9'd0;
    wire [8:0] advertised_need = {1'b0, energy}
                                 + {7'd0, activity[rd_ptr][7:6]};

    assign o_activity = activity[rd_ptr];
    assign o_energy = energy;
    assign o_throttle = throttle;

    wire [DEPTH-1:0] cost_matches;
    generate
        for (genvar g = 0; g < DEPTH; g = g + 1) begin : slots
            assign cost_matches[g] = (power_cost[g] == activity[g][7:6]);
            initial begin
                activity[g] = 8'd0;
                power_cost[g] = 2'd0;
            end
            always @(posedge clk) begin
                if (push && (wr_ptr == g)) begin
                    activity[g] <= i_activity;
                    power_cost[g] <= incoming_cost;
                end
            end
        end
    endgenerate

    initial begin
        rd_ptr = {PTR_W{1'b0}};
        wr_ptr = {PTR_W{1'b0}};
        queued = {COUNT_W{1'b0}};
        energy = 8'd0;
        budget = 8'd64;
        throttle = 8'd0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (pop) begin
                rd_ptr <= next_rd;
                energy <= head_need[7:0];
                if ((queued > 1) || push)
                    throttle <= following_excess[7:0];
                else
                    throttle <= 8'd0;
            end else if ((queued != 0) && (throttle != 8'd0)) begin
                // Only actual throttle cycles dissipate energy. A ready-low
                // receiver must not cause subtraction from an idle estimate.
                energy <= energy - 8'd1;
                throttle <= throttle - 8'd1;
            end else if ((queued == 0) && push) begin
                budget <= incoming_budget;
                energy <= 8'd0;
                throttle <= 8'd0;
            end

            if (push)
                wr_ptr <= next_wr;

            case ({push, pop})
                2'b10: queued <= queued + 1'b1;
                2'b01: queued <= queued - 1'b1;
                default: queued <= queued;
            endcase
        end
    end

    // Every advertised item is affordable, including while the receiver
    // withholds ready. Valid never depends on ready.
    always @(posedge clk) begin
        if (o_valid)
            assert (advertised_need <= {1'b0, budget});
    end
endmodule

module instruction_loop_buffer #(
    parameter [31:0] DEPTH = 32'd8
) (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        i_capture_loop,
    input  wire        i_replay_request,
    input  wire [31:0] i_loop_start,
    input  wire [31:0] i_instruction,
    output reg  [31:0] instruction_out,
    output reg  [31:0] replay_pc,
    output reg         outstanding
);
    reg [31:0] instructions [32'd0:DEPTH - 32'd1];
    reg [31:0] loop_start;
    reg [31:0] loop_end;
    reg [31:0] capture_index;
    reg [31:0] replay_index;
    reg [31:0] countdown;
    reg capturing;
    reg replay_mode;
    reg armed;

    initial begin
        instruction_out = 32'd0;
        replay_pc = 32'd0;
        outstanding = 1'b0;
        loop_start = 32'd0;
        loop_end = (DEPTH - 32'd1) << 32'd2;
        capture_index = 32'd0;
        replay_index = 32'd0;
        countdown = 32'd0;
        capturing = 1'b0;
        replay_mode = 1'b0;
        armed = 1'b0;
    end

    genvar g;
    generate
        for (g = 32'd0; g < DEPTH; g = g + 32'd1) begin : initialize_entries
            initial instructions[g] = 32'd0;
        end
    endgenerate

    // A frontend selects a fixed-length backward-branching loop.
    // Capture consumes one instruction on each enabled clock.
    always @(posedge clk) begin
        if (i_ce) begin
            if (outstanding) begin
                instruction_out <= instructions[replay_index];
                countdown <= countdown - 32'd1;
                if (replay_pc == loop_end) begin
                    outstanding <= 1'b0;
                    replay_index <= 32'd0;
                end else begin
                    replay_index <= replay_index + 32'd1;
                    replay_pc <= replay_pc + 32'd4;
                end
            end else if (capturing) begin
                instructions[capture_index] <= i_instruction;
                if (capture_index == DEPTH - 32'd1) begin
                    capturing <= 1'b0;
                    replay_mode <= 1'b1;
                    // Q: the first complete loop capture permanently arms P.
                    armed <= 1'b1;
                end else begin
                    capture_index <= capture_index + 32'd1;
                end
            end else if (i_capture_loop) begin
                capturing <= 1'b1;
                replay_mode <= 1'b0;
                capture_index <= 32'd0;
                loop_start <= i_loop_start;
                loop_end <= i_loop_start + ((DEPTH - 32'd1) << 32'd2);
            end else if (replay_mode && i_replay_request) begin
                // Acceptance starts a DEPTH-enabled-cycle replay deadline.
                outstanding <= 1'b1;
                countdown <= DEPTH;
                replay_index <= 32'd0;
                replay_pc <= loop_start;
            end
        end
    end

    // After Q, a replay request must finish before its budget expires.
    assert property (!armed || !outstanding || (countdown != 32'd0));
endmodule

module accelerator_status_sequencer #(
    parameter integer DEPTH = 32,
    parameter [63:0] DWELL_TICKS = 64'd4
) (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        i_arm,
    input  wire        i_start,
    input  wire        i_loop,
    input  wire        i_end_scope,
    output reg  [63:0] leds,
    output reg         pattern_finished
);
    localparam [63:0] PATTERN_COUNT = DEPTH;
    localparam [63:0] LAST_PATTERN = PATTERN_COUNT - 64'd1;
    localparam [63:0] DWELL_RELOAD =
        (DWELL_TICKS == 64'd0) ? 64'd0 : DWELL_TICKS - 64'd1;

    localparam [1:0] PH_IDLE  = 2'b00;
    localparam [1:0] PH_ARMED = 2'b01;
    localparam [1:0] PH_RUN   = 2'b10;
    localparam [1:0] PH_DONE  = 2'b11;

    // Preloaded status-pattern table, with one valid bit per entry.
    reg [63:0] pattern_mem [0:DEPTH-1];
    reg [DEPTH-1:0] pattern_valid;
    reg [63:0] pattern_index;
    reg [63:0] dwell_count;
    reg [1:0] phase;
    reg loop_mode;
    reg arm_seen;
    reg start_seen;
    reg before_boundary;
    reg pv;

    generate
        for (genvar g = 32'd0; g < DEPTH; g = g + 32'd1) begin : init_patterns
            initial pattern_mem[g] = 64'd1 << g;
        end
    endgenerate

    initial begin
        pattern_valid = {DEPTH{1'b1}};
        pattern_index = 64'd0;
        dwell_count = 64'd0;
        phase = PH_IDLE;
        loop_mode = 1'b0;
        arm_seen = 1'b0;
        start_seen = 1'b0;
        pattern_finished = 1'b0;
        leds = 64'd0;
        before_boundary = 1'b1;
        pv = 1'b0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            pv <= 1'b1;

            // The first accepted boundary command permanently ends the scope.
            if (i_end_scope)
                before_boundary <= 1'b0;

            case (phase)
                PH_IDLE, PH_DONE: begin
                    if (i_arm && (&pattern_valid)) begin
                        phase <= PH_ARMED;
                        pattern_index <= 64'd0;
                        dwell_count <= 64'd0;
                        loop_mode <= i_loop;
                        arm_seen <= 1'b1;
                        start_seen <= 1'b0;
                        pattern_finished <= 1'b0;
                        leds <= 64'd0;
                    end
                end

                PH_ARMED: begin
                    if (i_start && pattern_valid[pattern_index]) begin
                        phase <= PH_RUN;
                        start_seen <= 1'b1;
                        dwell_count <= DWELL_RELOAD;
                        leds <= pattern_mem[pattern_index];
                    end
                end

                PH_RUN: begin
                    pattern_finished <= 1'b0;
                    if (dwell_count != 64'd0) begin
                        dwell_count <= dwell_count - 64'd1;
                    end else begin
                        // Completion of the current pattern's dwell interval.
                        pattern_finished <= 1'b1;
                        if (pattern_index == LAST_PATTERN) begin
                            if (loop_mode) begin
                                pattern_index <= 64'd0;
                                dwell_count <= DWELL_RELOAD;
                                leds <= pattern_mem[0];
                            end else begin
                                phase <= PH_DONE;
                            end
                        end else begin
                            pattern_index <= pattern_index + 64'd1;
                            dwell_count <= DWELL_RELOAD;
                            leds <= pattern_mem[pattern_index + 64'd1];
                        end
                    end
                end
            endcase
        end
    end

    // Chain precedence before the first accepted scope boundary:
    // an observed start requires arming; an observed finish requires both.
    always @(posedge clk) begin
        if (pv && before_boundary)
            assert ((!$rose(start_seen) || arm_seen) &&
                    (!$rose(pattern_finished) || (arm_seen && start_seen)));
    end
endmodule

module queued_timer_peripheral #(
    parameter integer WORD_W = 64,
    parameter integer DEPTH = 2
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  i_cmd_valid,
    output wire                  o_cmd_ready,
    input  wire [WORD_W-1:0]     i_cmd_address,
    input  wire [WORD_W-1:0]     i_cmd_data,
    input  wire                  i_execute,
    input  wire                  i_tick,
    input  wire                  i_event,
    output wire [WORD_W-1:0]     o_timer_value,
    output wire                  o_irq
);
    localparam [WORD_W-1:0] ZERO = 64'd0;
    localparam [WORD_W-1:0] ONE = 64'd1;
    localparam [WORD_W-1:0] CAPACITY = DEPTH;
    localparam [WORD_W-1:0] LAST_SLOT = CAPACITY - ONE;
    localparam [WORD_W-1:0] ADDR_LOAD = 64'd0;
    localparam [WORD_W-1:0] ADDR_COMPARE = 64'd1;
    localparam [WORD_W-1:0] ADDR_CONTROL = 64'd2;
    localparam [WORD_W-1:0] ADDR_ACK = 64'd3;

    reg [WORD_W-1:0] cmd_address [0:DEPTH-1];
    reg [WORD_W-1:0] cmd_data [0:DEPTH-1];
    reg [WORD_W-1:0] cmd_tag [0:DEPTH-1];
    reg [DEPTH-1:0] cmd_valid;
    reg [WORD_W-1:0] read_ptr;
    reg [WORD_W-1:0] write_ptr;
    reg [WORD_W-1:0] pending;
    reg [WORD_W-1:0] accepted_seq;
    reg [WORD_W-1:0] retired_seq;

    reg [WORD_W-1:0] timer_count;
    reg [WORD_W-1:0] load_reg;
    reg [WORD_W-1:0] compare_reg;
    reg [WORD_W-1:0] control_reg;
    reg irq_flag;
    reg window_open;

    wire enqueue;
    wire dequeue;
    assign o_cmd_ready = i_ce && !cmd_valid[write_ptr];
    assign enqueue = i_cmd_valid && o_cmd_ready;
    assign dequeue = i_ce && i_execute && cmd_valid[read_ptr];
    assign o_timer_value = timer_count;
    assign o_irq = irq_flag;

    // A command retains its slot until execution. Sequence tags describe
    // FIFO order independently of the occupancy accounting register.
    wire [WORD_W-1:0] valid_prefix [0:DEPTH];
    wire [WORD_W-1:0] valid_count;
    wire [WORD_W-1:0] slot_distance [0:DEPTH-1];
    wire [DEPTH-1:0] entry_shape_ok;
    wire [DEPTH-1:0] entry_tag_ok;
    wire [WORD_W-1:0] tail_position;

    assign valid_prefix[0] = ZERO;
    assign valid_count = valid_prefix[DEPTH];
    assign tail_position = ((read_ptr + pending) >= CAPACITY)
                         ? (read_ptr + pending - CAPACITY)
                         : (read_ptr + pending);

    generate
        for (genvar g = 0; g < DEPTH; g = g + 1) begin : entries
            localparam [WORD_W-1:0] SLOT = g;
            initial begin
                cmd_address[g] = ZERO;
                cmd_data[g] = ZERO;
                cmd_tag[g] = ZERO;
            end
            assign valid_prefix[g+1] = valid_prefix[g]
                + {{(WORD_W-1){1'b0}}, cmd_valid[g]};
            assign slot_distance[g] = (SLOT >= read_ptr)
                ? (SLOT - read_ptr) : (CAPACITY - read_ptr + SLOT);
            // One fill-position fact and one contents/order fact per entry.
            assign entry_shape_ok[g] =
                (cmd_valid[g] == (slot_distance[g] < pending));
            assign entry_tag_ok[g] = !cmd_valid[g]
                || (cmd_tag[g] == (retired_seq + slot_distance[g]));
        end
    endgenerate

    initial begin
        cmd_valid = {DEPTH{1'b0}};
        read_ptr = ZERO;
        write_ptr = ZERO;
        pending = ZERO;
        accepted_seq = ZERO;
        retired_seq = ZERO;
        timer_count = ZERO;
        load_reg = ZERO;
        compare_reg = ONE;
        control_reg = ZERO;
        irq_flag = 1'b0;
        window_open = 1'b0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (enqueue) begin
                cmd_address[write_ptr] <= i_cmd_address;
                cmd_data[write_ptr] <= i_cmd_data;
                cmd_tag[write_ptr] <= accepted_seq;
                cmd_valid[write_ptr] <= 1'b1;
                accepted_seq <= accepted_seq + ONE;
                write_ptr <= (write_ptr == LAST_SLOT)
                           ? ZERO : write_ptr + ONE;
            end

            if (dequeue) begin
                cmd_valid[read_ptr] <= 1'b0;
                retired_seq <= retired_seq + ONE;
                read_ptr <= (read_ptr == LAST_SLOT)
                          ? ZERO : read_ptr + ONE;
            end

            case ({enqueue, dequeue})
                2'b10: pending <= pending + ONE;
                2'b01: pending <= pending - ONE;
                default: begin end
            endcase

            // Control: bit 0 enables counting, bit 1 selects external
            // events instead of ticks, and bit 2 enables periodic reload.
            if (control_reg[0]
                && (control_reg[1] ? i_event : i_tick)) begin
                if ((timer_count + ONE) == compare_reg) begin
                    irq_flag <= 1'b1;
                    timer_count <= control_reg[2]
                                 ? load_reg : timer_count + ONE;
                end else begin
                    timer_count <= timer_count + ONE;
                end
            end

            // Executed writes take priority over ordinary timer activity.
            if (dequeue) begin
                case (cmd_address[read_ptr])
                    ADDR_LOAD: begin
                        load_reg <= cmd_data[read_ptr];
                        timer_count <= cmd_data[read_ptr];
                    end
                    ADDR_COMPARE: compare_reg <= cmd_data[read_ptr];
                    ADDR_CONTROL: begin
                        control_reg <= cmd_data[read_ptr];
                        // Q: execute an enable write. R: execute a disable
                        // write. Other commands leave the window latched.
                        window_open <= cmd_data[read_ptr][0];
                    end
                    ADDR_ACK: irq_flag <= 1'b0;
                    default: begin end
                endcase
            end
        end
    end

    assert property (!window_open || (pending <= CAPACITY));
endmodule

module matrix_stream_crc (
    input  wire                  clk,
    input  wire                  ce,
    input  wire [DATA_WIDTH-1:0]  matrix_word,
    output wire [DATA_WIDTH-1:0]  crc_out
);
    parameter integer DATA_WIDTH = 64;
    parameter integer PIPE_STAGES = 2;
    localparam integer BYTE_BITS = 8;
    localparam integer TABLE_ENTRIES = 256;
    localparam [DATA_WIDTH-1:0] CRC_POLY = 64'h42f0e1eba9ea3693;

    // DATA_WIDTH >= 8 and PIPE_STAGES >= 2.
    // Each enabled cycle consumes the low byte of the matrix-stream word.
    function automatic [DATA_WIDTH-1:0] crc_byte_serial;
        input [DATA_WIDTH-1:0] old_crc;
        input [BYTE_BITS-1:0] byte_value;
        reg [DATA_WIDTH-1:0] work;
        integer bit_number;
        begin
            work = old_crc ^
                   ({{(DATA_WIDTH-BYTE_BITS){1'b0}}, byte_value}
                    << (DATA_WIDTH-BYTE_BITS));
            for (bit_number = 0; bit_number < BYTE_BITS;
                 bit_number = bit_number + 1) begin
                if (work[DATA_WIDTH-1])
                    work = (work << 1) ^ CRC_POLY;
                else
                    work = work << 1;
            end
            crc_byte_serial = work;
        end
    endfunction

    // Fixed combinational remainder ROM, not writable sequential storage.
    wire [DATA_WIDTH-1:0] remainder_table [0:TABLE_ENTRIES-1];
    genvar t;
    generate
        for (t = 0; t < TABLE_ENTRIES; t = t + 1) begin : table_rom
            localparam [BYTE_BITS-1:0] TABLE_BYTE = t;
            assign remainder_table[t] =
                crc_byte_serial({DATA_WIDTH{1'b0}}, TABLE_BYTE);
        end
    endgenerate

    // Two-entry sequential pipelines by default. The shadows retain the
    // predecessor CRC and input word belonging to each computed remainder.
    reg [DATA_WIDTH-1:0] crc_pipe [0:PIPE_STAGES-1];
    reg [DATA_WIDTH-1:0] source_crc [0:PIPE_STAGES-1];
    reg [DATA_WIDTH-1:0] source_word [0:PIPE_STAGES-1];

    wire [BYTE_BITS-1:0] table_index;
    assign table_index = matrix_word[BYTE_BITS-1:0] ^
                         crc_pipe[0][DATA_WIDTH-1 -: BYTE_BITS];

    always @(posedge clk) begin
        if (ce) begin
            crc_pipe[0] <= (crc_pipe[0] << BYTE_BITS) ^
                           remainder_table[table_index];
            source_crc[0] <= crc_pipe[0];
            source_word[0] <= matrix_word;
        end
    end

    wire [PIPE_STAGES-2:0] prefix_consistent;
    genvar s;
    generate
        for (s = 0; s < PIPE_STAGES; s = s + 1) begin : history_pipeline
            initial begin
                crc_pipe[s] = {DATA_WIDTH{1'b0}};
                source_crc[s] = {DATA_WIDTH{1'b0}};
                source_word[s] = {DATA_WIDTH{1'b0}};
            end
            if (s > 0) begin : delayed_stage
                always @(posedge clk) begin
                    if (ce) begin
                        crc_pipe[s] <= crc_pipe[s-1];
                        source_crc[s] <= source_crc[s-1];
                        source_word[s] <= source_word[s-1];
                    end
                end
            end
            if (s < PIPE_STAGES-1) begin : prefix_check
                assign prefix_consistent[s] =
                    crc_pipe[s] == crc_byte_serial(
                        source_crc[s], source_word[s][BYTE_BITS-1:0]);
            end
        end
    endgenerate

    assign crc_out = crc_pipe[PIPE_STAGES-1];

    // A zero remainder must have been preceded by a CRC whose high byte
    // was canceled by the recorded byte, with every lower bit already zero.
    always @(*) begin
        if (crc_out == {DATA_WIDTH{1'b0}})
            assert (source_crc[PIPE_STAGES-1] ==
                    (source_word[PIPE_STAGES-1] << (DATA_WIDTH-BYTE_BITS)));
    end
endmodule

module field_power_cap #(
    parameter integer DATA_W = 128,
    parameter integer MAX_SAMPLES = 8,
    parameter integer SAMPLE_W = $clog2(MAX_SAMPLES + 1),
    parameter integer ACTIVITY_W = $clog2(MAX_SAMPLES * DATA_W + 1),
    parameter integer COST_W = $clog2(DATA_W + 1)
) (
    input  wire                  clk,
    input  wire                  i_enable,
    input  wire                  i_valid,
    output reg                   i_ready,
    input  wire [2:0]            i_cmd,
    input  wire [DATA_W-1:0]     i_data,
    output reg  [DATA_W-1:0]     energy,
    output reg  [DATA_W-1:0]     budget,
    output reg  [1:0]            throttle_level
);
    localparam [2:0] CMD_OPEN   = 3'd0;
    localparam [2:0] CMD_CLOSE  = 3'd1;
    localparam [2:0] CMD_ARM    = 3'd2;
    localparam [2:0] CMD_START  = 3'd3;
    localparam [2:0] CMD_SAMPLE = 3'd4;
    localparam [2:0] CMD_FINISH = 3'd5;

    localparam [1:0] PH_IDLE    = 2'd0;
    localparam [1:0] PH_ARMED   = 2'd1;
    localparam [1:0] PH_RUNNING = 2'd2;
    localparam [1:0] PH_DONE    = 2'd3;
    localparam [SAMPLE_W-1:0] SAMPLE_MAX = SAMPLE_W'(MAX_SAMPLES);
    localparam [SAMPLE_W-1:0] SAMPLE_ONE = SAMPLE_W'(1);
    localparam [ACTIVITY_W-1:0] ACTIVITY_MAX = ACTIVITY_W'(MAX_SAMPLES * DATA_W);

    reg window;
    reg [1:0] phase;
    reg arm_seen;
    reg start_seen;
    reg start_event;
    reg finish_event;
    reg [SAMPLE_W-1:0] sample_count;
    reg [ACTIVITY_W-1:0] activity_count;

    // A sample is a bitmap of switching field-coupled cells. Each active
    // cell contributes one energy unit to the current measurement batch.
    function automatic [COST_W-1:0] active_cells;
        input [DATA_W-1:0] bitmap;
        integer n;
        begin
            active_cells = {COST_W{1'b0}};
            for (n = 0; n < DATA_W; n = n + 1)
                active_cells = active_cells + COST_W'(bitmap[n]);
        end
    endfunction

    wire [COST_W-1:0] sample_activity = active_cells(i_data);
    wire [DATA_W-1:0] next_energy = energy + DATA_W'(sample_activity);
    wire accept = i_enable && i_valid && i_ready;

    initial begin
        window = 1'b0;
        phase = PH_IDLE;
        arm_seen = 1'b0;
        start_seen = 1'b0;
        start_event = 1'b0;
        finish_event = 1'b0;
        sample_count = {SAMPLE_W{1'b0}};
        activity_count = {ACTIVITY_W{1'b0}};
        energy = {DATA_W{1'b0}};
        budget = {DATA_W{1'b0}};
        throttle_level = 2'd1;
    end

    // Back-pressure rejects samples outside a running batch, after the
    // sample limit, or when issuing their activity would exceed the cap.
    // A nonzero throttle level stops further issue until the next batch.
    always @(*) begin
        i_ready = 1'b0;
        if (i_enable) begin
            case (i_cmd)
                CMD_OPEN:   i_ready = !window;
                CMD_CLOSE:  i_ready = window;
                CMD_ARM:    i_ready = window &&
                                      ((phase == PH_IDLE) || (phase == PH_DONE));
                CMD_START:  i_ready = window && (phase == PH_ARMED);
                CMD_SAMPLE: i_ready = window && (phase == PH_RUNNING) &&
                                      (sample_count < SAMPLE_MAX) &&
                                      (throttle_level == 2'd0) &&
                                      (next_energy <= budget);
                CMD_FINISH: i_ready = window && (phase == PH_RUNNING);
                default:    i_ready = 1'b0;
            endcase
        end
    end

    // All state changes require an accepted input item. In particular,
    // lowering i_enable freezes every register indefinitely.
    always @(posedge clk) begin
        if (accept) begin
            start_event <= 1'b0;
            finish_event <= 1'b0;
            case (i_cmd)
                CMD_OPEN, CMD_CLOSE: begin
                    window <= (i_cmd == CMD_OPEN);
                    phase <= PH_IDLE;
                    arm_seen <= 1'b0;
                    start_seen <= 1'b0;
                    sample_count <= {SAMPLE_W{1'b0}};
                    activity_count <= {ACTIVITY_W{1'b0}};
                    energy <= {DATA_W{1'b0}};
                    budget <= {DATA_W{1'b0}};
                    throttle_level <= 2'd1;
                end
                CMD_ARM: begin
                    phase <= PH_ARMED;
                    arm_seen <= 1'b1;
                    start_seen <= 1'b0;
                    sample_count <= {SAMPLE_W{1'b0}};
                    activity_count <= {ACTIVITY_W{1'b0}};
                    energy <= {DATA_W{1'b0}};
                    budget <= i_data;
                    throttle_level <= (i_data == {DATA_W{1'b0}}) ? 2'd1 : 2'd0;
                end
                CMD_START: begin
                    phase <= PH_RUNNING;
                    start_seen <= 1'b1;
                    start_event <= 1'b1;
                end
                CMD_SAMPLE: begin
                    sample_count <= sample_count + SAMPLE_ONE;
                    activity_count <= activity_count + ACTIVITY_W'(sample_activity);
                    energy <= next_energy;
                    throttle_level <= (next_energy >= budget) ? 2'd1 : 2'd0;
                end
                CMD_FINISH: begin
                    phase <= PH_DONE;
                    finish_event <= 1'b1;
                end
                default: begin end
            endcase
        end
    end

    // Between OPEN and CLOSE, START requires ARM, and FINISH requires
    // the ARM-then-START prefix of the current batch.
    always @(posedge clk) begin
        if (window) begin
            assert (!start_event || arm_seen);
            assert (!finish_event || (arm_seen && start_seen));
        end
    end
endmodule

module schmitt_ramp_monitor #(
    parameter integer DATA_W = 16
) (
    input wire clk,
    input wire i_ce,
    input wire i_config,
    input wire [DATA_W-1:0] i_upper_threshold,
    input wire i_begin_window,
    input wire i_end_window,
    output wire o_inverted,
    output wire [DATA_W-1:0] o_ramp
);
    // DATA_W must be at least two. Default thresholds are 0x4000/0xc000.
    localparam [DATA_W-1:0] ONE_CODE = {{(DATA_W-1){1'b0}}, 1'b1};
    localparam [DATA_W-1:0] LOW_CODE = {2'b01, {(DATA_W-2){1'b0}}};
    localparam [DATA_W-1:0] DEFAULT_HIGH_CODE = {2'b11, {(DATA_W-2){1'b0}}};

    reg [DATA_W-1:0] capacitor_code;
    reg [DATA_W-1:0] high_threshold;
    reg schmitt_n;
    reg window;

    wire [DATA_W-1:0] configured_high;
    wire [DATA_W-1:0] next_code;

    assign configured_high = (i_upper_threshold > LOW_CODE)
                           ? i_upper_threshold : (LOW_CODE + ONE_CODE);

    // The inverter output controls charging versus discharging.
    assign next_code = schmitt_n ? (capacitor_code + ONE_CODE)
                                 : (capacitor_code - ONE_CODE);
    assign o_inverted = schmitt_n;
    assign o_ramp = capacitor_code;

    initial begin
        capacitor_code = LOW_CODE;
        high_threshold = DEFAULT_HIGH_CODE;
        schmitt_n = 1'b1;
        window = 1'b0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            // The observation window stays open until explicitly ended.
            if (i_end_window)
                window <= 1'b0;
            else if (i_begin_window)
                window <= 1'b1;

            if (i_config) begin
                high_threshold <= configured_high;
                capacitor_code <= LOW_CODE;
                schmitt_n <= 1'b1;
            end else begin
                capacitor_code <= next_code;

                // Schmitt-trigger inverter: retain its output in the band.
                if (next_code >= high_threshold)
                    schmitt_n <= 1'b0;
                else if (next_code <= LOW_CODE)
                    schmitt_n <= 1'b1;
            end
        end
    end

    always @(posedge clk)
        if (window)
            assert (capacitor_code <= high_threshold);
endmodule

module ordered_request_arbiter #(
    parameter logic [15:0] DEPTH = 16'd16,
    parameter integer WORD_WIDTH = 16
) (
    input  wire clk,
    input  wire i_ce,
    input  wire request_valid,
    input  wire [WORD_WIDTH-1:0] requester_id,
    input  wire watch_request,
    input  wire scope_open,
    input  wire scope_close,
    output wire request_ready,
    output reg grant_valid,
    output reg [WORD_WIDTH-1:0] grant_id
);
    localparam logic [15:0] BUDGET = DEPTH + DEPTH;

    typedef enum logic [1:0] {
        ROUTE = 2'b00,
        GRANT = 2'b01
    } state_t;
    state_t state;

    reg [WORD_WIDTH-1:0] order_queue [0:DEPTH-1];
    reg [15:0] head, tail, count;
    reg [15:0] watched_slot, remaining;
    reg outstanding, deadline_expired;
    reg window, past_valid;
    integer init_index;

    wire accept_request = request_valid && request_ready;
    wire dequeue = (state == GRANT) && (count != 16'd0);
    wire watched_grant = dequeue && (head == watched_slot);

    wire [15:0] queue_distance = (watched_slot >= head)
        ? (watched_slot - head)
        : (watched_slot + DEPTH - head);
    wire [15:0] service_rank = queue_distance + queue_distance
        + ((state == GRANT) ? 16'd1 : 16'd2);

    assign request_ready = count < DEPTH;

    initial begin
        state = ROUTE;
        head = 16'd0;
        tail = 16'd0;
        count = 16'd0;
        watched_slot = 16'd0;
        remaining = 16'd0;
        outstanding = 1'b0;
        deadline_expired = 1'b0;
        window = 1'b0;
        past_valid = 1'b0;
        grant_valid = 1'b0;
        grant_id = {WORD_WIDTH{1'b0}};
        for (init_index = 0; init_index < DEPTH; init_index = init_index + 1)
            order_queue[init_index] = {WORD_WIDTH{1'b0}};
    end

    always @(posedge clk) begin
        if (i_ce) begin
            past_valid <= 1'b1;

            if (scope_close)
                window <= 1'b0;
            else if (scope_open)
                window <= 1'b1;

            case (state)
                ROUTE: state <= GRANT;
                GRANT: state <= ROUTE;
                default: state <= ROUTE;
            endcase

            grant_valid <= dequeue;
            if (dequeue) begin
                grant_id <= order_queue[head];
                head <= (head == DEPTH - 16'd1) ? 16'd0 : head + 16'd1;
            end

            if (accept_request) begin
                order_queue[tail] <= requester_id;
                tail <= (tail == DEPTH - 16'd1) ? 16'd0 : tail + 16'd1;
            end

            case ({accept_request, dequeue})
                2'b10: count <= count + 16'd1;
                2'b01: count <= count - 16'd1;
                default: count <= count;
            endcase

            // Watch one accepted request until its FIFO-ordered grant.
            // The budget counts enabled cycles, including ROUTE cycles.
            if (outstanding) begin
                if (remaining != 16'd0)
                    remaining <= remaining - 16'd1;
                if (watched_grant) begin
                    outstanding <= 1'b0;
                    deadline_expired <= 1'b0;
                end else if (remaining <= 16'd1) begin
                    deadline_expired <= 1'b1;
                end
            end else if (accept_request && watch_request) begin
                outstanding <= 1'b1;
                watched_slot <= tail;
                remaining <= BUDGET;
                deadline_expired <= 1'b0;
            end
        end
    end

    // Within the latched scope, an outstanding request must not
    // acquire an expiration while its outstanding status stays unchanged.
    always @(posedge clk)
        if (past_valid && window && outstanding && $stable(outstanding))
            assert ($stable(deadline_expired));
endmodule

module i2c_word_receiver #(
    parameter integer WORD_BITS = 64,
    parameter [WORD_BITS-1:0] SLAVE_ADDR = 64'h000000000000002a
) (
    input  wire                 clk,
    // Ordered events from a sampled I2C bus frontend.
    input  wire                 i_bus_valid,
    output wire                 o_bus_ready,
    input  wire [1:0]           i_bus_event,
    input  wire                 i_sda,
    output wire                 o_sda_drive_low,
    output wire                 o_scl_stretch,
    output wire                 o_word_valid,
    input  wire                 i_word_ready,
    output wire [WORD_BITS-1:0] o_word_data
);
    localparam [1:0] EV_START = 2'd0;
    localparam [1:0] EV_STOP  = 2'd1;
    localparam [1:0] EV_RISE  = 2'd2;
    localparam [1:0] EV_FALL  = 2'd3;

    localparam [WORD_BITS-1:0] BYTE_BITS = 64'd8;
    localparam [WORD_BITS-1:0] WORD_BYTES = WORD_BITS / 64'd8;
    localparam [WORD_BITS-1:0] ST_IDLE             = 64'd0;
    localparam [WORD_BITS-1:0] ST_ADDRESS          = 64'd1;
    localparam [WORD_BITS-1:0] ST_ADDR_ACK_SETUP   = 64'd2;
    localparam [WORD_BITS-1:0] ST_ADDR_ACK_SAMPLE  = 64'd3;
    localparam [WORD_BITS-1:0] ST_ADDR_ACK_RELEASE = 64'd4;
    localparam [WORD_BITS-1:0] ST_ARMED            = 64'd5;
    localparam [WORD_BITS-1:0] ST_DATA             = 64'd6;
    localparam [WORD_BITS-1:0] ST_DATA_ACK_SETUP   = 64'd7;
    localparam [WORD_BITS-1:0] ST_DATA_ACK_SAMPLE  = 64'd8;
    localparam [WORD_BITS-1:0] ST_DATA_ACK_RELEASE = 64'd9;
    localparam [WORD_BITS-1:0] ST_WAIT_STOP        = 64'd10;
    localparam [WORD_BITS-1:0] ST_IGNORE           = 64'd11;

    reg [WORD_BITS-1:0] state;
    reg [WORD_BITS-1:0] bit_count;
    reg [WORD_BITS-1:0] byte_count;
    reg [WORD_BITS-1:0] shift_reg;
    reg address_match;
    reg data_started;
    reg rx_valid;

    initial begin
        state         = ST_IDLE;
        bit_count     = 64'd0;
        byte_count    = 64'd0;
        shift_reg     = 64'd0;
        address_match = 1'b0;
        data_started  = 1'b0;
        rx_valid      = 1'b0;
    end

    // A pending word back-pressures the event frontend and stretches SCL.
    assign o_bus_ready = !rx_valid;
    assign o_scl_stretch = rx_valid;
    assign o_word_valid = rx_valid;
    assign o_word_data = shift_reg;
    assign o_sda_drive_low =
        (state == ST_ADDR_ACK_SAMPLE) ||
        (state == ST_ADDR_ACK_RELEASE) ||
        (state == ST_DATA_ACK_SAMPLE) ||
        (state == ST_DATA_ACK_RELEASE);

    // With i_bus_valid and i_word_ready both low, every register holds.
    always @(posedge clk) begin
        if (rx_valid && i_word_ready)
            rx_valid <= 1'b0;

        if (i_bus_valid && o_bus_ready) begin
            if (i_bus_event == EV_START) begin
                state         <= ST_ADDRESS;
                bit_count     <= 64'd0;
                byte_count    <= 64'd0;
                shift_reg     <= 64'd0;
                address_match <= 1'b0;
                data_started  <= 1'b0;
            end else if (i_bus_event == EV_STOP) begin
                state         <= ST_IDLE;
                bit_count     <= 64'd0;
                byte_count    <= 64'd0;
                shift_reg     <= 64'd0;
                address_match <= 1'b0;
                data_started  <= 1'b0;
            end else begin
                case (state)
                    ST_ADDRESS: begin
                        if (i_bus_event == EV_RISE) begin
                            shift_reg <= {shift_reg[WORD_BITS-2:0], i_sda};
                            if (bit_count == BYTE_BITS - 64'd1) begin
                                bit_count <= 64'd0;
                                // The first seven bits are the address;
                                // the eighth bit must select a write.
                                if ((shift_reg[6:0] == SLAVE_ADDR[6:0]) && !i_sda) begin
                                    address_match <= 1'b1;
                                    state <= ST_ADDR_ACK_SETUP;
                                end else begin
                                    address_match <= 1'b0;
                                    state <= ST_IGNORE;
                                end
                            end else begin
                                bit_count <= bit_count + 64'd1;
                            end
                        end
                    end
                    ST_ADDR_ACK_SETUP: begin
                        if (i_bus_event == EV_FALL)
                            state <= ST_ADDR_ACK_SAMPLE;
                    end
                    ST_ADDR_ACK_SAMPLE: begin
                        if (i_bus_event == EV_RISE)
                            state <= ST_ADDR_ACK_RELEASE;
                    end
                    ST_ADDR_ACK_RELEASE: begin
                        if (i_bus_event == EV_FALL) begin
                            state      <= ST_ARMED;
                            shift_reg  <= 64'd0;
                            bit_count  <= 64'd0;
                            byte_count <= 64'd0;
                        end
                    end
                    ST_ARMED: begin
                        if (i_bus_event == EV_RISE) begin
                            shift_reg    <= {shift_reg[WORD_BITS-2:0], i_sda};
                            bit_count    <= 64'd1;
                            data_started <= 1'b1;
                            state        <= ST_DATA;
                        end
                    end
                    ST_DATA: begin
                        if (i_bus_event == EV_RISE) begin
                            shift_reg <= {shift_reg[WORD_BITS-2:0], i_sda};
                            if (bit_count == BYTE_BITS - 64'd1) begin
                                bit_count <= 64'd0;
                                state <= ST_DATA_ACK_SETUP;
                            end else begin
                                bit_count <= bit_count + 64'd1;
                            end
                        end
                    end
                    ST_DATA_ACK_SETUP: begin
                        if (i_bus_event == EV_FALL)
                            state <= ST_DATA_ACK_SAMPLE;
                    end
                    ST_DATA_ACK_SAMPLE: begin
                        if (i_bus_event == EV_RISE)
                            state <= ST_DATA_ACK_RELEASE;
                    end
                    ST_DATA_ACK_RELEASE: begin
                        if (i_bus_event == EV_FALL) begin
                            if (byte_count == WORD_BYTES - 64'd1) begin
                                rx_valid <= 1'b1;
                                state <= ST_WAIT_STOP;
                            end else begin
                                byte_count <= byte_count + 64'd1;
                                state <= ST_DATA;
                            end
                        end
                    end
                    default: begin
                        // IDLE, IGNORE and WAIT_STOP await START or STOP.
                    end
                endcase
            end
        end
    end

    // Global chain precedence: address arm precedes data start,
    // and data start precedes completed-word publication.
    always @(posedge clk)
        assert (!(data_started || rx_valid) ||
                (address_match && (!rx_valid || data_started)));
endmodule

module uart_baud_event_timer #(
    parameter integer WIDTH = 32,
    parameter [WIDTH-1:0] RESET_COMPARE = 32'd8
) (
    input  wire                 clk,
    input  wire                 rst,
    input  wire                 i_ce,
    input  wire                 i_tick,
    input  wire                 i_write,
    input  wire [1:0]           i_addr,
    input  wire [WIDTH-1:0]     i_wdata,
    output wire [WIDTH-1:0]     o_count,
    output wire                 o_running,
    output wire                 o_irq
);
    localparam [WIDTH-1:0] ZERO = {WIDTH{1'b0}};
    localparam [WIDTH-1:0] ONE = {{(WIDTH-1){1'b0}}, 1'b1};

    reg [WIDTH-1:0] counter;
    reg [WIDTH-1:0] counter_inv;
    reg [WIDTH-1:0] load_reg;
    reg [WIDTH-1:0] compare_reg;
    reg [WIDTH-1:0] control_reg;
    reg irq;

    wire [WIDTH-1:0] forward_next = counter + ONE;
    wire [WIDTH-1:0] inverse_next = counter_inv - ONE;

    initial begin
        counter = ZERO;
        counter_inv = ~ZERO;
        load_reg = ZERO;
        compare_reg = RESET_COMPARE;
        control_reg = ZERO;
        irq = 1'b0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (rst) begin
                counter <= ZERO;
                counter_inv <= ~ZERO;
                load_reg <= ZERO;
                compare_reg <= RESET_COMPARE;
                control_reg <= ZERO;
                irq <= 1'b0;
            end else if (i_write) begin
                // Programming acknowledges any previous interrupt.
                irq <= 1'b0;
                case (i_addr)
                    2'b00: load_reg <= i_wdata;
                    2'b01: compare_reg <= i_wdata;
                    2'b10: control_reg <= i_wdata;
                    2'b11: begin
                        if (i_wdata[0]) begin
                            counter <= load_reg;
                            counter_inv <= ~load_reg;
                        end
                    end
                endcase
            end else if (i_tick && control_reg[0] && !irq) begin
                counter <= forward_next;
                counter_inv <= inverse_next;

                // Independent terminal paths stop the timer and raise IRQ.
                if (forward_next == compare_reg)
                    control_reg[0] <= 1'b0;
                if (inverse_next == ~compare_reg)
                    irq <= 1'b1;
            end
        end
    end

    assign o_count = counter;
    assign o_running = control_reg[0];
    assign o_irq = irq;

    always @(posedge clk) assert (!(irq && control_reg[0]));
endmodule

module activation_clamp_deadline #(
    parameter integer DATA_WIDTH = 32,
    parameter integer MAX_CYCLES = 4
) (
    input wire clk,
    input wire rst_n,
    input wire i_ce,
    input wire in_valid,
    output wire in_ready,
    input wire [DATA_WIDTH-1:0] in_data,
    input wire [DATA_WIDTH-1:0] in_lower,
    input wire [DATA_WIDTH-1:0] in_upper,
    output wire out_valid,
    input wire out_ready,
    output reg [DATA_WIDTH-1:0] result,
    output reg clipped
);
    localparam integer BUDGET = (MAX_CYCLES < 2) ? 2 : MAX_CYCLES;
    localparam integer COUNT_WIDTH = $clog2(BUDGET + 1);

    reg [DATA_WIDTH-1:0] lower_limit;
    reg [DATA_WIDTH-1:0] upper_limit;
    reg [COUNT_WIDTH-1:0] countdown;
    reg outstanding;
    reg output_pending;

    wire accept;
    assign in_ready = i_ce && !outstanding && !output_pending;
    assign accept = in_valid && in_ready;

    // Suppress interface transfers while the entire engine is disabled.
    assign out_valid = i_ce && output_pending;

    initial begin
        lower_limit = {DATA_WIDTH{1'b0}};
        upper_limit = {DATA_WIDTH{1'b0}};
        result = {DATA_WIDTH{1'b0}};
        clipped = 1'b0;
        countdown = {COUNT_WIDTH{1'b0}};
        outstanding = 1'b0;
        output_pending = 1'b0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            lower_limit <= {DATA_WIDTH{1'b0}};
            upper_limit <= {DATA_WIDTH{1'b0}};
            result <= {DATA_WIDTH{1'b0}};
            clipped <= 1'b0;
            countdown <= {COUNT_WIDTH{1'b0}};
            outstanding <= 1'b0;
            output_pending <= 1'b0;
        end else if (i_ce) begin
            if (accept) begin
                if (in_lower <= in_upper) begin
                    lower_limit <= in_lower;
                    upper_limit <= in_upper;
                end else begin
                    lower_limit <= in_upper;
                    upper_limit <= in_lower;
                end
                result <= in_data;
                clipped <= 1'b0;
                countdown <= BUDGET;
                outstanding <= 1'b1;
            end else if (outstanding) begin
                // Internal service never waits for downstream readiness.
                if (countdown != 0)
                    countdown <= countdown - 1'b1;

                if (result < lower_limit) begin
                    result <= lower_limit;
                    clipped <= 1'b1;
                end else if (result > upper_limit) begin
                    result <= upper_limit;
                    clipped <= 1'b1;
                end else begin
                    outstanding <= 1'b0;
                    countdown <= {COUNT_WIDTH{1'b0}};
                    output_pending <= 1'b1;
                end
            end else if (output_pending && out_ready) begin
                // Only retirement of an already-valid output needs ready.
                output_pending <= 1'b0;
            end
        end
    end

    always @(posedge clk) begin
        if (outstanding)
            assert (countdown != 0);
    end
endmodule

module led_pattern_sequencer #(
    parameter integer DATA_WIDTH = 128,
    parameter integer PATTERNS = 4,
    parameter integer DWELL_CONFIG_WIDTH = 2
) (
    input wire clk,
    input wire i_ce,
    input wire start,
    input wire stop,
    input wire config_load,
    input wire [DWELL_CONFIG_WIDTH-1:0] dwell_config_in,
    input wire loop_mode_in,
    input wire pattern_write,
    input wire [((PATTERNS > 1) ? $clog2(PATTERNS) : 1)-1:0] write_index,
    input wire [DATA_WIDTH-1:0] pattern_data,
    output wire [DATA_WIDTH-1:0] leds
);
    localparam integer INDEX_WIDTH = (PATTERNS > 1) ? $clog2(PATTERNS) : 1;
    localparam integer DWELL_WIDTH = DWELL_CONFIG_WIDTH + 1;
    localparam [INDEX_WIDTH-1:0] LAST_PATTERN = INDEX_WIDTH'(PATTERNS - 1);
    localparam [DWELL_WIDTH-1:0] DWELL_ONE = DWELL_WIDTH'(1);
    localparam [DWELL_WIDTH-1:0] DWELL_BOUND = {1'b1, {DWELL_CONFIG_WIDTH{1'b0}}};

    reg [DATA_WIDTH-1:0] pattern_mem [0:PATTERNS-1];
    reg [INDEX_WIDTH-1:0] pattern_index;
    reg [DWELL_WIDTH-1:0] dwell_count;
    reg [DWELL_WIDTH-1:0] dwell_left;
    reg [DWELL_CONFIG_WIDTH-1:0] dwell_config;
    reg loop_mode;
    reg running;
    reg window_open;

    wire [DWELL_WIDTH-1:0] configured_dwell =
        {1'b0, dwell_config} + DWELL_ONE;
    assign leds = pattern_mem[pattern_index];

    initial begin
        for (integer n = 0; n < PATTERNS; n = n + 1) begin
            pattern_mem[n] = {{(DATA_WIDTH-1){1'b0}}, 1'b1} << n;
        end
        pattern_index = {INDEX_WIDTH{1'b0}};
        dwell_config = {DWELL_CONFIG_WIDTH{1'b1}};
        dwell_count = {DWELL_WIDTH{1'b0}};
        dwell_left = DWELL_BOUND;
        loop_mode = 1'b0;
        running = 1'b0;
        window_open = 1'b0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (pattern_write && write_index <= LAST_PATTERN)
                pattern_mem[write_index] <= pattern_data;

            // The observation window starts at start and ends only at stop.
            if (stop)
                window_open <= 1'b0;
            else if (start)
                window_open <= 1'b1;

            if (config_load) begin
                dwell_config <= dwell_config_in;
                loop_mode <= loop_mode_in;
                pattern_index <= {INDEX_WIDTH{1'b0}};
                dwell_count <= {DWELL_WIDTH{1'b0}};
                dwell_left <= {1'b0, dwell_config_in} + DWELL_ONE;
                running <= 1'b0;
            end else if (stop) begin
                running <= 1'b0;
            end else if (start) begin
                pattern_index <= {INDEX_WIDTH{1'b0}};
                dwell_count <= {DWELL_WIDTH{1'b0}};
                dwell_left <= configured_dwell;
                running <= 1'b1;
            end else if (running) begin
                if (dwell_left != {DWELL_WIDTH{1'b0}}) begin
                    dwell_left <= dwell_left - DWELL_ONE;
                    dwell_count <= dwell_count + DWELL_ONE;
                end else if (pattern_index == LAST_PATTERN) begin
                    if (loop_mode) begin
                        pattern_index <= {INDEX_WIDTH{1'b0}};
                        dwell_count <= {DWELL_WIDTH{1'b0}};
                        dwell_left <= configured_dwell;
                    end else begin
                        running <= 1'b0;
                    end
                end else begin
                    pattern_index <= pattern_index + INDEX_WIDTH'(1);
                    dwell_count <= {DWELL_WIDTH{1'b0}};
                    dwell_left <= configured_dwell;
                end
            end
        end
    end

    always @(*) begin
        if (window_open)
            assert (dwell_count <= DWELL_BOUND);
    end
endmodule

module rsqrt_seed_sequencer #(
    parameter integer WORD_W = 16,
    parameter integer TABLE_ENTRIES = 32
) (
    input  wire                  clk,
    input  wire                  rst_n,
    input  wire                  ce,
    input  wire                  q_event,
    input  wire                  arm_req,
    input  wire                  start_req,
    input  wire                  finish_req,
    input  wire [WORD_W-1:0]     exponent,
    input  wire [WORD_W-1:0]     significand,
    output reg  [WORD_W-1:0]     estimate,
    output reg                   start_pulse,
    output reg                   finish_pulse
);
    // TABLE_ENTRIES is a power of two. The default uses parity plus
    // four leading fractional significand bits as its ROM address.
    localparam integer INDEX_W = $clog2(TABLE_ENTRIES);
    localparam [WORD_W-1:0] PH_IDLE    = 16'd0;
    localparam [WORD_W-1:0] PH_ARMED   = 16'd1;
    localparam [WORD_W-1:0] PH_RUNNING = 16'd2;
    localparam [WORD_W-1:0] PH_DONE    = 16'd3;

    reg [WORD_W-1:0] seed_rom [0:TABLE_ENTRIES-1];
    reg [WORD_W-1:0] phase;
    reg [WORD_W-1:0] table_index;
    reg scope_armed;
    reg arm_seen;
    reg start_seen;

    // Quantized Q1.15 reciprocal-square-root seeds. The upper half
    // includes the additional factor 1/sqrt(2) for odd exponents.
    function automatic [WORD_W-1:0] seed_word;
        input integer row;
        integer scaled_row;
        begin
            scaled_row = (row * 16'd32) / TABLE_ENTRIES;
            case (scaled_row)
                16'd0:  seed_word = 16'h8000;
                16'd1:  seed_word = 16'h7c00;
                16'd2:  seed_word = 16'h7900;
                16'd3:  seed_word = 16'h7500;
                16'd4:  seed_word = 16'h7200;
                16'd5:  seed_word = 16'h7000;
                16'd6:  seed_word = 16'h6d00;
                16'd7:  seed_word = 16'h6b00;
                16'd8:  seed_word = 16'h6900;
                16'd9:  seed_word = 16'h6600;
                16'd10: seed_word = 16'h6400;
                16'd11: seed_word = 16'h6300;
                16'd12: seed_word = 16'h6100;
                16'd13: seed_word = 16'h5f00;
                16'd14: seed_word = 16'h5d00;
                16'd15: seed_word = 16'h5c00;
                16'd16: seed_word = 16'h5b00;
                16'd17: seed_word = 16'h5800;
                16'd18: seed_word = 16'h5500;
                16'd19: seed_word = 16'h5300;
                16'd20: seed_word = 16'h5100;
                16'd21: seed_word = 16'h4f00;
                16'd22: seed_word = 16'h4d00;
                16'd23: seed_word = 16'h4b00;
                16'd24: seed_word = 16'h4a00;
                16'd25: seed_word = 16'h4800;
                16'd26: seed_word = 16'h4700;
                16'd27: seed_word = 16'h4600;
                16'd28: seed_word = 16'h4400;
                16'd29: seed_word = 16'h4300;
                16'd30: seed_word = 16'h4200;
                default: seed_word = 16'h4100;
            endcase
        end
    endfunction

    // Immutable ROM: every stored word has an initial value.
    genvar row;
    generate
        for (row = 0; row < TABLE_ENTRIES; row = row + 1) begin : initialize_rom
            initial seed_rom[row] = seed_word(row);
        end
    endgenerate

    initial begin
        phase        = PH_IDLE;
        table_index  = 16'd0;
        estimate     = 16'h8000;
        scope_armed  = 1'b0;
        arm_seen     = 1'b0;
        start_seen   = 1'b0;
        start_pulse  = 1'b0;
        finish_pulse = 1'b0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            phase        <= PH_IDLE;
            table_index  <= 16'd0;
            estimate     <= 16'h8000;
            scope_armed  <= 1'b0;
            arm_seen     <= 1'b0;
            start_seen   <= 1'b0;
            start_pulse  <= 1'b0;
            finish_pulse <= 1'b0;
        end else if (ce) begin
            // Q is an enabled context-open event; its scope is sticky.
            scope_armed  <= scope_armed || q_event;
            start_pulse  <= 1'b0;
            finish_pulse <= 1'b0;

            case (phase)
                PH_IDLE, PH_DONE: begin
                    if (arm_req) begin
                        // Arm locks the lookup address for this transaction.
                        table_index <= {{(WORD_W-INDEX_W){1'b0}},
                                        exponent[0],
                                        significand[WORD_W-2 -: (INDEX_W-1)]};
                        arm_seen   <= 1'b1;
                        start_seen <= 1'b0;
                        phase      <= PH_ARMED;
                    end
                end
                PH_ARMED: begin
                    if (start_req) begin
                        // Start performs the registered ROM read.
                        estimate    <= seed_rom[table_index];
                        start_seen  <= 1'b1;
                        start_pulse <= 1'b1;
                        phase       <= PH_RUNNING;
                    end
                end
                PH_RUNNING: begin
                    if (finish_req) begin
                        // Finish publishes completion of the seed operation.
                        finish_pulse <= 1'b1;
                        phase        <= PH_DONE;
                    end
                end
                default: begin
                    phase <= PH_IDLE;
                end
            endcase
        end
    end

    // Chain precedence after Q: arm precedes either later step,
    // and start additionally precedes finish.
    always @(posedge clk) begin
        if (scope_armed) begin
            assert (!(start_pulse || finish_pulse) || arm_seen);
            assert (!finish_pulse || start_seen);
        end
    end
endmodule

module move_score_snapshot_queue #(
    parameter integer DEPTH = 16,
    parameter integer WIDTH = 16
) (
    input  wire                 clk,
    input  wire                 i_score_valid,
    output wire                 o_score_ready,
    input  wire [WIDTH-1:0]     i_score_delta,
    input  wire                 i_request_valid,
    output wire                 o_request_ready,
    output wire                 o_report_valid,
    input  wire                 i_report_ready,
    output wire [WIDTH-1:0]     o_report_data
);
    localparam [WIDTH-1:0] ZERO = {WIDTH{1'b0}};
    localparam [WIDTH-1:0] ONE = {{(WIDTH-1){1'b0}}, 1'b1};
    localparam [WIDTH-1:0] DEPTH_WORD = DEPTH;
    localparam [WIDTH-1:0] LAST = DEPTH_WORD - ONE;
    localparam [WIDTH:0] DEPTH_EXT = DEPTH;

    reg [WIDTH-1:0] source_score;
    reg [WIDTH-1:0] snapshot_score;
    reg [WIDTH-1:0] capture_shadow;

    reg request_toggle;
    reg request_meta;
    reg request_sync;
    reg completion_toggle;
    reg completion_meta;
    reg completion_sync;
    reg busy;

    reg [WIDTH-1:0] report_mem [0:DEPTH-1];
    reg [WIDTH-1:0] earlier_mem [0:DEPTH-1];
    reg [DEPTH-1:0] filled;
    reg [WIDTH-1:0] read_ptr;
    reg [WIDTH-1:0] write_ptr;
    reg [WIDTH-1:0] used;
    reg window;
    reg pv;

    wire [DEPTH-1:0] occupied;
    wire [WIDTH-1:0] prior_value;

    // Common-clock abstraction of enabled source and destination domains.
    // With these three handshake-driving inputs low, every register holds.
    wire advance = i_score_valid || i_request_valid || i_report_ready;

    assign o_score_ready = 1'b1;
    assign o_request_ready = !busy && (used < DEPTH_WORD);
    assign o_report_valid = (used != ZERO);
    assign o_report_data = report_mem[read_ptr];
    assign prior_value = earlier_mem[read_ptr];

    wire request_fire = i_request_valid && o_request_ready;
    wire pop = o_report_valid && i_report_ready;
    wire publish = busy && (completion_sync == request_toggle);

    function automatic [WIDTH-1:0] next_ptr;
        input [WIDTH-1:0] ptr;
        begin
            next_ptr = (ptr == LAST) ? ZERO : ptr + ONE;
        end
    endfunction

    genvar g;
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin : occupancy_decode
            localparam [WIDTH:0] SLOT = g;
            assign occupied[g] = (used != ZERO) &&
                ((SLOT >= {1'b0, read_ptr}) ?
                    ((SLOT - {1'b0, read_ptr}) < {1'b0, used}) :
                    ((SLOT + DEPTH_EXT - {1'b0, read_ptr}) < {1'b0, used}));
        end
    endgenerate

    integer k;
    initial begin
        source_score = ZERO;
        snapshot_score = ZERO;
        capture_shadow = ZERO;
        request_toggle = 1'b0;
        request_meta = 1'b0;
        request_sync = 1'b0;
        completion_toggle = 1'b0;
        completion_meta = 1'b0;
        completion_sync = 1'b0;
        busy = 1'b0;
        filled = {DEPTH{1'b0}};
        read_ptr = ZERO;
        write_ptr = ZERO;
        used = ZERO;
        window = 1'b0;
        pv = 1'b0;
        for (k = 0; k < DEPTH; k = k + 1) begin
            report_mem[k] = ZERO;
            earlier_mem[k] = ZERO;
        end
    end

    always @(posedge clk) begin
        if (advance) begin
            pv <= 1'b1;

            if (i_score_valid && o_score_ready)
                source_score <= source_score + i_score_delta;

            // Destination launches one request and reserves a free FIFO slot.
            if (request_fire) begin
                request_toggle <= !request_toggle;
                busy <= 1'b1;
            end else if (publish) begin
                busy <= 1'b0;
            end

            // Request synchronizer and source-domain capture.
            request_meta <= request_toggle;
            request_sync <= request_meta;
            if (request_sync != completion_toggle) begin
                snapshot_score <= source_score;
                capture_shadow <= source_score;
                completion_toggle <= request_sync;
            end

            // The completion crosses back only after the snapshot is frozen.
            completion_meta <= completion_toggle;
            completion_sync <= completion_meta;

            if (pop) begin
                filled[read_ptr] <= 1'b0;
                read_ptr <= next_ptr(read_ptr);
            end
            if (publish) begin
                report_mem[write_ptr] <= snapshot_score;
                // Shadow provenance from the earlier source capture event.
                earlier_mem[write_ptr] <= capture_shadow;
                filled[write_ptr] <= 1'b1;
                write_ptr <= next_ptr(write_ptr);
            end

            case ({publish, pop})
                2'b10: used <= used + ONE;
                2'b01: used <= used - ONE;
                default: used <= used;
            endcase

            // Q: accepted request. R: final report consumed with no work pending.
            // Another accepted request can reopen the scope after it closes.
            if (request_fire)
                window <= 1'b1;
            else if (pop && (used == ONE) && !busy)
                window <= 1'b0;
        end
    end

    // A newly visible report must match its earlier source-capture value.
    always @(posedge clk)
        if (pv && window && $rose(o_report_valid))
            assert (o_report_data == prior_value);
endmodule

module interleaved_fetch_scheduler #(
    parameter [15:0] THREADS = 16'd24
) (
    input  wire        clk,
    input  wire        command_valid,
    output wire        command_ready,
    input  wire [1:0]  command_op,
    input  wire [15:0] command_tid,
    input  wire        fetch_valid,
    output wire        fetch_ready,
    output wire        issue_valid,
    input  wire        issue_ready,
    output reg  [15:0] issue_tid,
    output reg  [15:0] issue_pc
);
    typedef enum logic [1:0] {
        SCAN  = 2'b00,
        OFFER = 2'b01
    } state_t;

    localparam [1:0] CMD_OPEN  = 2'b00;
    localparam [1:0] CMD_CLOSE = 2'b01;
    localparam [1:0] CMD_WAKE  = 2'b10;
    localparam [1:0] CMD_SLEEP = 2'b11;

    state_t state;
    reg [15:0] rr_ptr;
    reg [15:0] thread_pc [0:THREADS-16'd1];
    reg [THREADS-16'd1:0] thread_ready;
    reg scope_active;
    reg past_valid;

    reg found;
    reg [15:0] selected_tid;
    reg [15:0] scan_offset;
    reg [15:0] scan_index;

    initial begin
        state = SCAN;
        rr_ptr = 16'd0;
        issue_tid = 16'd0;
        issue_pc = 16'd0;
        thread_ready = {THREADS{1'b1}};
        scope_active = 1'b0;
        past_valid = 1'b0;
    end

    genvar t;
    generate
        for (t = 0; t < THREADS; t = t + 1) begin : initialize_pcs
            initial thread_pc[t] = 16'd0;
        end
    endgenerate

    // Rotating priority selection among runnable hardware threads.
    always @(*) begin
        found = 1'b0;
        selected_tid = 16'd0;
        scan_index = 16'd0;
        for (scan_offset = 16'd0;
             scan_offset < THREADS;
             scan_offset = scan_offset + 16'd1) begin
            scan_index = rr_ptr + scan_offset;
            if (scan_index >= THREADS)
                scan_index = scan_index - THREADS;
            if (!found && thread_ready[scan_index]) begin
                found = 1'b1;
                selected_tid = scan_index;
            end
        end
    end

    // Commands have priority over new fetch requests. Readiness cannot
    // change while an offered instruction is waiting for its consumer.
    assign command_ready = (state == SCAN) && (command_tid < THREADS);
    assign fetch_ready = (state == SCAN) && !command_valid && found;
    assign issue_valid = (state == OFFER);

    wire command_fire = command_valid && command_ready;
    wire fetch_fire = fetch_valid && fetch_ready;
    wire issue_fire = issue_valid && issue_ready;

    always @(posedge clk) begin
        if (command_fire) begin
            past_valid <= 1'b1;
            case (command_op)
                CMD_OPEN:  scope_active <= 1'b1;
                CMD_CLOSE: scope_active <= 1'b0;
                CMD_WAKE:  thread_ready[command_tid] <= 1'b1;
                CMD_SLEEP: thread_ready[command_tid] <= 1'b0;
            endcase
        end else if (fetch_fire) begin
            past_valid <= 1'b1;
            issue_tid <= selected_tid;
            issue_pc <= thread_pc[selected_tid];
            state <= OFFER;
        end else if (issue_fire) begin
            past_valid <= 1'b1;
            thread_pc[issue_tid] <= issue_pc + 16'd1;
            if (issue_tid == THREADS - 16'd1)
                rr_ptr <= 16'd0;
            else
                rr_ptr <= issue_tid + 16'd1;
            state <= SCAN;
        end
    end

    // Between OPEN and CLOSE, thread zero cannot simultaneously remain
    // asleep and make architectural fetch progress.
    always @(posedge clk)
        if (past_valid && scope_active && !thread_ready[0] &&
            $stable(thread_ready[0]))
            assert ($stable(thread_pc[0]));
endmodule

module memory_link_schmitt_tags #(
    parameter integer DATA_WIDTH = 128,
    parameter [DATA_WIDTH-1:0] LOW_TRIP  = DATA_WIDTH'(32),
    parameter [DATA_WIDTH-1:0] HIGH_TRIP = DATA_WIDTH'(96)
) (
    input  wire                  clk,
    input  wire                  rst_n,
    input  wire                  s_valid,
    output wire                  s_ready,
    input  wire [DATA_WIDTH-1:0] s_data,
    output reg                   m_valid,
    input  wire                  m_ready,
    output reg  [DATA_WIDTH-1:0] m_data,
    output reg                   sleep_hint,
    output reg                   stretch_hint
);
    // Sampled Schmitt-trigger inverter: retain the output in the deadband.
    reg schmitt_n;
    reg last_above_high;
    reg armed;

    // One-word output buffer, with replacement on simultaneous retirement.
    assign s_ready = !m_valid || m_ready;

    initial begin
        schmitt_n       = 1'b1;
        last_above_high = 1'b0;
        armed           = 1'b0;
        m_valid         = 1'b0;
        m_data          = {DATA_WIDTH{1'b0}};
        sleep_hint      = 1'b0;
        stretch_hint    = 1'b0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            schmitt_n       <= 1'b1;
            last_above_high <= 1'b0;
            armed           <= 1'b0;
            m_valid         <= 1'b0;
            m_data          <= {DATA_WIDTH{1'b0}};
            sleep_hint      <= 1'b0;
            stretch_hint    <= 1'b0;
        end else begin
            if (s_valid && s_ready) begin
                m_valid <= 1'b1;
                m_data  <= s_data;
                armed   <= 1'b1;

                // Tag this transfer using the previous accepted measurement.
                sleep_hint   <= schmitt_n;
                stretch_hint <= last_above_high;

                last_above_high <= (s_data >= HIGH_TRIP);
                if (s_data >= HIGH_TRIP)
                    schmitt_n <= 1'b0;
                else if (s_data <= LOW_TRIP)
                    schmitt_n <= 1'b1;
            end else if (m_valid && m_ready) begin
                m_valid <= 1'b0;
            end
        end
    end

    // After the first accepted measurement, incompatible hints never coexist.
    always @(*) begin
        if (armed)
            assert (!(sleep_hint && stretch_hint));
    end
endmodule

module waveform_scale_pipeline #(
    parameter integer DATA_BITS = 32'd32,
    parameter integer LUT_ENTRIES = 32'd32,
    parameter [DATA_BITS-1:0] COEFF = 32'd3
) (
    input wire clk,
    input wire i_ce,
    input wire i_open,
    input wire i_close,
    input wire i_request,
    input wire [DATA_BITS-1:0] i_sample,
    output reg result_valid,
    output reg [DATA_BITS-1:0] result_data
);
    localparam integer NIBBLE_BITS = 32'd4;
    localparam integer TABLE_SIZE = 32'd16;
    localparam integer LUT_BANKS = LUT_ENTRIES / TABLE_SIZE;
    localparam integer LANES = DATA_BITS / NIBBLE_BITS;

    // Two 16-entry multiple tables occupy the default 32-entry array.
    // Alternating nibble lanes use alternating banks.
    reg [DATA_BITS-1:0] multiples [0:LUT_ENTRIES-1];
    reg [LUT_ENTRIES-1:0] lut_valid;

    genvar entry;
    generate
        for (entry = 32'd0; entry < LUT_ENTRIES; entry = entry + 32'd1) begin : init_tables
            localparam [DATA_BITS-1:0] DIGIT = entry % TABLE_SIZE;
            initial begin
                multiples[entry] = COEFF * DIGIT;
                lut_valid[entry] = 1'b1;
            end
        end
    endgenerate

    reg [DATA_BITS-1:0] lookup_sum;
    integer lane;
    always @(*) begin
        lookup_sum = {DATA_BITS{1'b0}};
        for (lane = 32'd0; lane < LANES; lane = lane + 32'd1) begin
            lookup_sum = lookup_sum +
                (multiples[((lane % LUT_BANKS) * TABLE_SIZE) +
                           i_sample[lane*NIBBLE_BITS +: NIBBLE_BITS]]
                 << (lane * NIBBLE_BITS));
        end
    end

    wire tables_ready = &lut_valid;
    reg window_open;
    reg stage_valid;
    reg [DATA_BITS-1:0] stage_sum;
    reg [DATA_BITS-1:0] accepted_operand;
    reg [DATA_BITS-1:0] retired_operand_shadow;

    initial begin
        window_open = 1'b0;
        stage_valid = 1'b0;
        stage_sum = 32'd0;
        accepted_operand = 32'd0;
        result_valid = 1'b0;
        result_data = 32'd0;
        retired_operand_shadow = 32'd0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            // Closing has priority; later openings can start another window.
            if (i_close)
                window_open <= 1'b0;
            else if (i_open)
                window_open <= 1'b1;

            // The adder stage accepts one sample per enabled cycle.
            stage_valid <= i_request && tables_ready;
            if (i_request && tables_ready) begin
                stage_sum <= lookup_sum;
                accepted_operand <= i_sample;
            end

            // Retire the previous enabled cycle's accepted sample.
            result_valid <= stage_valid;
            if (stage_valid) begin
                result_data <= stage_sum;
                retired_operand_shadow <= accepted_operand;
            end
        end
    end

    // During an open window, every observed completion must agree with
    // the shadow of the sample accepted at an earlier enabled edge.
    // Products are modulo 2**DATA_BITS, matching the datapath width.
    assert property (!(window_open && result_valid) ||
                     result_data == (retired_operand_shadow * COEFF));
endmodule

module fpga_job_fifo_arbiter #(
    parameter integer DATA_WIDTH = 128,
    parameter integer DEPTH = 24,
    parameter integer REQUESTERS = 4,
    parameter integer ID_W = (REQUESTERS > 1) ? $clog2(REQUESTERS) : 1,
    parameter integer PTR_W = (DEPTH > 1) ? $clog2(DEPTH) : 1,
    parameter integer COUNT_W = $clog2(DEPTH + 1)
) (
    input wire clk,
    input wire [REQUESTERS-1:0] request_valid,
    output reg [REQUESTERS-1:0] request_ready,
    input wire [REQUESTERS*DATA_WIDTH-1:0] request_data,
    input wire [REQUESTERS-1:0] scope_begin,
    input wire [REQUESTERS-1:0] scope_end,
    output wire grant_valid,
    input wire grant_ready,
    output wire [ID_W-1:0] grant_id,
    output wire [DATA_WIDTH-1:0] grant_data
);
    localparam [COUNT_W-1:0] CAPACITY = COUNT_W'(DEPTH);
    localparam [PTR_W-1:0] LAST_PTR = PTR_W'(DEPTH - 1);
    localparam [COUNT_W:0] REL_DEPTH = (COUNT_W+1)'(DEPTH);

    reg [ID_W-1:0] order_queue [0:DEPTH-1];
    reg [DATA_WIDTH-1:0] job_queue [0:DEPTH-1];
    reg [PTR_W-1:0] head, tail;
    reg [COUNT_W-1:0] used;
    reg scope_active;

    reg selected_valid;
    reg [ID_W-1:0] selected_id;
    integer select_index;
    integer init_index;

    function automatic [PTR_W-1:0] advance_ptr;
        input [PTR_W-1:0] ptr;
        begin
            if (ptr == LAST_PTR)
                advance_ptr = {PTR_W{1'b0}};
            else
                advance_ptr = ptr + PTR_W'(1);
        end
    endfunction

    initial begin
        head = {PTR_W{1'b0}};
        tail = {PTR_W{1'b0}};
        used = {COUNT_W{1'b0}};
        scope_active = 1'b0;
        for (init_index = 0; init_index < DEPTH; init_index = init_index + 1) begin
            order_queue[init_index] = {ID_W{1'b0}};
            job_queue[init_index] = {DATA_WIDTH{1'b0}};
        end
    end

    // Admit at most one requester per cycle. Simultaneous offers use
    // requester-number priority; accepted arrivals are serviced FIFO.
    always @* begin
        selected_valid = 1'b0;
        selected_id = {ID_W{1'b0}};
        request_ready = {REQUESTERS{1'b0}};
        for (select_index = 0; select_index < REQUESTERS; select_index = select_index + 1) begin
            if (!selected_valid && request_valid[select_index]) begin
                selected_valid = 1'b1;
                selected_id = ID_W'(select_index);
            end
        end
        if (selected_valid && used < CAPACITY)
            request_ready[selected_id] = 1'b1;
    end

    wire enqueue = |(request_valid & request_ready);
    assign grant_valid = (used != {COUNT_W{1'b0}});
    wire dequeue = grant_valid && grant_ready;
    assign grant_id = order_queue[head];
    assign grant_data = job_queue[head];

    always @(posedge clk) begin
        if (enqueue) begin
            order_queue[tail] <= selected_id;
            job_queue[tail] <= request_data[selected_id*DATA_WIDTH +: DATA_WIDTH];
            tail <= advance_ptr(tail);

            // Q: accepted scope-begin marker. R: accepted scope-end
            // marker, with closing taking priority if both are present.
            if (scope_end[selected_id])
                scope_active <= 1'b0;
            else if (scope_begin[selected_id])
                scope_active <= 1'b1;
        end

        if (dequeue)
            head <= advance_ptr(head);

        case ({enqueue, dequeue})
            2'b10: used <= used + COUNT_W'(1);
            2'b01: used <= used - COUNT_W'(1);
            default: used <= used;
        endcase
    end

    // While the scope is open, pointer coincidence denotes exactly
    // the empty and full states, never an intermediate occupancy.
    always @(posedge clk)
        assert (!scope_active ||
                ((head == tail) ==
                 ((used == {COUNT_W{1'b0}}) || (used == CAPACITY))));
endmodule

module refresh_ratio_divider #(
    parameter integer WIDTH = 64,
    parameter integer DEPTH = 64,
    parameter [WIDTH-1:0] START_RATIO = 64'd4
) (
    input  wire                 clk,
    input  wire                 i_ce,
    input  wire                 i_valid,
    output wire                 i_ready,
    input  wire                 i_program,
    input  wire [WIDTH-1:0]     i_slot,
    input  wire [WIDTH-1:0]     i_ratio,
    input  wire                 i_refresh,
    output wire                 o_period_boundary,
    output reg  [WIDTH-1:0]     phase_count,
    output reg  [WIDTH-1:0]     active_ratio
);
    localparam [WIDTH-1:0] ZERO = {WIDTH{1'b0}};
    localparam [WIDTH-1:0] ONE = {{(WIDTH-1){1'b0}}, 1'b1};
    localparam [WIDTH:0] SUM_ONE = {{WIDTH{1'b0}}, 1'b1};
    localparam [WIDTH-1:0] DEPTH_COUNT = WIDTH'(DEPTH);
    localparam [WIDTH-1:0] INITIAL_RATIO =
        (START_RATIO == ZERO) ? ONE : START_RATIO;

    reg [WIDTH-1:0] shadow_ratio;
    reg [WIDTH-1:0] remaining_count;
    reg [WIDTH-1:0] scan_index;

    // Addressed pending-profile table, with one pending update per slot.
    reg [WIDTH-1:0] ratio_mem [0:DEPTH-1];
    reg [DEPTH-1:0] pending_valid;
    reg before_first_refresh;
    reg pv;

    wire slot_free = (i_slot < DEPTH_COUNT)
                   ? !pending_valid[i_slot] : 1'b0;
    assign i_ready = i_ce && (!i_program || slot_free);
    wire fire = i_valid && i_ready;
    assign o_period_boundary = fire && (remaining_count == ZERO);

    initial begin
        phase_count = ZERO;
        active_ratio = INITIAL_RATIO;
        shadow_ratio = INITIAL_RATIO;
        remaining_count = INITIAL_RATIO - ONE;
        scan_index = ZERO;
        pending_valid = {DEPTH{1'b0}};
        before_first_refresh = 1'b1;
        pv = 1'b0;
    end

    genvar entry;
    generate
        for (entry = 0; entry < DEPTH; entry = entry + 1) begin : init_table
            initial ratio_mem[entry] = INITIAL_RATIO;
        end
    endgenerate

    // Each accepted command supplies one enabled divider tick.
    // A non-programming command supplies a tick without allocating a slot.
    always @(posedge clk) begin
        if (fire) begin
            pv <= 1'b1;
            if (i_refresh)
                before_first_refresh <= 1'b0;

            // A pending slot cannot be overwritten before it is consumed.
            if (i_program) begin
                ratio_mem[i_slot] <= (i_ratio == ZERO) ? ONE : i_ratio;
                pending_valid[i_slot] <= 1'b1;
            end

            if (remaining_count == ZERO) begin
                phase_count <= ZERO;
                active_ratio <= shadow_ratio;
                remaining_count <= shadow_ratio - ONE;

                // Stage a table entry for a subsequent period boundary.
                if (pending_valid[scan_index]) begin
                    shadow_ratio <= ratio_mem[scan_index];
                    pending_valid[scan_index] <= 1'b0;
                end
                if (scan_index == DEPTH_COUNT - ONE)
                    scan_index <= ZERO;
                else
                    scan_index <= scan_index + ONE;
            end else begin
                phase_count <= phase_count + ONE;
                remaining_count <= remaining_count - ONE;
            end
        end
    end

    // Before the first accepted refresh command, the phase resulting from
    // the previous cycle fits the active period budget used in that cycle.
    always @(posedge clk) begin
        if (pv && before_first_refresh)
            assert (phase_count < $past(active_ratio));
    end
endmodule

module shader_ladder_engine #(
    parameter [31:0] SCALAR_WORDS = 32'd24
) (
    input  wire clk,
    input  wire i_ce,
    input  wire i_req_valid,
    output wire o_req_ready,
    input  wire [SCALAR_WORDS*32'd32-32'd1:0] i_scalar,
    output wire o_done,
    output wire [31:0] o_point
);
    localparam [31:0] TOTAL_BITS = SCALAR_WORDS * 32'd32;
    localparam [31:0] LAST_WORD = SCALAR_WORDS - 32'd1;

    // A small coordinate-processing accelerator, specialized to the subgroup
    // generated by G=(0,1) on y^2=x^3+1 over F_5.  G has order three.
    // Every finite subgroup point has x=0, so a 32-bit point word stores its
    // y coordinate: 1 denotes G, 4 denotes -G, and 0 denotes infinity.
    // This is an intentionally small elliptic-curve specialization, not a
    // cryptographic-strength curve.
    function automatic [31:0] ec_add;
        input [31:0] a;
        input [31:0] b;
        begin
            if (a == 32'd0)
                ec_add = b;
            else if (b == 32'd0)
                ec_add = a;
            else if (a != b)
                ec_add = 32'd0;
            else if (a == 32'd1)
                ec_add = 32'd4;
            else
                ec_add = 32'd1;
        end
    endfunction

    reg busy;
    reg done;
    reg pv;
    reg [31:0] word_index;
    reg [31:0] bit_index;
    reg [31:0] deadline;
    reg [31:0] pending_words;
    reg [31:0] scalar_reg;
    reg [31:0] point_lo;
    reg [31:0] point_hi;
    reg [31:0] result;
    reg [31:0] scalar_words [0:SCALAR_WORDS-32'd1];
    reg [SCALAR_WORDS-32'd1:0] word_valid;
    wire [SCALAR_WORDS-32'd1:0] limb_select;

    wire accept = i_req_valid && o_req_ready;
    assign o_req_ready = i_ce && !busy;
    assign o_done = done;
    assign o_point = result;

    // Uniform Montgomery-ladder add-and-double datapath.  Both candidate
    // doubles and the sum are formed independently of the scalar bit.
    wire [31:0] point_sum = ec_add(point_lo, point_hi);
    wire [31:0] double_lo = ec_add(point_lo, point_lo);
    wire [31:0] double_hi = ec_add(point_hi, point_hi);
    wire [31:0] next_lo = scalar_reg[31] ? point_sum : double_lo;
    wire [31:0] next_hi = scalar_reg[31] ? double_hi : point_sum;

    initial begin
        busy = 1'b0;
        done = 1'b0;
        pv = 1'b0;
        word_index = 32'd0;
        bit_index = 32'd0;
        deadline = 32'd0;
        pending_words = 32'd0;
        scalar_reg = 32'd0;
        point_lo = 32'd0;
        point_hi = 32'd1;
        result = 32'd0;
        word_valid = {SCALAR_WORDS{1'b0}};
    end

    // A request atomically supplies all scalar limbs.  The receiver applies
    // back-pressure until that scalar has completed; no live limb is replaced.
    // Higher-numbered limbs are older in the MSB-first traversal.
    genvar g;
    generate
        for (g = 32'd0; g < SCALAR_WORDS; g = g + 32'd1) begin : limbs
            localparam [31:0] WORD_NO = g;
            assign limb_select[g] = busy && (word_index == WORD_NO);
            initial scalar_words[g] = 32'd0;
            always @(posedge clk) begin
                if (i_ce) begin
                    if (accept)
                        scalar_words[g] <= i_scalar[g*32'd32 +: 32'd32];
                    else if (limb_select[g])
                        scalar_words[g] <= scalar_words[g] << 32'd1;
                end
            end
        end
    endgenerate

    // Clock enable freezes the watchdog as well as the computation.  Thus the
    // response bound is TOTAL_BITS enabled cycles after request acceptance.
    // Even the past-valid state freezes, making i_ce=0 a complete idle mode.
    always @(posedge clk) begin
        if (i_ce)
            pv <= 1'b1;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (accept) begin
                busy <= 1'b1;
                done <= 1'b0;
                word_index <= LAST_WORD;
                bit_index <= 32'd31;
                deadline <= TOTAL_BITS;
                pending_words <= SCALAR_WORDS;
                scalar_reg <= i_scalar[LAST_WORD*32'd32 +: 32'd32];
                point_lo <= 32'd0;
                point_hi <= 32'd1;
                word_valid <= {SCALAR_WORDS{1'b1}};
            end else if (busy) begin
                deadline <= deadline - 32'd1;
                scalar_reg <= scalar_reg << 32'd1;
                point_lo <= next_lo;
                point_hi <= next_hi;
                if (bit_index != 32'd0) begin
                    bit_index <= bit_index - 32'd1;
                end else begin
                    pending_words <= pending_words - 32'd1;
                    word_valid[word_index] <= 1'b0;
                    if (word_index != 32'd0) begin
                        word_index <= word_index - 32'd1;
                        bit_index <= 32'd31;
                        scalar_reg <= scalar_words[word_index - 32'd1];
                    end else begin
                        busy <= 1'b0;
                        done <= 1'b1;
                        result <= next_lo;
                    end
                end
            end
        end
    end

    // Globally scoped bounded response, expressed about the previous tick:
    // if the outstanding request used its last budget cycle, it must now
    // be complete.  Result and done remain available until the next request.
    always @(posedge clk) begin
        if (pv && $past(i_ce && busy))
            assert (!busy || ($past(deadline) > 32'd1));
    end
endmodule

module cartridge_lookup_cam #(
    parameter ENTRIES = 128,
    parameter WORD_W = 64
) (
    input  wire                  clk,
    input  wire                  i_ce,
    input  wire                  i_req_valid,
    output wire                  o_req_ready,
    input  wire [WORD_W-1:0]     i_key,
    output reg                   o_done,
    output wire [63:0]           o_address,
    output wire                  o_hit,
    output wire                  o_multiple,
    output reg  [WORD_W-1:0]     o_data
);
    localparam INDEX_W = (ENTRIES > 32'd1) ? $clog2(ENTRIES) : 32'd1;
    localparam [63:0] ENTRY_LIMIT = 64'(ENTRIES);
    localparam [ENTRIES-1:0] MATCH_ONE = {{(ENTRIES-1){1'b0}}, 1'b1};

    // Paired cartridge-region tags exercise the multiple-hit encoder.
    reg [WORD_W-1:0] tags [0:ENTRIES-1];
    reg [ENTRIES-1:0] tag_valid;
    reg [WORD_W-1:0] active_key;
    reg [ENTRIES-1:0] latched_matches;
    reg [63:0] winner_addr;
    reg hit_any;
    reg hit_multi;
    reg busy;
    reg [63:0] countdown;
    reg pv;

    integer init_index;
    initial begin
        tag_valid = {ENTRIES{1'b1}};
        for (init_index = 32'd0; init_index < ENTRIES;
             init_index = init_index + 32'd1)
            tags[init_index] = 64'(init_index >> 32'd1);
        active_key = 64'd0;
        latched_matches = {ENTRIES{1'b0}};
        winner_addr = 64'd0;
        hit_any = 1'b0;
        hit_multi = 1'b0;
        busy = 1'b0;
        countdown = 64'd0;
        pv = 1'b0;
        o_done = 1'b0;
        o_data = 64'd0;
    end

    reg [ENTRIES-1:0] cam_matches;
    reg [63:0] encoded_addr;
    reg encoded_any;
    reg encoded_multi;
    integer enc_index;
    always @(*) begin
        cam_matches = {ENTRIES{1'b0}};
        encoded_addr = 64'd0;
        encoded_any = 1'b0;
        encoded_multi = 1'b0;
        for (enc_index = 32'd0; enc_index < ENTRIES;
             enc_index = enc_index + 32'd1) begin
            cam_matches[enc_index] = tag_valid[enc_index] &&
                                     (tags[enc_index] == i_key);
            if (cam_matches[enc_index]) begin
                if (!encoded_any)
                    encoded_addr = 64'(enc_index);
                else
                    encoded_multi = 1'b1;
                encoded_any = 1'b1;
            end
        end
    end

    assign o_req_ready = i_ce && !busy;
    assign o_address = winner_addr;
    assign o_hit = hit_any;
    assign o_multiple = hit_multi;

    // The encoded address is confirmed by reading its CAM entry.
    wire selected_ok = (winner_addr < ENTRY_LIMIT) &&
                       tag_valid[winner_addr[INDEX_W-1:0]] &&
                       (tags[winner_addr[INDEX_W-1:0]] == active_key);
    wire confirmation_ok = !hit_any || selected_ok;
    wire timer_expired = (countdown == 64'd0);

    // The deadline is one enabled work cycle after acceptance.
    // Disabling i_ce freezes every state element, including the timer.
    always @(posedge clk) begin
        if (i_ce) begin
            pv <= 1'b1;
            if (i_req_valid && o_req_ready) begin
                active_key <= i_key;
                latched_matches <= cam_matches;
                winner_addr <= encoded_addr;
                hit_any <= encoded_any;
                hit_multi <= encoded_multi;
                busy <= 1'b1;
                countdown <= 64'd1;
                o_done <= 1'b0;
            end else if (busy) begin
                if (countdown != 64'd0)
                    countdown <= countdown - 64'd1;
                if (confirmation_ok) begin
                    busy <= 1'b0;
                    o_done <= 1'b1;
                    countdown <= 64'd0;
                    if (hit_any)
                        o_data <= tags[winner_addr[INDEX_W-1:0]];
                    else
                        o_data <= 64'd0;
                end
            end
        end
    end

    // Completion status and response data persist until another request.
    // A rising expiration indication must never find a request outstanding.
    always @(posedge clk)
        if (pv && $rose(timer_expired))
            assert (!busy);
endmodule

module metric_exp2_pipe #(
    parameter integer PIPE_DEPTH = 32'd32,
    parameter integer LUT_ENTRIES = 32'd32
) (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        i_valid,
    input  wire [63:0] i_x,
    output wire        o_ready,
    output wire        o_valid,
    output wire [63:0] o_exp2,
    input  wire        i_out_ready,
    output wire [159:0] o_debug_stats
);
    // PIPE_DEPTH >= 3. LUT_ENTRIES is a power of two from 2 through 32.
    // Binary64 input and output; a table plus linear residual polynomial
    // approximates exp2. Inputs outside [0,32) are clamped before evaluation.
    localparam integer LUT_BITS = $clog2(LUT_ENTRIES);
    localparam [63:0] PIPE_CAPACITY = PIPE_DEPTH;
    localparam [63:0] LUT_SIZE = LUT_ENTRIES;
    localparam [63:0] Q30_ONE = 64'h0000000040000000;
    localparam [63:0] LN2_Q30 = 64'd744261118;
    localparam [63:0] RESIDUAL_MASK =
        (64'd1 << (32'd30 - LUT_BITS)) - 64'd1;

    reg [63:0] coeff_rom [0:LUT_ENTRIES-1];
    reg [LUT_ENTRIES-1:0] coeff_valid;
    reg [63:0] data_pipe [0:PIPE_DEPTH-1];
    reg [PIPE_DEPTH-1:0] pipe_valid;
    reg [63:0] integer_s0, integer_s1, residual_s0;
    reg [63:0] outstanding;

    // Q1.31 samples of 2^(j/32). Smaller supported tables subsample this ROM.
    function [63:0] rom_word;
        input [63:0] slot;
        reg [63:0] sample;
        begin
            sample = (slot * 64'd32) / LUT_SIZE;
            case (sample)
                64'd0:  rom_word = 64'h0000000080000000;
                64'd1:  rom_word = 64'h0000000082cd8699;
                64'd2:  rom_word = 64'h0000000085aac368;
                64'd3:  rom_word = 64'h0000000088980e81;
                64'd4:  rom_word = 64'h000000008b95c1e4;
                64'd5:  rom_word = 64'h000000008ea4398b;
                64'd6:  rom_word = 64'h0000000091c3d373;
                64'd7:  rom_word = 64'h0000000094f4efa9;
                64'd8:  rom_word = 64'h000000009837f052;
                64'd9:  rom_word = 64'h000000009b8d39ba;
                64'd10: rom_word = 64'h000000009ef53261;
                64'd11: rom_word = 64'h00000000a2704303;
                64'd12: rom_word = 64'h00000000a5fed6aa;
                64'd13: rom_word = 64'h00000000a9a15ab5;
                64'd14: rom_word = 64'h00000000ad583eea;
                64'd15: rom_word = 64'h00000000b123f582;
                64'd16: rom_word = 64'h00000000b504f334;
                64'd17: rom_word = 64'h00000000b8fbaf47;
                64'd18: rom_word = 64'h00000000bd08a39f;
                64'd19: rom_word = 64'h00000000c12c4cca;
                64'd20: rom_word = 64'h00000000c5672a11;
                64'd21: rom_word = 64'h00000000c9b9bd86;
                64'd22: rom_word = 64'h00000000ce248c15;
                64'd23: rom_word = 64'h00000000d2a81d91;
                64'd24: rom_word = 64'h00000000d744fcca;
                64'd25: rom_word = 64'h00000000dbfbb798;
                64'd26: rom_word = 64'h00000000e0ccdeec;
                64'd27: rom_word = 64'h00000000e5b906e7;
                64'd28: rom_word = 64'h00000000eac0c6e8;
                64'd29: rom_word = 64'h00000000efe4b99c;
                64'd30: rom_word = 64'h00000000f5257d15;
                64'd31: rom_word = 64'h00000000fa83b2db;
                default: rom_word = 64'h0000000080000000;
            endcase
        end
    endfunction

    initial begin
        coeff_valid = {LUT_ENTRIES{1'b1}};
        pipe_valid = {PIPE_DEPTH{1'b0}};
        integer_s0 = 64'd0;
        integer_s1 = 64'd0;
        residual_s0 = 64'd0;
        outstanding = 64'd0;
        for (integer n = 32'd0; n < LUT_ENTRIES; n = n + 32'd1)
            coeff_rom[n] = rom_word(n);
        for (integer n = 32'd0; n < PIPE_DEPTH; n = n + 32'd1)
            data_pipe[n] = 64'd0;
    end

    // Convert binary64 to unsigned Q5.59, saturating at the upper endpoint.
    wire [63:0] input_exponent = {53'd0, i_x[62:52]};
    wire [63:0] input_significand = {11'd0, 1'b1, i_x[51:0]};
    wire [63:0] x_fixed = i_x[63] ? 64'd0 :
        ((input_exponent >= 64'd1028) ? 64'hffffffffffffffff :
         ((input_exponent >= 64'd1016) ?
          (input_significand << (input_exponent - 64'd1016)) :
          (input_significand >> (64'd1016 - input_exponent))));

    wire [63:0] table_index =
        (x_fixed >> (32'd59 - LUT_BITS)) & (LUT_SIZE - 64'd1);
    wire [63:0] input_integer = x_fixed >> 64'd59;
    wire [63:0] input_residual = (x_fixed >> 64'd29) & RESIDUAL_MASK;

    // The entire pipeline freezes behind a blocked output. Thus an occupied
    // stage is never overwritten before its item advances or is consumed.
    wire advance = i_ce && (!pipe_valid[PIPE_DEPTH-1] || i_out_ready);
    wire take = i_valid && coeff_valid[table_index];
    assign o_ready = advance && coeff_valid[table_index];
    assign o_valid = i_ce && pipe_valid[PIPE_DEPTH-1];
    assign o_exp2 = data_pipe[PIPE_DEPTH-1];

    // Read-only diagnostic bank; all counters saturate rather than wrap.
    reg [15:0] dbg_cycles;
    reg [15:0] dbg_accept_count;
    reg [15:0] dbg_retire_count;
    reg [15:0] dbg_blocked_cycles;
    reg [15:0] dbg_paused_cycles;
    reg [15:0] dbg_clamp_count;
    reg [15:0] dbg_special_count;
    reg [15:0] dbg_subnormal_count;
    reg [15:0] dbg_stall_run;
    reg [15:0] dbg_stall_peak;
    wire dbg_accept = i_valid && o_ready;
    wire dbg_retire = o_valid && i_out_ready;
    wire dbg_blocked = i_ce && pipe_valid[PIPE_DEPTH-1] && !i_out_ready;
    wire dbg_clamped = i_x[63] || (input_exponent >= 64'd1028);
    initial begin
        dbg_cycles = 16'd0;
        dbg_accept_count = 16'd0;
        dbg_retire_count = 16'd0;
        dbg_blocked_cycles = 16'd0;
        dbg_paused_cycles = 16'd0;
        dbg_clamp_count = 16'd0;
        dbg_special_count = 16'd0;
        dbg_subnormal_count = 16'd0;
        dbg_stall_run = 16'd0;
        dbg_stall_peak = 16'd0;
    end
    assign o_debug_stats = {
        dbg_cycles, dbg_accept_count,
        dbg_retire_count, dbg_blocked_cycles,
        dbg_paused_cycles, dbg_clamp_count,
        dbg_special_count, dbg_subnormal_count,
        dbg_stall_run, dbg_stall_peak
    };
    always @(posedge clk) begin
        if (dbg_cycles != 16'hffff)
            dbg_cycles <= dbg_cycles + 16'd1;
        if (dbg_accept) begin
            if (dbg_accept_count != 16'hffff)
                dbg_accept_count <= dbg_accept_count + 16'd1;
            if (dbg_clamped && dbg_clamp_count != 16'hffff)
                dbg_clamp_count <= dbg_clamp_count + 16'd1;
            if (input_exponent == 64'd2047 && dbg_special_count != 16'hffff)
                dbg_special_count <= dbg_special_count + 16'd1;
            if (input_exponent == 64'd0 && i_x[51:0] != 52'd0 &&
                dbg_subnormal_count != 16'hffff)
                dbg_subnormal_count <= dbg_subnormal_count + 16'd1;
        end
        if (dbg_retire && dbg_retire_count != 16'hffff)
            dbg_retire_count <= dbg_retire_count + 16'd1;
        if (!i_ce && dbg_paused_cycles != 16'hffff)
            dbg_paused_cycles <= dbg_paused_cycles + 16'd1;
        if (dbg_blocked) begin
            if (dbg_blocked_cycles != 16'hffff)
                dbg_blocked_cycles <= dbg_blocked_cycles + 16'd1;
            if (dbg_stall_run != 16'hffff) begin
                dbg_stall_run <= dbg_stall_run + 16'd1;
                if (dbg_stall_run >= dbg_stall_peak)
                    dbg_stall_peak <= dbg_stall_run + 16'd1;
            end
        end else begin
            dbg_stall_run <= 16'd0;
        end
    end

    // Stage 1: table_base * (1 + ln(2)*residual).
    // The table is Q1.31 and the residual polynomial is Q2.30.
    wire [63:0] linear_product = LN2_Q30 * residual_s0;
    wire [63:0] residual_polynomial =
        Q30_ONE + (linear_product >> 64'd30);
    wire [63:0] fractional_product = data_pipe[0] * residual_polynomial;
    wire [63:0] fractional_q30 = fractional_product >> 64'd31;
    wire [63:0] result_exponent = 64'd1023 + integer_s1;

    always @(posedge clk) begin
        if (advance) begin
            pipe_valid <= {pipe_valid[PIPE_DEPTH-2:0], take};
            data_pipe[0] <= coeff_rom[table_index];
            integer_s0 <= input_integer;
            residual_s0 <= input_residual;
            data_pipe[1] <= fractional_q30;
            integer_s1 <= integer_s0;
            // Stage 2: put the integer part in the binary64 exponent.
            data_pipe[2] <= {
                1'b0, result_exponent[10:0], data_pipe[1][29:0], 22'd0
            };
            for (integer s = 32'd3; s < PIPE_DEPTH; s = s + 32'd1)
                data_pipe[s] <= data_pipe[s-1];

            case ({take, pipe_valid[PIPE_DEPTH-1]})
                2'b10: outstanding <= outstanding + 64'd1;
                2'b01: outstanding <= outstanding - 64'd1;
                default: outstanding <= outstanding;
            endcase
        end
    end

    // Fixed stage positions encode order; no arbitration or age tags are used.
    reg [63:0] occupied_slots;
    always @(*) begin
        occupied_slots = 64'd0;
        for (integer p = 32'd0; p < PIPE_DEPTH; p = p + 32'd1)
            occupied_slots = occupied_slots + {63'd0, pipe_valid[p]};
    end

    assert property (outstanding <= PIPE_CAPACITY);
endmodule

module schmitt_ramp_monitor #(
    parameter integer DATA_W = 16
) (
    input wire clk,
    input wire i_ce,
    input wire i_config,
    input wire [DATA_W-1:0] i_upper_threshold,
    input wire i_begin_window,
    input wire i_end_window,
    output wire o_inverted,
output wire [DATA_W-1:0] o_ramp,
input wire i_peer_valid,
input wire i_peer_up,
input wire [DATA_W-1:0] i_peer_code,
output wire o_ready, o_peer_ready,
output wire [DATA_W-1:0] o_result,
output wire o_result_peer, o_result_valid
);
    // DATA_W must be at least two. Default thresholds are 0x4000/0xc000.
    localparam [DATA_W-1:0] ONE_CODE = {{(DATA_W-1){1'b0}}, 1'b1};
    localparam [DATA_W-1:0] LOW_CODE = {2'b01, {(DATA_W-2){1'b0}}};
    localparam [DATA_W-1:0] DEFAULT_HIGH_CODE = {2'b11, {(DATA_W-2){1'b0}}};
localparam integer CHANNELS = 2, PIPE_DEPTH = 4;

    reg [DATA_W-1:0] capacitor_code;
    reg [DATA_W-1:0] high_threshold;
    reg schmitt_n;
    reg window;

    wire [DATA_W-1:0] configured_high;
    wire [DATA_W-1:0] next_code;
wire [CHANNELS-1:0] grant;
wire [DATA_W-1:0] alu_base;
wire alu_up;
reg [DATA_W-1:0] result_pipe [0:PIPE_DEPTH-1];
reg [PIPE_DEPTH-1:0] result_peer, result_valid;
integer stage;

    assign configured_high = (i_upper_threshold > LOW_CODE)
                           ? i_upper_threshold : (LOW_CODE + ONE_CODE);
assign o_ready = i_config || !i_peer_valid || result_peer[0];
assign o_peer_ready = !i_ce || (!i_config && !result_peer[0]);
assign grant = {i_peer_valid && o_peer_ready, i_ce && o_ready};
// Forward writeback when the same accumulator uses the arithmetic path again.
assign alu_base = grant[1] ? i_peer_code : (result_peer[0] ? capacitor_code : result_pipe[0]);
assign alu_up = grant[1] ? i_peer_up : schmitt_n;
assign o_result = result_pipe[PIPE_DEPTH-1];
assign o_result_peer = result_peer[PIPE_DEPTH-1];
assign o_result_valid = result_valid[PIPE_DEPTH-1];

    // The inverter output controls charging versus discharging.
assign next_code = alu_up ? (alu_base + ONE_CODE) : (alu_base - ONE_CODE);
    assign o_inverted = schmitt_n;
    assign o_ramp = capacitor_code;

    initial begin
        capacitor_code = LOW_CODE;
        high_threshold = DEFAULT_HIGH_CODE;
        schmitt_n = 1'b1;
        window = 1'b0;
result_peer = {PIPE_DEPTH{1'b1}};
result_valid = {PIPE_DEPTH{1'b0}};
for (stage = 0; stage < PIPE_DEPTH; stage = stage + 1) result_pipe[stage] = LOW_CODE;
    end
always @(posedge clk) begin
    result_valid <= {result_valid[PIPE_DEPTH-2:0], |grant};
    result_peer[PIPE_DEPTH-1:1] <= result_peer[PIPE_DEPTH-2:0];
    for (stage = 1; stage < PIPE_DEPTH; stage = stage + 1) result_pipe[stage] <= result_pipe[stage-1];
    if (|grant) begin
        result_pipe[0] <= (grant[0] && i_config) ? LOW_CODE : next_code;
        result_peer[0] <= grant[1];
    end
end

    always @(posedge clk) begin
        if (i_ce) begin
            // The observation window stays open until explicitly ended.
            if (i_end_window)
                window <= 1'b0;
            else if (i_begin_window)
                window <= 1'b1;

            if (i_config) begin
                high_threshold <= configured_high;
                capacitor_code <= LOW_CODE;
                schmitt_n <= 1'b1;
end else if (grant[0]) begin
                capacitor_code <= next_code;

                // Schmitt-trigger inverter: retain its output in the band.
                if (next_code >= high_threshold)
                    schmitt_n <= 1'b0;
                else if (next_code <= LOW_CODE)
                    schmitt_n <= 1'b1;
            end
        end
    end

    always @(posedge clk)
        if (window)
            assert (capacitor_code <= high_threshold);
endmodule

module request_completion_fold #(
    parameter integer WORD_WIDTH = 16,
    parameter integer SLOTS = 4
) (
    input  wire clk,
    input  wire i_ce,
    input  wire reserve_valid,
    output wire reserve_ready,
    input  wire completion_valid,
    input  wire [WORD_WIDTH-1:0] completion_data,
    output wire completion_ready,
    output reg [$clog2(SLOTS+1)-1:0] used,
    output reg [$clog2(SLOTS+1)-1:0] fill,
    output reg [WORD_WIDTH-1:0] signature,
    output wire fold_valid
);
    localparam integer PTR_WIDTH = $clog2(SLOTS);
    localparam integer COUNT_WIDTH = $clog2(SLOTS+1);
    localparam integer FOLD_CYCLES = 4;
    localparam integer PHASE_WIDTH = $clog2(FOLD_CYCLES);
    reg [WORD_WIDTH-1:0] records [0:SLOTS-1];
    reg [PTR_WIDTH-1:0] rd_ptr, wr_ptr;
    reg [PHASE_WIDTH-1:0] phase;
    integer init_index;

    wire reserve = reserve_valid && reserve_ready;
    wire push = completion_valid && completion_ready;
    wire fold = (phase == FOLD_CYCLES-1) && (fill != 0);
    assign reserve_ready = used < SLOTS;
    assign completion_ready = fill < SLOTS;
    assign fold_valid = i_ce && fold;

    initial begin
        used = {COUNT_WIDTH{1'b0}};
        fill = {COUNT_WIDTH{1'b0}};
        signature = {WORD_WIDTH{1'b0}};
        rd_ptr = {PTR_WIDTH{1'b0}};
        wr_ptr = {PTR_WIDTH{1'b0}};
        phase = {PHASE_WIDTH{1'b0}};
        for (init_index = 0; init_index < SLOTS; init_index = init_index + 1)
            records[init_index] = {WORD_WIDTH{1'b0}};
    end

    always @(posedge clk) begin
        if (i_ce) begin
            phase <= (phase == FOLD_CYCLES-1)
                ? {PHASE_WIDTH{1'b0}} : phase + 1'b1;
            if (push) begin
                records[wr_ptr] <= completion_data;
                wr_ptr <= (wr_ptr == SLOTS-1)
                    ? {PTR_WIDTH{1'b0}} : wr_ptr + 1'b1;
            end
            if (fold) begin
                signature <= ((signature << 1) |
                    (signature >> (WORD_WIDTH-1))) ^ records[rd_ptr];
                rd_ptr <= (rd_ptr == SLOTS-1)
                    ? {PTR_WIDTH{1'b0}} : rd_ptr + 1'b1;
            end
            case ({reserve, fold})
                2'b10: used <= used + 1'b1;
                2'b01: used <= used - 1'b1;
                default: used <= used;
            endcase
            case ({push, fold})
                2'b10: fill <= fill + 1'b1;
                2'b01: fill <= fill - 1'b1;
                default: fill <= fill;
            endcase
        end
    end
endmodule

module ordered_request_arbiter #(
    parameter logic [15:0] DEPTH = 16'd16,
    parameter integer WORD_WIDTH = 16,
    parameter integer TRACE_DEPTH = 4
) (
    input  wire clk,
    input  wire i_ce,
    input  wire request_valid,
    input  wire [WORD_WIDTH-1:0] requester_id,
    input  wire watch_request,
    input  wire scope_open,
    input  wire scope_close,
    output wire request_ready,
    output reg grant_valid,
    output reg [WORD_WIDTH-1:0] grant_id,
    output wire [$clog2(TRACE_DEPTH+1)-1:0] trace_used,
    output wire [$clog2(TRACE_DEPTH+1)-1:0] trace_count,
    output wire [WORD_WIDTH-1:0] trace_signature,
    output wire trace_fold_valid
);
    localparam logic [15:0] BUDGET = DEPTH + DEPTH;

    typedef enum logic [1:0] {
        ROUTE = 2'b00,
        GRANT = 2'b01
    } state_t;
    state_t state;

    reg [WORD_WIDTH-1:0] order_queue [0:DEPTH-1];
    reg [15:0] head, tail, count;
    reg [15:0] watched_slot, remaining;
    reg outstanding, deadline_expired;
    reg window, past_valid;
    integer init_index;
    wire trace_reserve_ready, trace_completion_ready;

    wire accept_request = request_valid && request_ready;
    wire dequeue = (state == GRANT) && (count != 16'd0)
        && trace_completion_ready;
    wire watched_grant = dequeue && (head == watched_slot);

    wire [15:0] queue_distance = (watched_slot >= head)
        ? (watched_slot - head)
        : (watched_slot + DEPTH - head);
    wire [15:0] service_rank = queue_distance + queue_distance
        + ((state == GRANT) ? 16'd1 : 16'd2);

    assign request_ready = (count < DEPTH) && trace_reserve_ready;

    request_completion_fold #(
        .WORD_WIDTH(WORD_WIDTH), .SLOTS(TRACE_DEPTH)
    ) completion_fold (
        .clk(clk), .i_ce(i_ce),
        .reserve_valid(accept_request),
        .reserve_ready(trace_reserve_ready),
        .completion_valid(dequeue),
        .completion_data(order_queue[head]),
        .completion_ready(trace_completion_ready),
        .used(trace_used), .fill(trace_count),
        .signature(trace_signature), .fold_valid(trace_fold_valid)
    );

    initial begin
        state = ROUTE;
        head = 16'd0;
        tail = 16'd0;
        count = 16'd0;
        watched_slot = 16'd0;
        remaining = 16'd0;
        outstanding = 1'b0;
        deadline_expired = 1'b0;
        window = 1'b0;
        past_valid = 1'b0;
        grant_valid = 1'b0;
        grant_id = {WORD_WIDTH{1'b0}};
        for (init_index = 0; init_index < DEPTH; init_index = init_index + 1)
            order_queue[init_index] = {WORD_WIDTH{1'b0}};
    end

    always @(posedge clk) begin
        if (i_ce) begin
            past_valid <= 1'b1;

            if (scope_close)
                window <= 1'b0;
            else if (scope_open)
                window <= 1'b1;

            case (state)
                ROUTE: state <= GRANT;
                GRANT: state <= ROUTE;
                default: state <= ROUTE;
            endcase

            grant_valid <= dequeue;
            if (dequeue) begin
                grant_id <= order_queue[head];
                head <= (head == DEPTH - 16'd1) ? 16'd0 : head + 16'd1;
            end

            if (accept_request) begin
                order_queue[tail] <= requester_id;
                tail <= (tail == DEPTH - 16'd1) ? 16'd0 : tail + 16'd1;
            end

            case ({accept_request, dequeue})
                2'b10: count <= count + 16'd1;
                2'b01: count <= count - 16'd1;
                default: count <= count;
            endcase

            // Watch one accepted request until its FIFO-ordered grant.
            // The budget counts enabled cycles, including ROUTE cycles.
            if (outstanding) begin
                if (remaining != 16'd0)
                    remaining <= remaining - 16'd1;
                if (watched_grant) begin
                    outstanding <= 1'b0;
                    deadline_expired <= 1'b0;
                end else if (remaining <= 16'd1) begin
                    deadline_expired <= 1'b1;
                end
            end else if (accept_request && watch_request) begin
                outstanding <= 1'b1;
                watched_slot <= tail;
                remaining <= BUDGET;
                deadline_expired <= 1'b0;
            end
        end
    end

    // Within the latched scope, an outstanding request must not
    // acquire an expiration while its outstanding status stays unchanged.
    always @(posedge clk)
        if (past_valid && window && outstanding && $stable(outstanding))
            assert ($stable(deadline_expired));
endmodule

module shader_ladder_engine #(
    parameter [31:0] SCALAR_WORDS = 32'd24
) (
    input  wire clk,
    input  wire i_ce,
    input  wire i_req_valid,
    output wire o_req_ready,
    input  wire [SCALAR_WORDS*32'd32-32'd1:0] i_scalar,
    output wire o_done,
output wire [31:0] o_point,
output wire o_scan_valid,
output wire o_scan_bit,
output wire o_scan_first,
output wire o_scan_last,
output wire o_scan_pending,
output wire [31:0] o_scan_point
);
    localparam [31:0] TOTAL_BITS = SCALAR_WORDS * 32'd32;
    localparam [31:0] LAST_WORD = SCALAR_WORDS - 32'd1;

localparam TRACE_DEPTH = 4;
localparam TRACE_AW = $clog2(TRACE_DEPTH);
localparam [31:0] POINT_BITS = 32'd32;
localparam SCAN_AW = $clog2(POINT_BITS);
localparam SCAN_PERIOD = 32;
localparam DIV_AW = $clog2(SCAN_PERIOD);

    // A small coordinate-processing accelerator, specialized to the subgroup
    // generated by G=(0,1) on y^2=x^3+1 over F_5.  G has order three.
    // Every finite subgroup point has x=0, so a 32-bit point word stores its
    // y coordinate: 1 denotes G, 4 denotes -G, and 0 denotes infinity.
    // This is an intentionally small elliptic-curve specialization, not a
    // cryptographic-strength curve.
    function automatic [31:0] ec_add;
        input [31:0] a;
        input [31:0] b;
        begin
            if (a == 32'd0)
                ec_add = b;
            else if (b == 32'd0)
                ec_add = a;
            else if (a != b)
                ec_add = 32'd0;
            else if (a == 32'd1)
                ec_add = 32'd4;
            else
                ec_add = 32'd1;
        end
    endfunction

    reg busy;
    reg done;
    reg pv;
    reg [31:0] word_index;
    reg [31:0] bit_index;
    reg [31:0] deadline;
    reg [31:0] pending_words;
    reg [31:0] scalar_reg;
    reg [31:0] point_lo;
    reg [31:0] point_hi;
    reg [31:0] result;
    reg [31:0] scalar_words [0:SCALAR_WORDS-32'd1];
    reg [SCALAR_WORDS-32'd1:0] word_valid;
    wire [SCALAR_WORDS-32'd1:0] limb_select;

reg [31:0] trace_mem [0:TRACE_DEPTH-1];
reg [TRACE_AW:0] trace_rd;
reg [TRACE_AW:0] trace_wr;
reg [31:0] scan_shift;
reg [SCAN_AW-1:0] scan_phase;
reg [DIV_AW-1:0] scan_divider;
reg scan_busy;

wire trace_empty = (trace_wr == trace_rd);
wire trace_full =
    (trace_wr[TRACE_AW] != trace_rd[TRACE_AW]) &&
    (trace_wr[TRACE_AW-1:0] == trace_rd[TRACE_AW-1:0]);
wire [TRACE_AW:0] trace_used = trace_wr - trace_rd;
wire [TRACE_AW-1:0] trace_last =
    trace_wr[TRACE_AW-1:0] - 1'b1;
wire trace_push = i_ce && busy &&
    (word_index == 32'd0) && (bit_index == 32'd0);
wire trace_pop = i_ce && !scan_busy && !trace_empty;
wire scan_tick = (scan_divider == SCAN_PERIOD - 1);
wire scan_finish = i_ce && scan_busy && scan_tick &&
    (scan_phase == POINT_BITS - 32'd1);
wire [31:0] scan_restored =
    (scan_shift << scan_phase) |
    (scan_shift >> (POINT_BITS - scan_phase));

    wire accept = i_req_valid && o_req_ready;
assign o_req_ready = i_ce && !busy && !trace_full;
    assign o_done = done;
    assign o_point = result;
assign o_scan_valid = i_ce && scan_busy && scan_tick;
assign o_scan_bit = scan_shift[0];
assign o_scan_first = o_scan_valid && (scan_phase == 0);
assign o_scan_last = scan_finish;
assign o_scan_pending = busy || !trace_empty || scan_busy;
assign o_scan_point = scan_restored;

    // Uniform Montgomery-ladder add-and-double datapath.  Both candidate
    // doubles and the sum are formed independently of the scalar bit.
    wire [31:0] point_sum = ec_add(point_lo, point_hi);
    wire [31:0] double_lo = ec_add(point_lo, point_lo);
    wire [31:0] double_hi = ec_add(point_hi, point_hi);
    wire [31:0] next_lo = scalar_reg[31] ? point_sum : double_lo;
    wire [31:0] next_hi = scalar_reg[31] ? double_hi : point_sum;

    initial begin
trace_rd = {(TRACE_AW+1){1'b0}};
trace_wr = {(TRACE_AW+1){1'b0}};
scan_shift = 32'd0;
scan_phase = {SCAN_AW{1'b0}};
scan_divider = {DIV_AW{1'b0}};
scan_busy = 1'b0;
        busy = 1'b0;
        done = 1'b0;
        pv = 1'b0;
        word_index = 32'd0;
        bit_index = 32'd0;
        deadline = 32'd0;
        pending_words = 32'd0;
        scalar_reg = 32'd0;
        point_lo = 32'd0;
        point_hi = 32'd1;
        result = 32'd0;
        word_valid = {SCALAR_WORDS{1'b0}};
    end

    // A request atomically supplies all scalar limbs.  The receiver applies
    // back-pressure until that scalar has completed; no live limb is replaced.
    // Higher-numbered limbs are older in the MSB-first traversal.
    genvar g;
    generate
        for (g = 32'd0; g < SCALAR_WORDS; g = g + 32'd1) begin : limbs
            localparam [31:0] WORD_NO = g;
            assign limb_select[g] = busy && (word_index == WORD_NO);
            initial scalar_words[g] = 32'd0;
            always @(posedge clk) begin
                if (i_ce) begin
                    if (accept)
                        scalar_words[g] <= i_scalar[g*32'd32 +: 32'd32];
                    else if (limb_select[g])
                        scalar_words[g] <= scalar_words[g] << 32'd1;
                end
            end
        end
    endgenerate

integer trace_init;
initial begin
    for (trace_init = 0; trace_init < TRACE_DEPTH; trace_init = trace_init + 1)
        trace_mem[trace_init] = 32'd0;
end

// Acceptance reserves a completion slot. Only the active ladder can
// enqueue, so completion never needs to stop the bounded datapath.
always @(posedge clk) begin
    if (i_ce) begin
        if (trace_push) begin
            trace_mem[trace_wr[TRACE_AW-1:0]] <= next_lo;
            trace_wr <= trace_wr + 1'b1;
        end
        if (trace_pop)
            trace_rd <= trace_rd + 1'b1;
    end
end

// Emit complete point words LSB first at the diagnostic link's baud.
// Rotation also provides a stable parallel view of the current packet.
always @(posedge clk) begin
    if (i_ce) begin
        if (trace_pop) begin
            scan_shift <= trace_mem[trace_rd[TRACE_AW-1:0]];
            scan_phase <= {SCAN_AW{1'b0}};
            scan_divider <= {DIV_AW{1'b0}};
            scan_busy <= 1'b1;
        end else if (scan_busy) begin
            if (scan_tick) begin
                scan_divider <= {DIV_AW{1'b0}};
                scan_shift <= {scan_shift[0], scan_shift[31:1]};
                if (scan_phase == POINT_BITS - 32'd1) begin
                    scan_phase <= {SCAN_AW{1'b0}};
                    scan_busy <= 1'b0;
                end else begin
                    scan_phase <= scan_phase + 1'b1;
                end
            end else begin
                scan_divider <= scan_divider + 1'b1;
            end
        end
    end
end

    // Clock enable freezes the watchdog as well as the computation.  Thus the
    // response bound is TOTAL_BITS enabled cycles after request acceptance.
    // Even the past-valid state freezes, making i_ce=0 a complete idle mode.
    always @(posedge clk) begin
        if (i_ce)
            pv <= 1'b1;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (accept) begin
                busy <= 1'b1;
                done <= 1'b0;
                word_index <= LAST_WORD;
                bit_index <= 32'd31;
                deadline <= TOTAL_BITS;
                pending_words <= SCALAR_WORDS;
                scalar_reg <= i_scalar[LAST_WORD*32'd32 +: 32'd32];
                point_lo <= 32'd0;
                point_hi <= 32'd1;
                word_valid <= {SCALAR_WORDS{1'b1}};
            end else if (busy) begin
                deadline <= deadline - 32'd1;
                scalar_reg <= scalar_reg << 32'd1;
                point_lo <= next_lo;
                point_hi <= next_hi;
                if (bit_index != 32'd0) begin
                    bit_index <= bit_index - 32'd1;
                end else begin
                    pending_words <= pending_words - 32'd1;
                    word_valid[word_index] <= 1'b0;
                    if (word_index != 32'd0) begin
                        word_index <= word_index - 32'd1;
                        bit_index <= 32'd31;
                        scalar_reg <= scalar_words[word_index - 32'd1];
                    end else begin
                        busy <= 1'b0;
                        done <= 1'b1;
                        result <= next_lo;
                    end
                end
            end
        end
    end

    // Globally scoped bounded response, expressed about the previous tick:
    // if the outstanding request used its last budget cycle, it must now
    // be complete.  Result and done remain available until the next request.
    always @(posedge clk) begin
        if (pv && $past(i_ce && busy))
            assert (!busy || ($past(deadline) > 32'd1));
    end

// Check the terminal packet position, including the parallel packet tap.
always @(posedge clk) begin
    if (pv && scan_busy && (scan_phase == POINT_BITS - 32'd1))
        assert (((scan_shift == 32'd0) ||
                 (scan_shift == 32'd2) ||
                 (scan_shift == 32'd8)) &&
                (!done || !trace_empty || (scan_restored == result)));
end
endmodule

module metric_request_gather #(
    parameter integer QUEUE_DEPTH = 32'd4,
    parameter integer GATHER_CYCLES = 32'd4
) (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        i_valid,
    input  wire [63:0] i_x,
    output wire        o_ready,
    output wire        o_valid,
    output wire [63:0] o_x,
    input  wire        i_out_ready,
    output wire [$clog2(QUEUE_DEPTH+1)-1:0] o_count,
    output wire [$clog2(QUEUE_DEPTH)-1:0] o_read_ptr,
    output wire [$clog2(QUEUE_DEPTH)-1:0] o_write_ptr,
    output wire        o_draining,
    output wire [$clog2(GATHER_CYCLES)-1:0] o_wait,
    output reg [64*QUEUE_DEPTH-1:0] o_storage
);
    // Supported queue and gathering sizes are powers of two, 4 or 8.
    // A timeout launches isolated requests without requiring a full batch.
    localparam integer PTR_BITS = $clog2(QUEUE_DEPTH);
    localparam integer COUNT_BITS = $clog2(QUEUE_DEPTH+1);
    localparam integer WAIT_BITS = $clog2(GATHER_CYCLES);
    localparam [PTR_BITS-1:0] LAST_ENTRY = QUEUE_DEPTH - 1;
    localparam [COUNT_BITS-1:0] QUEUE_LIMIT = QUEUE_DEPTH;
    localparam [WAIT_BITS-1:0] GATHER_LAST = GATHER_CYCLES - 1;

    reg [63:0] request_mem [0:QUEUE_DEPTH-1];
    reg [PTR_BITS-1:0] read_ptr, write_ptr;
    reg [COUNT_BITS-1:0] used_count;
    reg [63:0] issue_x;
    reg issue_valid;
    reg draining;
    reg [WAIT_BITS-1:0] gather_wait;

    // The registered read port isolates queue storage from evaluator stalls.
    wire issue_advance = i_ce && (!issue_valid || i_out_ready);
    wire launch_batch = draining || (used_count == QUEUE_LIMIT) ||
        (gather_wait == GATHER_LAST);
    wire refill = issue_advance && launch_batch && (used_count != 0);
    wire push = i_valid && o_ready;
    assign o_ready = i_ce &&
        ((used_count < QUEUE_LIMIT) || refill);
    assign o_valid = issue_valid;
    assign o_x = issue_x;
    assign o_count = used_count;
    assign o_read_ptr = read_ptr;
    assign o_write_ptr = write_ptr;
    assign o_draining = draining;
    assign o_wait = gather_wait;

    always @(*) begin
        o_storage = {64*QUEUE_DEPTH{1'b0}};
        for (integer e = 32'd0; e < QUEUE_DEPTH; e = e + 32'd1)
            o_storage[64*e +: 64] = request_mem[e];
    end

    initial begin
        read_ptr = {PTR_BITS{1'b0}};
        write_ptr = {PTR_BITS{1'b0}};
        used_count = {COUNT_BITS{1'b0}};
        issue_x = 64'd0;
        issue_valid = 1'b0;
        draining = 1'b0;
        gather_wait = {WAIT_BITS{1'b0}};
        for (integer e = 32'd0; e < QUEUE_DEPTH; e = e + 32'd1)
            request_mem[e] = 64'd0;
    end

    always @(posedge clk) begin
        if (push) begin
            request_mem[write_ptr] <= i_x;
            if (write_ptr == LAST_ENTRY)
                write_ptr <= {PTR_BITS{1'b0}};
            else
                write_ptr <= write_ptr + 1'b1;
        end
        if (refill) begin
            if (read_ptr == LAST_ENTRY)
                read_ptr <= {PTR_BITS{1'b0}};
            else
                read_ptr <= read_ptr + 1'b1;
        end
        case ({push, refill})
            2'b10: used_count <= used_count + 1'b1;
            2'b01: used_count <= used_count - 1'b1;
            default: used_count <= used_count;
        endcase

        // Once launched, drain continuously until the queued batch empties.
        // Backpressure holds both the issue register and the queue read port.
        if (i_ce) begin
            if (used_count == 0) begin
                draining <= 1'b0;
                gather_wait <= {WAIT_BITS{1'b0}};
            end else if (!draining) begin
                if (launch_batch) begin
                    draining <= 1'b1;
                    gather_wait <= {WAIT_BITS{1'b0}};
                end else begin
                    gather_wait <= gather_wait + 1'b1;
                end
            end
        end

        if (issue_advance) begin
            issue_valid <= refill;
            if (refill)
                issue_x <= request_mem[read_ptr];
        end
    end
endmodule

module metric_exp2_pipe #(
    parameter integer PIPE_DEPTH = 32'd32,
    parameter integer LUT_ENTRIES = 32'd32,
    parameter integer FRONT_DEPTH = 32'd4,
    parameter integer GATHER_CYCLES = 32'd4
) (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        i_valid,
    input  wire [63:0] i_x,
    output wire        o_ready,
    output wire        o_valid,
    output wire [63:0] o_exp2,
    input  wire        i_out_ready,
    output wire [159:0] o_debug_stats,
    output wire [64*FRONT_DEPTH-1:0] o_front_storage,
    output wire [63:0] o_front_x,
    output wire [2*$clog2(FRONT_DEPTH)+$clog2(FRONT_DEPTH+1)+$clog2(GATHER_CYCLES)+1:0] o_front_status
);
    // PIPE_DEPTH >= 3. LUT_ENTRIES is a power of two from 2 through 32.
    // FRONT_DEPTH and GATHER_CYCLES are 4 or 8; PIPE_DEPTH > FRONT_DEPTH+1.
    // Reserve front-end capacity in the transaction window, keeping ingress
    // readiness independent of the evaluator's output backpressure cone.
    // Binary64 input and output; a table plus linear residual polynomial
    // approximates exp2. Inputs outside [0,32) are clamped before evaluation.
    localparam integer LUT_BITS = $clog2(LUT_ENTRIES);
    localparam [63:0] PIPE_CAPACITY = PIPE_DEPTH;
    localparam [63:0] LUT_SIZE = LUT_ENTRIES;
    localparam integer FRONT_PTR_BITS = $clog2(FRONT_DEPTH);
    localparam integer FRONT_COUNT_BITS = $clog2(FRONT_DEPTH+1);
    localparam integer FRONT_WAIT_BITS = $clog2(GATHER_CYCLES);
    localparam [63:0] FRONT_CAPACITY = FRONT_DEPTH + 1;
    localparam [63:0] PIPE_ISSUE_LIMIT = PIPE_CAPACITY - FRONT_CAPACITY;
    localparam [63:0] Q30_ONE = 64'h0000000040000000;
    localparam [63:0] LN2_Q30 = 64'd744261118;
    localparam [63:0] RESIDUAL_MASK =
        (64'd1 << (32'd30 - LUT_BITS)) - 64'd1;

    reg [63:0] coeff_rom [0:LUT_ENTRIES-1];
    reg [LUT_ENTRIES-1:0] coeff_valid;
    reg [63:0] data_pipe [0:PIPE_DEPTH-1];
    reg [PIPE_DEPTH-1:0] pipe_valid;
    reg [63:0] integer_s0, integer_s1, residual_s0;
    reg [63:0] outstanding;
    reg [63:0] occupied_slots;

    wire front_in_ready, front_valid, front_issue_ready;
    wire [63:0] front_x;
    wire [FRONT_PTR_BITS-1:0] front_read_ptr, front_write_ptr;
    wire [FRONT_COUNT_BITS-1:0] front_count;
    wire front_draining;
    wire [FRONT_WAIT_BITS-1:0] front_wait;

    metric_request_gather #(
        .QUEUE_DEPTH(FRONT_DEPTH),
        .GATHER_CYCLES(GATHER_CYCLES)
    ) request_frontend (
        .clk(clk),
        .i_ce(i_ce),
        .i_valid(i_valid),
        .i_x(i_x),
        .o_ready(front_in_ready),
        .o_valid(front_valid),
        .o_x(front_x),
        .i_out_ready(front_issue_ready),
        .o_count(front_count),
        .o_read_ptr(front_read_ptr),
        .o_write_ptr(front_write_ptr),
        .o_draining(front_draining),
        .o_wait(front_wait),
        .o_storage(o_front_storage)
    );
    assign o_front_x = front_x;
    assign o_front_status = {front_write_ptr, front_read_ptr, front_count,
        front_valid, front_draining, front_wait};

    // Q1.31 samples of 2^(j/32). Smaller supported tables subsample this ROM.
    function [63:0] rom_word;
        input [63:0] slot;
        reg [63:0] sample;
        begin
            sample = (slot * 64'd32) / LUT_SIZE;
            case (sample)
                64'd0:  rom_word = 64'h0000000080000000;
                64'd1:  rom_word = 64'h0000000082cd8699;
                64'd2:  rom_word = 64'h0000000085aac368;
                64'd3:  rom_word = 64'h0000000088980e81;
                64'd4:  rom_word = 64'h000000008b95c1e4;
                64'd5:  rom_word = 64'h000000008ea4398b;
                64'd6:  rom_word = 64'h0000000091c3d373;
                64'd7:  rom_word = 64'h0000000094f4efa9;
                64'd8:  rom_word = 64'h000000009837f052;
                64'd9:  rom_word = 64'h000000009b8d39ba;
                64'd10: rom_word = 64'h000000009ef53261;
                64'd11: rom_word = 64'h00000000a2704303;
                64'd12: rom_word = 64'h00000000a5fed6aa;
                64'd13: rom_word = 64'h00000000a9a15ab5;
                64'd14: rom_word = 64'h00000000ad583eea;
                64'd15: rom_word = 64'h00000000b123f582;
                64'd16: rom_word = 64'h00000000b504f334;
                64'd17: rom_word = 64'h00000000b8fbaf47;
                64'd18: rom_word = 64'h00000000bd08a39f;
                64'd19: rom_word = 64'h00000000c12c4cca;
                64'd20: rom_word = 64'h00000000c5672a11;
                64'd21: rom_word = 64'h00000000c9b9bd86;
                64'd22: rom_word = 64'h00000000ce248c15;
                64'd23: rom_word = 64'h00000000d2a81d91;
                64'd24: rom_word = 64'h00000000d744fcca;
                64'd25: rom_word = 64'h00000000dbfbb798;
                64'd26: rom_word = 64'h00000000e0ccdeec;
                64'd27: rom_word = 64'h00000000e5b906e7;
                64'd28: rom_word = 64'h00000000eac0c6e8;
                64'd29: rom_word = 64'h00000000efe4b99c;
                64'd30: rom_word = 64'h00000000f5257d15;
                64'd31: rom_word = 64'h00000000fa83b2db;
                default: rom_word = 64'h0000000080000000;
            endcase
        end
    endfunction

    initial begin
        coeff_valid = {LUT_ENTRIES{1'b1}};
        pipe_valid = {PIPE_DEPTH{1'b0}};
        integer_s0 = 64'd0;
        integer_s1 = 64'd0;
        residual_s0 = 64'd0;
        outstanding = 64'd0;
        for (integer n = 32'd0; n < LUT_ENTRIES; n = n + 32'd1)
            coeff_rom[n] = rom_word(n);
        for (integer n = 32'd0; n < PIPE_DEPTH; n = n + 32'd1)
            data_pipe[n] = 64'd0;
    end

    // Convert binary64 to unsigned Q5.59, saturating at the upper endpoint.
    wire [63:0] input_exponent = {53'd0, i_x[62:52]};
    wire [63:0] evaluation_exponent = {53'd0, front_x[62:52]};
    wire [63:0] input_significand = {11'd0, 1'b1, front_x[51:0]};
    wire [63:0] x_fixed = front_x[63] ? 64'd0 :
        ((evaluation_exponent >= 64'd1028) ? 64'hffffffffffffffff :
         ((evaluation_exponent >= 64'd1016) ?
          (input_significand << (evaluation_exponent - 64'd1016)) :
          (input_significand >> (64'd1016 - evaluation_exponent))));

    wire [63:0] table_index =
        (x_fixed >> (32'd59 - LUT_BITS)) & (LUT_SIZE - 64'd1);
    wire [63:0] input_integer = x_fixed >> 64'd59;
    wire [63:0] input_residual = (x_fixed >> 64'd29) & RESIDUAL_MASK;

    // The entire pipeline freezes behind a blocked output. Thus an occupied
    // stage is never overwritten before its item advances or is consumed.
    // An empty evaluator also sleeps while the front end gathers its batch.
    wire advance = i_ce && (!pipe_valid[PIPE_DEPTH-1] || i_out_ready) &&
        ((occupied_slots != 64'd0) || front_valid);
    assign front_issue_ready = advance && coeff_valid[table_index] &&
        ((occupied_slots < PIPE_ISSUE_LIMIT) || pipe_valid[PIPE_DEPTH-1]);
    wire take = front_valid && front_issue_ready;
    assign o_ready = front_in_ready;
    assign o_valid = i_ce && pipe_valid[PIPE_DEPTH-1];
    assign o_exp2 = data_pipe[PIPE_DEPTH-1];

    // Read-only diagnostic bank; all counters saturate rather than wrap.
    reg [15:0] dbg_cycles;
    reg [15:0] dbg_accept_count;
    reg [15:0] dbg_retire_count;
    reg [15:0] dbg_blocked_cycles;
    reg [15:0] dbg_paused_cycles;
    reg [15:0] dbg_clamp_count;
    reg [15:0] dbg_special_count;
    reg [15:0] dbg_subnormal_count;
    reg [15:0] dbg_stall_run;
    reg [15:0] dbg_stall_peak;
    wire dbg_accept = i_valid && o_ready;
    wire dbg_retire = o_valid && i_out_ready;
    wire dbg_blocked = i_ce && pipe_valid[PIPE_DEPTH-1] && !i_out_ready;
    wire dbg_clamped = i_x[63] || (input_exponent >= 64'd1028);
    initial begin
        dbg_cycles = 16'd0;
        dbg_accept_count = 16'd0;
        dbg_retire_count = 16'd0;
        dbg_blocked_cycles = 16'd0;
        dbg_paused_cycles = 16'd0;
        dbg_clamp_count = 16'd0;
        dbg_special_count = 16'd0;
        dbg_subnormal_count = 16'd0;
        dbg_stall_run = 16'd0;
        dbg_stall_peak = 16'd0;
    end
    assign o_debug_stats = {
        dbg_cycles, dbg_accept_count,
        dbg_retire_count, dbg_blocked_cycles,
        dbg_paused_cycles, dbg_clamp_count,
        dbg_special_count, dbg_subnormal_count,
        dbg_stall_run, dbg_stall_peak
    };
    always @(posedge clk) begin
        if (dbg_cycles != 16'hffff)
            dbg_cycles <= dbg_cycles + 16'd1;
        if (dbg_accept) begin
            if (dbg_accept_count != 16'hffff)
                dbg_accept_count <= dbg_accept_count + 16'd1;
            if (dbg_clamped && dbg_clamp_count != 16'hffff)
                dbg_clamp_count <= dbg_clamp_count + 16'd1;
            if (input_exponent == 64'd2047 && dbg_special_count != 16'hffff)
                dbg_special_count <= dbg_special_count + 16'd1;
            if (input_exponent == 64'd0 && i_x[51:0] != 52'd0 &&
                dbg_subnormal_count != 16'hffff)
                dbg_subnormal_count <= dbg_subnormal_count + 16'd1;
        end
        if (dbg_retire && dbg_retire_count != 16'hffff)
            dbg_retire_count <= dbg_retire_count + 16'd1;
        if (!i_ce && dbg_paused_cycles != 16'hffff)
            dbg_paused_cycles <= dbg_paused_cycles + 16'd1;
        if (dbg_blocked) begin
            if (dbg_blocked_cycles != 16'hffff)
                dbg_blocked_cycles <= dbg_blocked_cycles + 16'd1;
            if (dbg_stall_run != 16'hffff) begin
                dbg_stall_run <= dbg_stall_run + 16'd1;
                if (dbg_stall_run >= dbg_stall_peak)
                    dbg_stall_peak <= dbg_stall_run + 16'd1;
            end
        end else begin
            dbg_stall_run <= 16'd0;
        end
    end

    // Stage 1: table_base * (1 + ln(2)*residual).
    // The table is Q1.31 and the residual polynomial is Q2.30.
    wire [63:0] linear_product = LN2_Q30 * residual_s0;
    wire [63:0] residual_polynomial =
        Q30_ONE + (linear_product >> 64'd30);
    wire [63:0] fractional_product = data_pipe[0] * residual_polynomial;
    wire [63:0] fractional_q30 = fractional_product >> 64'd31;
    wire [63:0] result_exponent = 64'd1023 + integer_s1;

    always @(posedge clk) begin
        if (advance) begin
            pipe_valid <= {pipe_valid[PIPE_DEPTH-2:0], take};
            data_pipe[0] <= coeff_rom[table_index];
            integer_s0 <= input_integer;
            residual_s0 <= input_residual;
            data_pipe[1] <= fractional_q30;
            integer_s1 <= integer_s0;
            // Stage 2: put the integer part in the binary64 exponent.
            data_pipe[2] <= {
                1'b0, result_exponent[10:0], data_pipe[1][29:0], 22'd0
            };
            for (integer s = 32'd3; s < PIPE_DEPTH; s = s + 32'd1)
                data_pipe[s] <= data_pipe[s-1];

        end
        // Admission includes requests still waiting for burst launch.
        case ({dbg_accept, dbg_retire})
            2'b10: outstanding <= outstanding + 64'd1;
            2'b01: outstanding <= outstanding - 64'd1;
            default: outstanding <= outstanding;
        endcase
    end

    // Fixed stage positions encode order; no arbitration or age tags are used.
    always @(*) begin
        occupied_slots = 64'd0;
        for (integer p = 32'd0; p < PIPE_DEPTH; p = p + 32'd1)
            occupied_slots = occupied_slots + {63'd0, pipe_valid[p]};
    end

    assert property (outstanding <= PIPE_CAPACITY);
endmodule

module clamp_request_fifo #(
    parameter integer DATA_WIDTH = 32,
    parameter integer DEPTH = 4,
    parameter integer COUNT_WIDTH = $clog2(DEPTH + 1)
) (
    input wire clk, rst_n, i_ce,
    input wire in_valid, retire,
    input wire [DATA_WIDTH-1:0] in_data, in_lower, in_upper,
    output wire in_ready, head_valid,
    output reg [COUNT_WIDTH-1:0] count,
    output reg [DEPTH*DATA_WIDTH-1:0] data_view, lower_view, upper_view
);
    reg [DATA_WIDTH-1:0] data [0:DEPTH-1];
    reg [DATA_WIDTH-1:0] low_bound [0:DEPTH-1], high_bound [0:DEPTH-1];
    wire pop, push;
    assign head_valid = (count != 0);
    assign pop = i_ce && retire && head_valid;
    assign in_ready = i_ce && ((count < DEPTH) || pop);
    assign push = in_valid && in_ready;
    integer k, v;

    initial begin
        count = {COUNT_WIDTH{1'b0}};
        for (k = 0; k < DEPTH; k = k + 1) begin
            data[k] = {DATA_WIDTH{1'b0}};
            low_bound[k] = {DATA_WIDTH{1'b0}};
            high_bound[k] = {DATA_WIDTH{1'b0}};
        end
    end

    always @(*) begin
        for (v = 0; v < DEPTH; v = v + 1) begin
            data_view[v*DATA_WIDTH +: DATA_WIDTH] = data[v];
            lower_view[v*DATA_WIDTH +: DATA_WIDTH] = low_bound[v];
            upper_view[v*DATA_WIDTH +: DATA_WIDTH] = high_bound[v];
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count <= {COUNT_WIDTH{1'b0}};
            for (k = 0; k < DEPTH; k = k + 1) begin
                data[k] <= {DATA_WIDTH{1'b0}};
                low_bound[k] <= {DATA_WIDTH{1'b0}};
                high_bound[k] <= {DATA_WIDTH{1'b0}};
            end
        end else if (i_ce) begin
            if (push != pop)
                count <= pop ? count - 1'b1 : count + 1'b1;
            if (pop)
                for (k = 0; k < DEPTH-1; k = k + 1) begin
                    data[k] <= data[k+1];
                    low_bound[k] <= low_bound[k+1];
                    high_bound[k] <= high_bound[k+1];
                end
            if (push) begin
                data[count-pop] <= in_data;
                low_bound[count-pop] <= (in_lower <= in_upper) ? in_lower : in_upper;
                high_bound[count-pop] <= (in_lower <= in_upper) ? in_upper : in_lower;
            end
        end
    end
endmodule

module activation_clamp_deadline #(
    parameter integer DATA_WIDTH = 32,
    parameter integer MAX_CYCLES = 4,
    parameter integer QUEUE_DEPTH = 4
) (
    input wire clk,
    input wire rst_n,
    input wire i_ce,
    input wire in_valid,
    output wire in_ready,
    input wire [DATA_WIDTH-1:0] in_data,
    input wire [DATA_WIDTH-1:0] in_lower,
    input wire [DATA_WIDTH-1:0] in_upper,
    output wire out_valid,
    input wire out_ready,
    output reg [DATA_WIDTH-1:0] result,
    output reg clipped,
    output wire [$clog2(QUEUE_DEPTH + 1)-1:0] queued_requests
);
    localparam integer BUDGET = (MAX_CYCLES < 2) ? 2 : MAX_CYCLES;
    localparam integer COUNT_WIDTH = $clog2(BUDGET + 1);

    reg [DATA_WIDTH-1:0] lower_limit;
    reg [DATA_WIDTH-1:0] upper_limit;
    reg [COUNT_WIDTH-1:0] countdown;
    reg outstanding;
    reg output_pending;
    wire fifo_ready, fifo_valid, queue_retire;
    wire [QUEUE_DEPTH*DATA_WIDTH-1:0] queued_data;
    wire [QUEUE_DEPTH*DATA_WIDTH-1:0] queued_lower, queued_upper;

    wire accept;
    assign in_ready = fifo_ready;
    assign accept = i_ce && fifo_valid && !outstanding && !output_pending;
    assign queue_retire = out_valid && out_ready;
    clamp_request_fifo #(.DATA_WIDTH(DATA_WIDTH), .DEPTH(QUEUE_DEPTH)) request_queue (
        .clk(clk), .rst_n(rst_n), .i_ce(i_ce), .in_valid(in_valid), .retire(queue_retire),
        .in_data(in_data), .in_lower(in_lower), .in_upper(in_upper),
        .in_ready(fifo_ready), .head_valid(fifo_valid), .count(queued_requests),
        .data_view(queued_data), .lower_view(queued_lower), .upper_view(queued_upper)
    );

    // Suppress interface transfers while the entire engine is disabled.
    assign out_valid = i_ce && output_pending;

    initial begin
        lower_limit = {DATA_WIDTH{1'b0}};
        upper_limit = {DATA_WIDTH{1'b0}};
        result = {DATA_WIDTH{1'b0}};
        clipped = 1'b0;
        countdown = {COUNT_WIDTH{1'b0}};
        outstanding = 1'b0;
        output_pending = 1'b0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            lower_limit <= {DATA_WIDTH{1'b0}};
            upper_limit <= {DATA_WIDTH{1'b0}};
            result <= {DATA_WIDTH{1'b0}};
            clipped <= 1'b0;
            countdown <= {COUNT_WIDTH{1'b0}};
            outstanding <= 1'b0;
            output_pending <= 1'b0;
        end else if (i_ce) begin
            if (accept) begin
                lower_limit <= queued_lower[0 +: DATA_WIDTH];
                upper_limit <= queued_upper[0 +: DATA_WIDTH];
                result <= queued_data[0 +: DATA_WIDTH];
                clipped <= 1'b0;
                countdown <= BUDGET;
                outstanding <= 1'b1;
            end else if (outstanding) begin
                // Internal service never waits for downstream readiness.
                if (countdown != 0)
                    countdown <= countdown - 1'b1;

                if (result < lower_limit) begin
                    result <= lower_limit;
                    clipped <= 1'b1;
                end else if (result > upper_limit) begin
                    result <= upper_limit;
                    clipped <= 1'b1;
                end else begin
                    outstanding <= 1'b0;
                    countdown <= {COUNT_WIDTH{1'b0}};
                    output_pending <= 1'b1;
                end
            end else if (output_pending && out_ready) begin
                // Only retirement of an already-valid output needs ready.
                output_pending <= 1'b0;
            end
        end
    end

    always @(posedge clk) begin
        if (outstanding)
            assert (countdown != 0);
    end

    always @(posedge clk) begin
        if (output_pending)
            assert ((result >= queued_lower[0 +: DATA_WIDTH]) && (result <= queued_upper[0 +: DATA_WIDTH]));
    end
endmodule

module schmitt_ramp_monitor #(
    parameter integer DATA_W = 16
) (
    input wire clk,
    input wire i_ce,
    input wire i_config,
    input wire [DATA_W-1:0] i_upper_threshold,
    input wire i_begin_window,
    input wire i_end_window,
    output wire o_inverted,
    output wire [DATA_W-1:0] o_ramp,
    output reg [3:0] o_debug_status
);
    // DATA_W must be at least two. Default thresholds are 0x4000/0xc000.
    localparam [DATA_W-1:0] ONE_CODE = {{(DATA_W-1){1'b0}}, 1'b1};
    localparam [DATA_W-1:0] LOW_CODE = {2'b01, {(DATA_W-2){1'b0}}};
    localparam [DATA_W-1:0] DEFAULT_HIGH_CODE = {2'b11, {(DATA_W-2){1'b0}}};

    reg [DATA_W-1:0] capacitor_code;
    reg [DATA_W-1:0] high_threshold;
    reg schmitt_n;
    reg window;
    reg [7:0] idle_cycles;
    reg [7:0] config_count;
    reg [7:0] transition_count;
    reg previous_schmitt;

    wire [DATA_W-1:0] configured_high;
    wire [DATA_W-1:0] next_code;

    assign configured_high = (i_upper_threshold > LOW_CODE)
                           ? i_upper_threshold : (LOW_CODE + ONE_CODE);

    // The inverter output controls charging versus discharging.
    assign next_code = schmitt_n ? (capacitor_code + ONE_CODE)
                                 : (capacitor_code - ONE_CODE);
    assign o_inverted = schmitt_n;
    assign o_ramp = capacitor_code;
    initial begin
        idle_cycles = 8'd0;
        config_count = 8'd0;
        transition_count = 8'd0;
        previous_schmitt = 1'b1;
        o_debug_status = 4'b0000;
    end
    always @(posedge clk) begin
        previous_schmitt <= schmitt_n;
        if (i_ce)
            idle_cycles <= 8'd0;
        else if (idle_cycles != 8'hff)
            idle_cycles <= idle_cycles + 8'd1;
        if (i_ce && i_config && (config_count != 8'hff))
            config_count <= config_count + 8'd1;
        if ((previous_schmitt != schmitt_n) && (transition_count != 8'hff))
            transition_count <= transition_count + 8'd1;
        o_debug_status <= {window, (config_count == 8'hff),
                           (transition_count == 8'hff), (idle_cycles == 8'hff)};
    end

    initial begin
        capacitor_code = LOW_CODE;
        high_threshold = DEFAULT_HIGH_CODE;
        schmitt_n = 1'b1;
        window = 1'b0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            // The observation window stays open until explicitly ended.
            if (i_end_window)
                window <= 1'b0;
            else if (i_begin_window)
                window <= 1'b1;

            if (i_config) begin
                high_threshold <= configured_high;
                capacitor_code <= LOW_CODE;
                schmitt_n <= 1'b1;
            end else begin
                capacitor_code <= next_code;

                // Schmitt-trigger inverter: retain its output in the band.
                if (next_code >= high_threshold)
                    schmitt_n <= 1'b0;
                else if (next_code <= LOW_CODE)
                    schmitt_n <= 1'b1;
            end
        end
    end

    always @(posedge clk)
        if (window)
            assert (capacitor_code <= high_threshold);
endmodule

module schmitt_ramp_monitor #(
    parameter integer DATA_W = 16
) (
    input wire clk,
    input wire i_ce,
    input wire i_config,
    input wire [DATA_W-1:0] i_upper_threshold,
    input wire i_begin_window,
    input wire i_end_window,
    output wire o_inverted,
output wire [DATA_W-1:0] o_ramp,
input wire i_peer_valid,
input wire i_peer_up,
input wire [DATA_W-1:0] i_peer_code,
output wire o_ready, o_peer_ready,
output wire [DATA_W-1:0] o_result,
output wire o_result_peer, o_result_valid,
output wire o_window_ready,
output wire o_report_bit, o_report_valid, o_report_last
);
    // DATA_W must be at least two. Default thresholds are 0x4000/0xc000.
    localparam [DATA_W-1:0] ONE_CODE = {{(DATA_W-1){1'b0}}, 1'b1};
    localparam [DATA_W-1:0] LOW_CODE = {2'b01, {(DATA_W-2){1'b0}}};
    localparam [DATA_W-1:0] DEFAULT_HIGH_CODE = {2'b11, {(DATA_W-2){1'b0}}};
localparam integer CHANNELS = 2, PIPE_DEPTH = 4;
localparam integer REPORT_DEPTH = 4;
localparam integer REPORT_ADDR_W = $clog2(REPORT_DEPTH);
localparam integer REPORT_BIT_W = $clog2(DATA_W+1);

    reg [DATA_W-1:0] capacitor_code;
    reg [DATA_W-1:0] high_threshold;
    reg schmitt_n;
    reg window;

    wire [DATA_W-1:0] configured_high;
    wire [DATA_W-1:0] next_code;
wire [CHANNELS-1:0] grant;
wire [DATA_W-1:0] alu_base;
wire alu_up;
reg [DATA_W-1:0] result_pipe [0:PIPE_DEPTH-1];
reg [PIPE_DEPTH-1:0] result_peer, result_valid;
integer stage;
reg [DATA_W-1:0] window_min, window_max;
reg [DATA_W-1:0] report_min_mem [0:REPORT_DEPTH-1];
reg [DATA_W-1:0] report_max_mem [0:REPORT_DEPTH-1];
reg [REPORT_ADDR_W:0] report_rd, report_wr;
reg [REPORT_BIT_W-1:0] report_bit;
reg report_high;
reg [REPORT_DEPTH-1:0] report_used;
wire [REPORT_ADDR_W:0] report_count;
wire report_empty, report_full, report_push, report_pop, report_bit_last;
wire [DATA_W-1:0] report_min, report_max, report_head_min, report_head_max, report_word;
integer report_slot, report_scan;

    assign configured_high = (i_upper_threshold > LOW_CODE)
                           ? i_upper_threshold : (LOW_CODE + ONE_CODE);
assign o_ready = i_config ? report_empty : (!i_peer_valid || result_peer[0]);
assign o_peer_ready = !i_ce || (i_config ? !report_empty : !result_peer[0]);
assign grant = {i_peer_valid && o_peer_ready, i_ce && o_ready};
// Forward writeback when the same accumulator uses the arithmetic path again.
assign alu_base = grant[1] ? i_peer_code : (result_peer[0] ? capacitor_code : result_pipe[0]);
assign alu_up = grant[1] ? i_peer_up : schmitt_n;
assign o_result = result_pipe[PIPE_DEPTH-1];
assign o_result_peer = result_peer[PIPE_DEPTH-1];
assign o_result_valid = result_valid[PIPE_DEPTH-1];
assign report_count = report_wr - report_rd;
assign report_empty = (report_wr == report_rd);
assign report_full = (report_wr[REPORT_ADDR_W] != report_rd[REPORT_ADDR_W])
                   && (report_wr[REPORT_ADDR_W-1:0] == report_rd[REPORT_ADDR_W-1:0]);
assign o_window_ready = !report_full && !(i_config && report_empty);
assign report_push = i_ce && i_end_window && o_window_ready;
assign report_bit_last = (report_bit == DATA_W);
assign o_report_valid = i_ce && !report_empty;
assign o_report_last = report_high && report_bit_last;
assign report_pop = o_report_valid && o_report_last;
assign report_head_min = report_min_mem[report_rd[REPORT_ADDR_W-1:0]];
assign report_head_max = report_max_mem[report_rd[REPORT_ADDR_W-1:0]];
assign report_word = report_high ? report_head_max : report_head_min;
assign o_report_bit = (report_bit == 0) ? report_high : report_word[report_bit-1'b1];
assign report_min = (window && window_min < capacitor_code) ? window_min : capacitor_code;
assign report_max = (window && window_max > capacitor_code) ? window_max : capacitor_code;
always @(*) begin
    for (report_scan = 0; report_scan < REPORT_DEPTH; report_scan = report_scan + 1)
        report_used[report_scan] = (((report_scan - report_rd[REPORT_ADDR_W-1:0]) & (REPORT_DEPTH-1)) < report_count);
end

    // The inverter output controls charging versus discharging.
assign next_code = alu_up ? (alu_base + ONE_CODE) : (alu_base - ONE_CODE);
    assign o_inverted = schmitt_n;
    assign o_ramp = capacitor_code;
always @(posedge clk) begin
    if (i_ce) begin
        if (i_config && o_ready) begin
            window_min <= LOW_CODE;
            window_max <= LOW_CODE;
        end else if (window || i_begin_window) begin
            window_min <= report_min;
            window_max <= report_max;
        end
    end
end
always @(posedge clk) begin
    if (report_push) begin
        report_min_mem[report_wr[REPORT_ADDR_W-1:0]] <= report_min;
        report_max_mem[report_wr[REPORT_ADDR_W-1:0]] <= report_max;
        report_wr <= report_wr + 1'b1;
    end
    if (report_pop)
        report_rd <= report_rd + 1'b1;
    if (o_report_valid) begin
        if (report_bit_last) begin
            report_bit <= 0;
            report_high <= !report_high;
        end else
            report_bit <= report_bit + 1'b1;
    end
end

    initial begin
        capacitor_code = LOW_CODE;
        high_threshold = DEFAULT_HIGH_CODE;
        schmitt_n = 1'b1;
        window = 1'b0;
result_peer = {PIPE_DEPTH{1'b1}};
result_valid = {PIPE_DEPTH{1'b0}};
for (stage = 0; stage < PIPE_DEPTH; stage = stage + 1) result_pipe[stage] = LOW_CODE;
        window_min = LOW_CODE;
        window_max = LOW_CODE;
        report_rd = 0;
        report_wr = 0;
        report_bit = 0;
        report_high = 1'b0;
        for (report_slot = 0; report_slot < REPORT_DEPTH; report_slot = report_slot + 1) begin
            report_min_mem[report_slot] = LOW_CODE;
            report_max_mem[report_slot] = LOW_CODE;
        end
    end
always @(posedge clk) begin
    result_valid <= {result_valid[PIPE_DEPTH-2:0], |grant};
    result_peer[PIPE_DEPTH-1:1] <= result_peer[PIPE_DEPTH-2:0];
    for (stage = 1; stage < PIPE_DEPTH; stage = stage + 1) result_pipe[stage] <= result_pipe[stage-1];
    if (|grant) begin
        result_pipe[0] <= (grant[0] && i_config) ? LOW_CODE : next_code;
        result_peer[0] <= grant[1];
    end
end

    always @(posedge clk) begin
        if (i_ce) begin
            // The observation window stays open until explicitly ended.
            if (i_end_window && o_window_ready)
                window <= 1'b0;
            else if (i_begin_window)
                window <= 1'b1;

            if (i_config && o_ready) begin
                high_threshold <= configured_high;
                capacitor_code <= LOW_CODE;
                schmitt_n <= 1'b1;
end else if (grant[0]) begin
                capacitor_code <= next_code;

                // Schmitt-trigger inverter: retain its output in the band.
                if (next_code >= high_threshold)
                    schmitt_n <= 1'b0;
                else if (next_code <= LOW_CODE)
                    schmitt_n <= 1'b1;
            end
        end
    end
    always @(posedge clk)
        if (o_report_valid)
            assert ((report_head_min <= report_head_max) &&
                    (report_head_max <= high_threshold) && (report_bit <= DATA_W));

    always @(posedge clk)
        if (window)
            assert (capacitor_code <= high_threshold);
endmodule

module shader_point_batch #(
    parameter BATCH_SIZE = 4
) (
    input wire clk,
    input wire i_ce,
    input wire i_valid,
    output wire o_ready,
    input wire [31:0] i_point,
    output wire o_valid,
    output wire [31:0] o_point,
    output wire o_pending,
    output wire [$clog2(BATCH_SIZE+1)-1:0] o_count,
    output wire [1:0] o_phase,
    output wire [$clog2(BATCH_SIZE-1)-1:0] o_cursor,
    output wire [(2*BATCH_SIZE-1)*32-1:0] o_tree
);
    localparam TREE_NODES = 2 * BATCH_SIZE - 1;
    localparam LEAF_BASE = BATCH_SIZE - 1;
    localparam COUNT_W = $clog2(BATCH_SIZE + 1);
    localparam CURSOR_W = $clog2(BATCH_SIZE - 1);
    localparam ADDR_W = $clog2(TREE_NODES);
    localparam [1:0] COLLECT = 2'd0;
    localparam [1:0] REDUCE = 2'd1;
    localparam [1:0] REPORT = 2'd2;

    reg [31:0] tree [0:TREE_NODES-1];
    reg [COUNT_W-1:0] count;
    reg [CURSOR_W-1:0] cursor;
    reg [1:0] phase;
    reg write_enable;
    reg [ADDR_W-1:0] write_address;
    reg [31:0] write_data;
    wire take = i_valid && o_ready;
    wire [ADDR_W-1:0] left_child = {cursor, 1'b0} + 1'b1;
    wire [ADDR_W-1:0] right_child = left_child + 1'b1;

    function automatic [31:0] ec_add;
        input [31:0] a;
        input [31:0] b;
        begin
            if (a == 32'd0)
                ec_add = b;
            else if (b == 32'd0)
                ec_add = a;
            else if (a != b)
                ec_add = 32'd0;
            else if (a == 32'd1)
                ec_add = 32'd4;
            else
                ec_add = 32'd1;
        end
    endfunction

    assign o_ready = (phase == COLLECT) && (count < BATCH_SIZE);
    assign o_valid = i_ce && (phase == REPORT);
    assign o_point = tree[0];
    assign o_pending = (count != 0);
    assign o_count = count;
    assign o_phase = phase;
    assign o_cursor = cursor;

    genvar n;
    generate
        for (n = 0; n < TREE_NODES; n = n + 1) begin : export_nodes
            assign o_tree[n*32 +: 32] = tree[n];
        end
    endgenerate

    integer init_node;
    initial begin
        count = {COUNT_W{1'b0}};
        cursor = {CURSOR_W{1'b0}};
        phase = COLLECT;
    end
    initial begin
        for (init_node = 0; init_node < TREE_NODES; init_node = init_node + 1)
            tree[init_node] = 32'd0;
    end

    // Leaves retain individual contributions; internal nodes hold subtotals.
    always @(*) begin
        write_enable = 1'b0;
        write_address = {ADDR_W{1'b0}};
        write_data = 32'd0;
        if (phase == COLLECT) begin
            if (take) begin
                write_enable = 1'b1;
                write_address = LEAF_BASE + count;
                write_data = i_point;
            end
        end else if (phase == REDUCE) begin
            write_enable = 1'b1;
            write_address = cursor;
            write_data = ec_add(tree[left_child], tree[right_child]);
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (write_enable)
                tree[write_address] <= write_data;
        end
    end

    // Reverse heap order makes both children available before their parent.
    always @(posedge clk) begin
        if (i_ce) begin
            case (phase)
                COLLECT: begin
                    if (take) begin
                        count <= count + 1'b1;
                        if (count == BATCH_SIZE - 1) begin
                            cursor <= BATCH_SIZE - 2;
                            phase <= REDUCE;
                        end
                    end
                end
                REDUCE: begin
                    if (cursor == 0) begin
                        phase <= REPORT;
                    end else begin
                        cursor <= cursor - 1'b1;
                    end
                end
                REPORT: begin
                    count <= {COUNT_W{1'b0}};
                    phase <= COLLECT;
                end
            endcase
        end
    end
endmodule

module shader_ladder_engine #(
    parameter [31:0] SCALAR_WORDS = 32'd24,
    parameter BATCH_SIZE = 4
) (
    input  wire clk,
    input  wire i_ce,
    input  wire i_req_valid,
    output wire o_req_ready,
    input  wire [SCALAR_WORDS*32'd32-32'd1:0] i_scalar,
    output wire o_done,
output wire [31:0] o_point,
output wire o_scan_valid,
output wire o_scan_bit,
output wire o_scan_first,
output wire o_scan_last,
output wire o_scan_pending,
output wire [31:0] o_scan_point,
output wire o_batch_valid,
output wire [31:0] o_batch_point,
output wire o_batch_pending,
output wire [$clog2(BATCH_SIZE+1)-1:0] o_batch_count
);
    localparam [31:0] TOTAL_BITS = SCALAR_WORDS * 32'd32;
    localparam [31:0] LAST_WORD = SCALAR_WORDS - 32'd1;

localparam TRACE_DEPTH = 4;
localparam TRACE_AW = $clog2(TRACE_DEPTH);
localparam [31:0] POINT_BITS = 32'd32;
localparam SCAN_AW = $clog2(POINT_BITS);
localparam SCAN_PERIOD = 32;
localparam DIV_AW = $clog2(SCAN_PERIOD);
localparam BATCH_NODES = 2 * BATCH_SIZE - 1;
localparam BATCH_CW = $clog2(BATCH_SIZE + 1);
localparam BATCH_IW = $clog2(BATCH_SIZE - 1);
localparam [1:0] BATCH_COLLECT = 2'd0;
localparam [1:0] BATCH_REDUCE = 2'd1;
localparam [1:0] BATCH_REPORT = 2'd2;

    // A small coordinate-processing accelerator, specialized to the subgroup
    // generated by G=(0,1) on y^2=x^3+1 over F_5.  G has order three.
    // Every finite subgroup point has x=0, so a 32-bit point word stores its
    // y coordinate: 1 denotes G, 4 denotes -G, and 0 denotes infinity.
    // This is an intentionally small elliptic-curve specialization, not a
    // cryptographic-strength curve.
    function automatic [31:0] ec_add;
        input [31:0] a;
        input [31:0] b;
        begin
            if (a == 32'd0)
                ec_add = b;
            else if (b == 32'd0)
                ec_add = a;
            else if (a != b)
                ec_add = 32'd0;
            else if (a == 32'd1)
                ec_add = 32'd4;
            else
                ec_add = 32'd1;
        end
    endfunction

    reg busy;
    reg done;
    reg pv;
    reg [31:0] word_index;
    reg [31:0] bit_index;
    reg [31:0] deadline;
    reg [31:0] pending_words;
    reg [31:0] scalar_reg;
    reg [31:0] point_lo;
    reg [31:0] point_hi;
    reg [31:0] result;
    reg [31:0] scalar_words [0:SCALAR_WORDS-32'd1];
    reg [SCALAR_WORDS-32'd1:0] word_valid;
    wire [SCALAR_WORDS-32'd1:0] limb_select;

reg [31:0] trace_mem [0:TRACE_DEPTH-1];
reg [TRACE_AW:0] trace_rd;
reg [TRACE_AW:0] trace_wr;
reg [31:0] scan_shift;
reg [SCAN_AW-1:0] scan_phase;
reg [DIV_AW-1:0] scan_divider;
reg scan_busy;

wire batch_ready;
wire [BATCH_CW-1:0] batch_count;
wire [BATCH_IW-1:0] batch_cursor;
wire [1:0] batch_phase;
wire [BATCH_NODES*32-1:0] batch_tree;
wire [31:0] batch_nodes [0:BATCH_NODES-1];
wire [BATCH_SIZE-2:0] batch_links_ok;
wire batch_offer = busy &&
    (word_index == 32'd0) && (bit_index == 32'd0);
wire [BATCH_CW-1:0] batch_delivered =
    o_batch_valid ? BATCH_SIZE : {BATCH_CW{1'b0}};

wire trace_empty = (trace_wr == trace_rd);
wire trace_full =
    (trace_wr[TRACE_AW] != trace_rd[TRACE_AW]) &&
    (trace_wr[TRACE_AW-1:0] == trace_rd[TRACE_AW-1:0]);
wire [TRACE_AW:0] trace_used = trace_wr - trace_rd;
wire [TRACE_AW-1:0] trace_last =
    trace_wr[TRACE_AW-1:0] - 1'b1;
wire trace_push = i_ce && busy &&
    (word_index == 32'd0) && (bit_index == 32'd0);
wire trace_pop = i_ce && !scan_busy && !trace_empty;
wire scan_tick = (scan_divider == SCAN_PERIOD - 1);
wire scan_finish = i_ce && scan_busy && scan_tick &&
    (scan_phase == POINT_BITS - 32'd1);
wire [31:0] scan_restored =
    (scan_shift << scan_phase) |
    (scan_shift >> (POINT_BITS - scan_phase));

    wire accept = i_req_valid && o_req_ready;
assign o_req_ready = i_ce && !busy && !trace_full && batch_ready;
    assign o_done = done;
    assign o_point = result;
assign o_scan_valid = i_ce && scan_busy && scan_tick;
assign o_scan_bit = scan_shift[0];
assign o_scan_first = o_scan_valid && (scan_phase == 0);
assign o_scan_last = scan_finish;
assign o_scan_pending = busy || !trace_empty || scan_busy;
assign o_scan_point = scan_restored;

    // Uniform Montgomery-ladder add-and-double datapath.  Both candidate
    // doubles and the sum are formed independently of the scalar bit.
    wire [31:0] point_sum = ec_add(point_lo, point_hi);
    wire [31:0] double_lo = ec_add(point_lo, point_lo);
    wire [31:0] double_hi = ec_add(point_hi, point_hi);
    wire [31:0] next_lo = scalar_reg[31] ? point_sum : double_lo;
    wire [31:0] next_hi = scalar_reg[31] ? double_hi : point_sum;

    // Request admission reserves one leaf for the active ladder.
    shader_point_batch #(
        .BATCH_SIZE(BATCH_SIZE)
    ) point_batches (
        .clk(clk),
        .i_ce(i_ce),
        .i_valid(batch_offer),
        .o_ready(batch_ready),
        .i_point(next_lo),
        .o_valid(o_batch_valid),
        .o_point(o_batch_point),
        .o_pending(o_batch_pending),
        .o_count(batch_count),
        .o_phase(batch_phase),
        .o_cursor(batch_cursor),
        .o_tree(batch_tree)
    );
    assign o_batch_count = batch_count;

    genvar bn;
    generate
        for (bn = 0; bn < BATCH_NODES; bn = bn + 1) begin : batch_taps
            assign batch_nodes[bn] = batch_tree[bn*32 +: 32];
        end
        for (bn = 0; bn < BATCH_SIZE-1; bn = bn + 1) begin : batch_checks
            assign batch_links_ok[bn] =
                batch_nodes[bn] == ec_add(batch_nodes[2*bn+1],
                    (bn == BATCH_SIZE-2) ? result : batch_nodes[2*bn+2]);
        end
    endgenerate

    initial begin
trace_rd = {(TRACE_AW+1){1'b0}};
trace_wr = {(TRACE_AW+1){1'b0}};
scan_shift = 32'd0;
scan_phase = {SCAN_AW{1'b0}};
scan_divider = {DIV_AW{1'b0}};
scan_busy = 1'b0;
        busy = 1'b0;
        done = 1'b0;
        pv = 1'b0;
        word_index = 32'd0;
        bit_index = 32'd0;
        deadline = 32'd0;
        pending_words = 32'd0;
        scalar_reg = 32'd0;
        point_lo = 32'd0;
        point_hi = 32'd1;
        result = 32'd0;
        word_valid = {SCALAR_WORDS{1'b0}};
    end

    // A request atomically supplies all scalar limbs.  The receiver applies
    // back-pressure until that scalar has completed; no live limb is replaced.
    // Higher-numbered limbs are older in the MSB-first traversal.
    genvar g;
    generate
        for (g = 32'd0; g < SCALAR_WORDS; g = g + 32'd1) begin : limbs
            localparam [31:0] WORD_NO = g;
            assign limb_select[g] = busy && (word_index == WORD_NO);
            initial scalar_words[g] = 32'd0;
            always @(posedge clk) begin
                if (i_ce) begin
                    if (accept)
                        scalar_words[g] <= i_scalar[g*32'd32 +: 32'd32];
                    else if (limb_select[g])
                        scalar_words[g] <= scalar_words[g] << 32'd1;
                end
            end
        end
    endgenerate

integer trace_init;
initial begin
    for (trace_init = 0; trace_init < TRACE_DEPTH; trace_init = trace_init + 1)
        trace_mem[trace_init] = 32'd0;
end

// Acceptance reserves a completion slot. Only the active ladder can
// enqueue, so completion never needs to stop the bounded datapath.
always @(posedge clk) begin
    if (i_ce) begin
        if (trace_push) begin
            trace_mem[trace_wr[TRACE_AW-1:0]] <= next_lo;
            trace_wr <= trace_wr + 1'b1;
        end
        if (trace_pop)
            trace_rd <= trace_rd + 1'b1;
    end
end

// Emit complete point words LSB first at the diagnostic link's baud.
// Rotation also provides a stable parallel view of the current packet.
always @(posedge clk) begin
    if (i_ce) begin
        if (trace_pop) begin
            scan_shift <= trace_mem[trace_rd[TRACE_AW-1:0]];
            scan_phase <= {SCAN_AW{1'b0}};
            scan_divider <= {DIV_AW{1'b0}};
            scan_busy <= 1'b1;
        end else if (scan_busy) begin
            if (scan_tick) begin
                scan_divider <= {DIV_AW{1'b0}};
                scan_shift <= {scan_shift[0], scan_shift[31:1]};
                if (scan_phase == POINT_BITS - 32'd1) begin
                    scan_phase <= {SCAN_AW{1'b0}};
                    scan_busy <= 1'b0;
                end else begin
                    scan_phase <= scan_phase + 1'b1;
                end
            end else begin
                scan_divider <= scan_divider + 1'b1;
            end
        end
    end
end

    // Clock enable freezes the watchdog as well as the computation.  Thus the
    // response bound is TOTAL_BITS enabled cycles after request acceptance.
    // Even the past-valid state freezes, making i_ce=0 a complete idle mode.
    always @(posedge clk) begin
        if (i_ce)
            pv <= 1'b1;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (accept) begin
                busy <= 1'b1;
                done <= 1'b0;
                word_index <= LAST_WORD;
                bit_index <= 32'd31;
                deadline <= TOTAL_BITS;
                pending_words <= SCALAR_WORDS;
                scalar_reg <= i_scalar[LAST_WORD*32'd32 +: 32'd32];
                point_lo <= 32'd0;
                point_hi <= 32'd1;
                word_valid <= {SCALAR_WORDS{1'b1}};
            end else if (busy) begin
                deadline <= deadline - 32'd1;
                scalar_reg <= scalar_reg << 32'd1;
                point_lo <= next_lo;
                point_hi <= next_hi;
                if (bit_index != 32'd0) begin
                    bit_index <= bit_index - 32'd1;
                end else begin
                    pending_words <= pending_words - 32'd1;
                    word_valid[word_index] <= 1'b0;
                    if (word_index != 32'd0) begin
                        word_index <= word_index - 32'd1;
                        bit_index <= 32'd31;
                        scalar_reg <= scalar_words[word_index - 32'd1];
                    end else begin
                        busy <= 1'b0;
                        done <= 1'b1;
                        result <= next_lo;
                    end
                end
            end
        end
    end

    // Globally scoped bounded response, expressed about the previous tick:
    // if the outstanding request used its last budget cycle, it must now
    // be complete.  Result and done remain available until the next request.
    always @(posedge clk) begin
        if (pv && $past(i_ce && busy))
            assert (!busy || ($past(deadline) > 32'd1));
    end

// Check the terminal packet position, including the parallel packet tap.
always @(posedge clk) begin
    if (pv && scan_busy && (scan_phase == POINT_BITS - 32'd1))
        assert (((scan_shift == 32'd0) ||
                 (scan_shift == 32'd2) ||
                 (scan_shift == 32'd8)) &&
                (!done || !trace_empty || (scan_restored == result)));
end

// A batch report includes the latest completion and coherent subtotals.
always @(posedge clk) begin
    if (pv && (batch_phase == BATCH_REPORT))
        assert (((o_batch_point == 32'd0) ||
                 (o_batch_point == 32'd1) ||
                 (o_batch_point == 32'd4)) &&
                (&batch_links_ok));
end
endmodule

module ordered_request_arbiter #(
    parameter logic [15:0] DEPTH = 16'd16,
    parameter integer OWNER_ENTRIES = 4,
    parameter integer WORD_WIDTH = 16
) (
    input  wire clk,
    input  wire i_ce,
    input  wire request_valid,
    input  wire [WORD_WIDTH-1:0] requester_id,
    input  wire watch_request,
    input  wire scope_open,
    input  wire scope_close,
    output wire request_ready,
    output reg grant_valid,
    output reg [WORD_WIDTH-1:0] grant_id,
    output wire [OWNER_ENTRIES-1:0] active_requesters,
    output wire requester_conflict,
    output reg [15:0] request_wait_cycles
);
    localparam logic [15:0] BUDGET = DEPTH + DEPTH;
    localparam integer OWNER_INDEX_WIDTH =
        (OWNER_ENTRIES <= 1) ? 1 : $clog2(OWNER_ENTRIES);
    localparam integer QUEUE_SLOT_WIDTH =
        (DEPTH <= 1) ? 1 : $clog2(DEPTH);

    typedef enum logic [1:0] {
        ROUTE = 2'b00,
        GRANT = 2'b01
    } state_t;
    state_t state;

    reg [WORD_WIDTH-1:0] order_queue [0:DEPTH-1];
    reg [15:0] head, tail, count;
    reg [15:0] watched_slot, remaining;
    reg outstanding, deadline_expired;
    reg window, past_valid;
    integer init_index;
    reg [WORD_WIDTH-1:0] owner_id [0:OWNER_ENTRIES-1];
    reg [QUEUE_SLOT_WIDTH-1:0] owner_slot [0:OWNER_ENTRIES-1];
    reg [OWNER_ENTRIES-1:0] owner_busy, retire_mask;
    reg alloc_found, retire_found, retire_multiple, id_conflict;
    reg [OWNER_INDEX_WIDTH-1:0] alloc_index, retire_index;
    reg [15:0] scan_distance, scan_rank;
    reg [15:0] capacity_rank, conflict_rank;
    integer owner_init_index, owner_scan_index;

    wire accept_request = request_valid && request_ready;
    wire dequeue = (state == GRANT) && (count != 16'd0);
    wire watched_grant = dequeue && (head == watched_slot);

    wire [15:0] queue_distance = (watched_slot >= head)
        ? (watched_slot - head)
        : (watched_slot + DEPTH - head);
    wire [15:0] service_rank = queue_distance + queue_distance
        + ((state == GRANT) ? 16'd1 : 16'd2);

    assign request_ready = (count < DEPTH) && alloc_found && !id_conflict;
    assign active_requesters = owner_busy;
    assign requester_conflict = id_conflict;

    always @(*) begin
        retire_found = 1'b0;
        retire_multiple = 1'b0;
        retire_index = {OWNER_INDEX_WIDTH{1'b0}};
        retire_mask = {OWNER_ENTRIES{1'b0}};
        alloc_found = 1'b0;
        alloc_index = {OWNER_INDEX_WIDTH{1'b0}};
        id_conflict = 1'b0;
        scan_distance = 16'd0;
        scan_rank = 16'd0;
        capacity_rank = BUDGET;
        conflict_rank = 16'd0;
        for (owner_scan_index = 0; owner_scan_index < OWNER_ENTRIES;
             owner_scan_index = owner_scan_index + 1) begin
            if (owner_busy[owner_scan_index] &&
                (owner_slot[owner_scan_index] == head)) begin
                retire_multiple = retire_multiple || retire_found;
                retire_found = 1'b1;
                retire_index = owner_scan_index[OWNER_INDEX_WIDTH-1:0];
                if (dequeue)
                    retire_mask[owner_scan_index] = 1'b1;
            end
        end
        for (owner_scan_index = 0; owner_scan_index < OWNER_ENTRIES;
             owner_scan_index = owner_scan_index + 1) begin
            if (owner_busy[owner_scan_index] && !retire_mask[owner_scan_index]) begin
                scan_distance = (owner_slot[owner_scan_index] >= head)
                    ? (owner_slot[owner_scan_index] - head)
                    : (owner_slot[owner_scan_index] + DEPTH - head);
                scan_rank = scan_distance + scan_distance
                    + ((state == GRANT) ? 16'd1 : 16'd2);
                if (scan_rank < capacity_rank)
                    capacity_rank = scan_rank;
                if (owner_id[owner_scan_index] == requester_id) begin
                    id_conflict = 1'b1;
                    conflict_rank = scan_rank;
                end
            end
            if ((!owner_busy[owner_scan_index] || retire_mask[owner_scan_index])
                && !alloc_found) begin
                alloc_found = 1'b1;
                alloc_index = owner_scan_index[OWNER_INDEX_WIDTH-1:0];
            end
        end
        request_wait_cycles = id_conflict ? conflict_rank
            : ((!alloc_found || (count >= DEPTH)) ? capacity_rank : 16'd0);
    end

    initial begin
        state = ROUTE;
        head = 16'd0;
        tail = 16'd0;
        count = 16'd0;
        watched_slot = 16'd0;
        remaining = 16'd0;
        outstanding = 1'b0;
        deadline_expired = 1'b0;
        window = 1'b0;
        past_valid = 1'b0;
        grant_valid = 1'b0;
        grant_id = {WORD_WIDTH{1'b0}};
        owner_busy = {OWNER_ENTRIES{1'b0}};
        for (owner_init_index = 0; owner_init_index < OWNER_ENTRIES;
             owner_init_index = owner_init_index + 1) begin
            owner_id[owner_init_index] = {WORD_WIDTH{1'b0}};
            owner_slot[owner_init_index] = {QUEUE_SLOT_WIDTH{1'b0}};
        end
        for (init_index = 0; init_index < DEPTH; init_index = init_index + 1)
            order_queue[init_index] = {WORD_WIDTH{1'b0}};
    end

    always @(posedge clk) begin
        if (i_ce) begin
            past_valid <= 1'b1;

            if (scope_close)
                window <= 1'b0;
            else if (scope_open)
                window <= 1'b1;

            case (state)
                ROUTE: state <= GRANT;
                GRANT: state <= ROUTE;
                default: state <= ROUTE;
            endcase

            grant_valid <= dequeue;
            if (dequeue) begin
                grant_id <= order_queue[head];
                head <= (head == DEPTH - 16'd1) ? 16'd0 : head + 16'd1;
            end

            if (accept_request) begin
                order_queue[tail] <= requester_id;
                tail <= (tail == DEPTH - 16'd1) ? 16'd0 : tail + 16'd1;
            end

            case ({accept_request, dequeue})
                2'b10: count <= count + 16'd1;
                2'b01: count <= count - 16'd1;
                default: count <= count;
            endcase

            if (dequeue && retire_found)
                owner_busy[retire_index] <= 1'b0;
            if (accept_request) begin
                owner_busy[alloc_index] <= 1'b1;
                owner_id[alloc_index] <= requester_id;
                owner_slot[alloc_index] <= tail[QUEUE_SLOT_WIDTH-1:0];
            end

            // Watch one accepted request until its FIFO-ordered grant.
            // The budget counts enabled cycles, including ROUTE cycles.
            if (outstanding) begin
                if (remaining != 16'd0)
                    remaining <= remaining - 16'd1;
                if (watched_grant) begin
                    outstanding <= 1'b0;
                    deadline_expired <= 1'b0;
                end else if (remaining <= 16'd1) begin
                    deadline_expired <= 1'b1;
                end
            end else if (accept_request && watch_request) begin
                outstanding <= 1'b1;
                watched_slot <= tail;
                remaining <= BUDGET;
                deadline_expired <= 1'b0;
            end
        end
    end

    // Within the latched scope, an outstanding request must not
    // acquire an expiration while its outstanding status stays unchanged.
    always @(posedge clk)
        if (past_valid && window && outstanding && $stable(outstanding))
            assert ($stable(deadline_expired));

    always @(posedge clk)
        if (past_valid && i_ce && dequeue)
            assert (retire_found && !retire_multiple &&
                    (owner_id[retire_index] == order_queue[head]));
endmodule

module request_latency_profiler #(
    parameter integer ENTRIES = 4,
    parameter integer BINS = 4,
    parameter integer LIMIT = 32,
    parameter integer TAG_WIDTH = 4,
    parameter integer AGE_WIDTH = $clog2(LIMIT+1),
    parameter integer SAMPLE_WIDTH = 16
) (
    input wire clk,
    input wire i_ce,
    input wire issue_valid,
    input wire [TAG_WIDTH-1:0] issue_tag,
    output wire issue_ready,
    input wire completion_valid,
    input wire [TAG_WIDTH-1:0] completion_tag,
    output reg completion_match,
    output reg [$clog2(ENTRIES)-1:0] completion_match_index,
    output reg [ENTRIES-1:0] busy,
    output reg [ENTRIES*TAG_WIDTH-1:0] tracked_tags,
    output reg [ENTRIES*AGE_WIDTH-1:0] tracked_ages,
    output reg [$clog2(ENTRIES+1)-1:0] active_count,
    output reg [AGE_WIDTH-1:0] last_latency, min_latency, peak_latency,
    output reg [SAMPLE_WIDTH-1:0] samples,
    output reg [31:0] total_latency,
    output reg [BINS*SAMPLE_WIDTH-1:0] histogram
);
    localparam integer INDEX_WIDTH = $clog2(ENTRIES);
    reg [INDEX_WIDTH-1:0] free_index;
    reg [AGE_WIDTH-1:0] selected_age, completed_latency;
    integer scan_index, bin_index, bucket;
    integer init_index, update_index;
    assign issue_ready = active_count < ENTRIES;

    always @(*) begin
        active_count = 0;
        free_index = 0;
        completion_match = 1'b0;
        completion_match_index = 0;
        selected_age = 0;
        for (scan_index = 0; scan_index < ENTRIES; scan_index = scan_index + 1) begin
            active_count = active_count + busy[scan_index];
            if (!busy[scan_index])
                free_index = scan_index;
            if (busy[scan_index] &&
                tracked_tags[scan_index*TAG_WIDTH +: TAG_WIDTH] == completion_tag) begin
                completion_match = 1'b1;
                completion_match_index = scan_index;
                selected_age = tracked_ages[scan_index*AGE_WIDTH +: AGE_WIDTH];
            end
        end
        completed_latency = selected_age + 1'b1;
        bucket = 0;
        for (bin_index = 0; bin_index < BINS-1; bin_index = bin_index + 1)
            if (completed_latency > ((bin_index+1)*LIMIT)/BINS)
                bucket = bin_index + 1;
    end

    initial begin
        busy = {ENTRIES{1'b0}};
        last_latency = 0;
        min_latency = LIMIT;
        peak_latency = 0;
        samples = 0;
        total_latency = 0;
        for (init_index = 0; init_index < ENTRIES; init_index = init_index + 1) begin
            tracked_tags[init_index*TAG_WIDTH +: TAG_WIDTH] = 0;
            tracked_ages[init_index*AGE_WIDTH +: AGE_WIDTH] = 0;
        end
        for (init_index = 0; init_index < BINS; init_index = init_index + 1)
            histogram[init_index*SAMPLE_WIDTH +: SAMPLE_WIDTH] = 0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            for (update_index = 0; update_index < ENTRIES; update_index = update_index + 1) begin
                if (busy[update_index]) begin
                    tracked_ages[update_index*AGE_WIDTH +: AGE_WIDTH] <=
                        tracked_ages[update_index*AGE_WIDTH +: AGE_WIDTH] + 1'b1;
                    if (completion_valid &&
                        tracked_tags[update_index*TAG_WIDTH +: TAG_WIDTH] == completion_tag) begin
                        busy[update_index] <= 1'b0;
                        tracked_ages[update_index*AGE_WIDTH +: AGE_WIDTH] <= 0;
                    end
                end
            end
            if (issue_valid && issue_ready) begin
                busy[free_index] <= 1'b1;
                tracked_tags[free_index*TAG_WIDTH +: TAG_WIDTH] <= issue_tag;
                tracked_ages[free_index*AGE_WIDTH +: AGE_WIDTH] <= 0;
            end
            if (completion_valid && completion_match) begin
                last_latency <= completed_latency;
                if (completed_latency < min_latency)
                    min_latency <= completed_latency;
                if (completed_latency > peak_latency)
                    peak_latency <= completed_latency;
                samples <= samples + 1'b1;
                total_latency <= total_latency + completed_latency;
                if (histogram[bucket*SAMPLE_WIDTH +: SAMPLE_WIDTH] != {SAMPLE_WIDTH{1'b1}})
                    histogram[bucket*SAMPLE_WIDTH +: SAMPLE_WIDTH] <=
                        histogram[bucket*SAMPLE_WIDTH +: SAMPLE_WIDTH] + 1'b1;
            end
        end
    end
endmodule

module request_completion_fold #(
    parameter integer WORD_WIDTH = 16,
    parameter integer SLOTS = 4
) (
    input  wire clk,
    input  wire i_ce,
    input  wire reserve_valid,
    output wire reserve_ready,
    input  wire completion_valid,
    input  wire [WORD_WIDTH-1:0] completion_data,
    output wire completion_ready,
    output reg [$clog2(SLOTS+1)-1:0] used,
    output reg [$clog2(SLOTS+1)-1:0] fill,
    output reg [WORD_WIDTH-1:0] signature,
    output wire fold_valid
);
    localparam integer PTR_WIDTH = $clog2(SLOTS);
    localparam integer COUNT_WIDTH = $clog2(SLOTS+1);
    localparam integer FOLD_CYCLES = 4;
    localparam integer PHASE_WIDTH = $clog2(FOLD_CYCLES);
    reg [WORD_WIDTH-1:0] records [0:SLOTS-1];
    reg [PTR_WIDTH-1:0] rd_ptr, wr_ptr;
    reg [PHASE_WIDTH-1:0] phase;
    integer init_index;

    wire reserve = reserve_valid && reserve_ready;
    wire push = completion_valid && completion_ready;
    wire fold = (phase == FOLD_CYCLES-1) && (fill != 0);
    assign reserve_ready = used < SLOTS;
    assign completion_ready = fill < SLOTS;
    assign fold_valid = i_ce && fold;

    initial begin
        used = {COUNT_WIDTH{1'b0}};
        fill = {COUNT_WIDTH{1'b0}};
        signature = {WORD_WIDTH{1'b0}};
        rd_ptr = {PTR_WIDTH{1'b0}};
        wr_ptr = {PTR_WIDTH{1'b0}};
        phase = {PHASE_WIDTH{1'b0}};
        for (init_index = 0; init_index < SLOTS; init_index = init_index + 1)
            records[init_index] = {WORD_WIDTH{1'b0}};
    end

    always @(posedge clk) begin
        if (i_ce) begin
            phase <= (phase == FOLD_CYCLES-1)
                ? {PHASE_WIDTH{1'b0}} : phase + 1'b1;
            if (push) begin
                records[wr_ptr] <= completion_data;
                wr_ptr <= (wr_ptr == SLOTS-1)
                    ? {PTR_WIDTH{1'b0}} : wr_ptr + 1'b1;
            end
            if (fold) begin
                signature <= ((signature << 1) |
                    (signature >> (WORD_WIDTH-1))) ^ records[rd_ptr];
                rd_ptr <= (rd_ptr == SLOTS-1)
                    ? {PTR_WIDTH{1'b0}} : rd_ptr + 1'b1;
            end
            case ({reserve, fold})
                2'b10: used <= used + 1'b1;
                2'b01: used <= used - 1'b1;
                default: used <= used;
            endcase
            case ({push, fold})
                2'b10: fill <= fill + 1'b1;
                2'b01: fill <= fill - 1'b1;
                default: fill <= fill;
            endcase
        end
    end
endmodule

module ordered_request_arbiter #(
    parameter logic [15:0] DEPTH = 16'd16,
    parameter integer WORD_WIDTH = 16,
    parameter integer TRACE_DEPTH = 4,
    parameter integer PROFILE_SLOTS = 4,
    parameter integer LATENCY_BINS = 4
) (
    input  wire clk,
    input  wire i_ce,
    input  wire request_valid,
    input  wire [WORD_WIDTH-1:0] requester_id,
    input  wire watch_request,
    input  wire scope_open,
    input  wire scope_close,
    output wire request_ready,
    output reg grant_valid,
    output reg [WORD_WIDTH-1:0] grant_id,
    output wire [$clog2(TRACE_DEPTH+1)-1:0] trace_used,
    output wire [$clog2(TRACE_DEPTH+1)-1:0] trace_count,
    output wire [WORD_WIDTH-1:0] trace_signature,
    output wire trace_fold_valid,
    output wire profile_ready,
    output wire [PROFILE_SLOTS-1:0] profile_busy,
    output wire [PROFILE_SLOTS*$clog2(DEPTH)-1:0] profile_slot_words,
    output wire [PROFILE_SLOTS*$clog2(DEPTH+DEPTH+1)-1:0] profile_age_words,
    output wire [$clog2(PROFILE_SLOTS+1)-1:0] profile_active,
    output wire [$clog2(DEPTH+DEPTH+1)-1:0] profile_last,
    output wire [$clog2(DEPTH+DEPTH+1)-1:0] profile_min,
    output wire [$clog2(DEPTH+DEPTH+1)-1:0] profile_peak,
    output wire [15:0] profile_samples,
    output wire [31:0] profile_total_latency,
    output wire [LATENCY_BINS*16-1:0] profile_histogram
);
    localparam logic [15:0] BUDGET = DEPTH + DEPTH;
    localparam integer PROFILE_TAG_WIDTH = $clog2(DEPTH);
    localparam integer PROFILE_AGE_WIDTH = $clog2(DEPTH+DEPTH+1);

    typedef enum logic [1:0] {
        ROUTE = 2'b00,
        GRANT = 2'b01
    } state_t;
    state_t state;

    reg [WORD_WIDTH-1:0] order_queue [0:DEPTH-1];
    reg [15:0] head, tail, count;
    reg [15:0] watched_slot, remaining;
    reg outstanding, deadline_expired;
    reg window, past_valid;
    integer init_index;
    wire trace_reserve_ready, trace_completion_ready;
    wire profile_match;
    wire [$clog2(PROFILE_SLOTS)-1:0] profile_match_index;
    wire [15:0] profile_slot [0:PROFILE_SLOTS-1];
    wire [PROFILE_AGE_WIDTH-1:0] profile_age [0:PROFILE_SLOTS-1];
    wire [15:0] profile_distance [0:PROFILE_SLOTS-1];
    wire [15:0] profile_service_rank [0:PROFILE_SLOTS-1];
    genvar profile_index;
    generate
        for (profile_index = 0; profile_index < PROFILE_SLOTS; profile_index = profile_index + 1) begin: profile_decode
            assign profile_slot[profile_index] =
                profile_slot_words[profile_index*PROFILE_TAG_WIDTH +: PROFILE_TAG_WIDTH];
            assign profile_age[profile_index] =
                profile_age_words[profile_index*PROFILE_AGE_WIDTH +: PROFILE_AGE_WIDTH];
            assign profile_distance[profile_index] = (profile_slot[profile_index] >= head)
                ? (profile_slot[profile_index] - head)
                : (profile_slot[profile_index] + DEPTH - head);
            assign profile_service_rank[profile_index] =
                profile_distance[profile_index] + profile_distance[profile_index]
                + ((state == GRANT) ? 16'd1 : 16'd2);
        end
    endgenerate

    wire accept_request = request_valid && request_ready;
    wire dequeue = (state == GRANT) && (count != 16'd0)
        && trace_completion_ready;
    wire watched_grant = dequeue && (head == watched_slot);

    wire [15:0] queue_distance = (watched_slot >= head)
        ? (watched_slot - head)
        : (watched_slot + DEPTH - head);
    wire [15:0] service_rank = queue_distance + queue_distance
        + ((state == GRANT) ? 16'd1 : 16'd2);

    assign request_ready = (count < DEPTH) && trace_reserve_ready && profile_ready;

    request_completion_fold #(
        .WORD_WIDTH(WORD_WIDTH), .SLOTS(TRACE_DEPTH)
    ) completion_fold (
        .clk(clk), .i_ce(i_ce),
        .reserve_valid(accept_request),
        .reserve_ready(trace_reserve_ready),
        .completion_valid(dequeue),
        .completion_data(order_queue[head]),
        .completion_ready(trace_completion_ready),
        .used(trace_used), .fill(trace_count),
        .signature(trace_signature), .fold_valid(trace_fold_valid)
    );

    request_latency_profiler #(
        .ENTRIES(PROFILE_SLOTS), .BINS(LATENCY_BINS), .LIMIT(BUDGET),
        .TAG_WIDTH(PROFILE_TAG_WIDTH), .AGE_WIDTH(PROFILE_AGE_WIDTH)
    ) latency_profiler (
        .clk(clk), .i_ce(i_ce),
        .issue_valid(accept_request),
        .issue_tag(tail[PROFILE_TAG_WIDTH-1:0]),
        .issue_ready(profile_ready),
        .completion_valid(dequeue),
        .completion_tag(head[PROFILE_TAG_WIDTH-1:0]),
        .completion_match(profile_match),
        .completion_match_index(profile_match_index),
        .busy(profile_busy), .tracked_tags(profile_slot_words),
        .tracked_ages(profile_age_words), .active_count(profile_active),
        .last_latency(profile_last), .min_latency(profile_min),
        .peak_latency(profile_peak), .samples(profile_samples),
        .total_latency(profile_total_latency), .histogram(profile_histogram)
    );

    initial begin
        state = ROUTE;
        head = 16'd0;
        tail = 16'd0;
        count = 16'd0;
        watched_slot = 16'd0;
        remaining = 16'd0;
        outstanding = 1'b0;
        deadline_expired = 1'b0;
        window = 1'b0;
        past_valid = 1'b0;
        grant_valid = 1'b0;
        grant_id = {WORD_WIDTH{1'b0}};
        for (init_index = 0; init_index < DEPTH; init_index = init_index + 1)
            order_queue[init_index] = {WORD_WIDTH{1'b0}};
    end

    always @(posedge clk) begin
        if (i_ce) begin
            past_valid <= 1'b1;

            if (scope_close)
                window <= 1'b0;
            else if (scope_open)
                window <= 1'b1;

            case (state)
                ROUTE: state <= GRANT;
                GRANT: state <= ROUTE;
                default: state <= ROUTE;
            endcase

            grant_valid <= dequeue;
            if (dequeue) begin
                grant_id <= order_queue[head];
                head <= (head == DEPTH - 16'd1) ? 16'd0 : head + 16'd1;
            end

            if (accept_request) begin
                order_queue[tail] <= requester_id;
                tail <= (tail == DEPTH - 16'd1) ? 16'd0 : tail + 16'd1;
            end

            case ({accept_request, dequeue})
                2'b10: count <= count + 16'd1;
                2'b01: count <= count - 16'd1;
                default: count <= count;
            endcase

            // Watch one accepted request until its FIFO-ordered grant.
            // The budget counts enabled cycles, including ROUTE cycles.
            if (outstanding) begin
                if (remaining != 16'd0)
                    remaining <= remaining - 16'd1;
                if (watched_grant) begin
                    outstanding <= 1'b0;
                    deadline_expired <= 1'b0;
                end else if (remaining <= 16'd1) begin
                    deadline_expired <= 1'b1;
                end
            end else if (accept_request && watch_request) begin
                outstanding <= 1'b1;
                watched_slot <= tail;
                remaining <= BUDGET;
                deadline_expired <= 1'b0;
            end
        end
    end

    // Within the latched scope, an outstanding request must not
    // acquire an expiration while its outstanding status stays unchanged.
    always @(posedge clk)
        if (past_valid && window && outstanding && $stable(outstanding))
            assert ($stable(deadline_expired));

    always @(posedge clk)
        if (past_valid && i_ce && dequeue)
            assert (profile_match &&
                (profile_age_words[profile_match_index*PROFILE_AGE_WIDTH +: PROFILE_AGE_WIDTH] < BUDGET));
endmodule

module shader_ladder_engine #(
    parameter [31:0] SCALAR_WORDS = 32'd24,
    parameter [31:0] PREFETCH_DEPTH = 32'd4
) (
    input  wire clk,
    input  wire i_ce,
    input  wire i_req_valid,
    output wire o_req_ready,
    input  wire [SCALAR_WORDS*32'd32-32'd1:0] i_scalar,
    output wire o_done,
    output wire [31:0] o_point,
    output wire o_operand_wait,
    output wire [$clog2(PREFETCH_DEPTH):0] o_prefetch_level,
    output wire [$clog2(SCALAR_WORDS+32'd1)-1:0] o_fetch_remaining
);
    localparam [31:0] TOTAL_BITS = SCALAR_WORDS * 32'd32;
    localparam [31:0] LAST_WORD = SCALAR_WORDS - 32'd1;
    // The prefetch RAM uses a power-of-two depth and binary wrap pointers.
    localparam PREFETCH_ADDR_W = $clog2(PREFETCH_DEPTH);
    localparam FETCH_COUNT_W = $clog2(SCALAR_WORDS + 32'd1);

    // A small coordinate-processing accelerator, specialized to the subgroup
    // generated by G=(0,1) on y^2=x^3+1 over F_5.  G has order three.
    // Every finite subgroup point has x=0, so a 32-bit point word stores its
    // y coordinate: 1 denotes G, 4 denotes -G, and 0 denotes infinity.
    // This is an intentionally small elliptic-curve specialization, not a
    // cryptographic-strength curve.
    function automatic [31:0] ec_add;
        input [31:0] a;
        input [31:0] b;
        begin
            if (a == 32'd0)
                ec_add = b;
            else if (b == 32'd0)
                ec_add = a;
            else if (a != b)
                ec_add = 32'd0;
            else if (a == 32'd1)
                ec_add = 32'd4;
            else
                ec_add = 32'd1;
        end
    endfunction

    reg busy;
    reg done;
    reg pv;
    reg [31:0] word_index;
    reg [31:0] bit_index;
    reg [31:0] deadline;
    reg [31:0] pending_words;
    reg [31:0] scalar_reg;
    reg [31:0] point_lo;
    reg [31:0] point_hi;
    reg [31:0] result;
    reg [31:0] scalar_words [0:SCALAR_WORDS-32'd1];
    reg [SCALAR_WORDS-32'd1:0] word_valid;
    wire [SCALAR_WORDS-32'd1:0] limb_select;
    reg [31:0] prefetch_fifo [0:PREFETCH_DEPTH-32'd1];
    reg [PREFETCH_ADDR_W:0] prefetch_rd;
    reg [PREFETCH_ADDR_W:0] prefetch_wr;
    reg [FETCH_COUNT_W-1:0] fetch_remaining;
    reg [31:0] operand_word;
    reg operand_valid;
    reg scalar_loaded;
    integer prefetch_init;
    wire [PREFETCH_ADDR_W:0] prefetch_level = prefetch_wr - prefetch_rd;
    wire prefetch_empty = (prefetch_wr == prefetch_rd);
    wire prefetch_full =
        (prefetch_wr[PREFETCH_ADDR_W] != prefetch_rd[PREFETCH_ADDR_W]) &&
        (prefetch_wr[PREFETCH_ADDR_W-1:0] == prefetch_rd[PREFETCH_ADDR_W-1:0]);
    wire [FETCH_COUNT_W-1:0] fetch_address = fetch_remaining - 1'b1;
    wire ladder_step = busy && scalar_loaded;
    reg prefetch_push;
    reg prefetch_pop;
    reg operand_take;

    wire accept = i_req_valid && o_req_ready;
    assign o_req_ready = i_ce && !busy;
    assign o_done = done;
    assign o_point = result;
    assign o_operand_wait = busy && !scalar_loaded;
    assign o_prefetch_level = prefetch_level;
    assign o_fetch_remaining = fetch_remaining;

    always @(*) begin
        prefetch_push = 1'b0;
        prefetch_pop = 1'b0;
        operand_take = 1'b0;
        if (i_ce && busy) begin
            if ((fetch_remaining != 0) && !prefetch_full) begin
                prefetch_push = 1'b1;
            end
            if (!scalar_loaded && operand_valid) begin
                operand_take = 1'b1;
            end
            if (!prefetch_empty && (!operand_valid || operand_take)) begin
                prefetch_pop = 1'b1;
            end
        end
    end

    // Uniform Montgomery-ladder add-and-double datapath.  Both candidate
    // doubles and the sum are formed independently of the scalar bit.
    wire [31:0] point_sum = ec_add(point_lo, point_hi);
    wire [31:0] double_lo = ec_add(point_lo, point_lo);
    wire [31:0] double_hi = ec_add(point_hi, point_hi);
    wire [31:0] next_lo = scalar_reg[31] ? point_sum : double_lo;
    wire [31:0] next_hi = scalar_reg[31] ? double_hi : point_sum;

    initial begin
        busy = 1'b0;
        done = 1'b0;
        pv = 1'b0;
        word_index = 32'd0;
        bit_index = 32'd0;
        deadline = 32'd0;
        pending_words = 32'd0;
        scalar_reg = 32'd0;
        point_lo = 32'd0;
        point_hi = 32'd1;
        result = 32'd0;
        word_valid = {SCALAR_WORDS{1'b0}};
        prefetch_rd = {(PREFETCH_ADDR_W+1){1'b0}};
        prefetch_wr = {(PREFETCH_ADDR_W+1){1'b0}};
        fetch_remaining = {FETCH_COUNT_W{1'b0}};
        operand_word = 32'd0;
        operand_valid = 1'b0;
        scalar_loaded = 1'b0;
        for (prefetch_init = 0; prefetch_init < PREFETCH_DEPTH; prefetch_init = prefetch_init + 1) begin
            prefetch_fifo[prefetch_init] = 32'd0;
        end
    end

    // A request atomically supplies all scalar limbs.  The receiver applies
    // back-pressure until that scalar has completed; no live limb is replaced.
    // Higher-numbered limbs are older in the MSB-first traversal.
    genvar g;
    generate
        for (g = 32'd0; g < SCALAR_WORDS; g = g + 32'd1) begin : limbs
            localparam [31:0] WORD_NO = g;
            assign limb_select[g] = busy && (word_index == WORD_NO);
            initial scalar_words[g] = 32'd0;
            always @(posedge clk) begin
                if (i_ce) begin
                    if (accept)
                        scalar_words[g] <= i_scalar[g*32'd32 +: 32'd32];
                    else if (limb_select[g] && scalar_loaded)
                        scalar_words[g] <= scalar_words[g] << 32'd1;
                end
            end
        end
    endgenerate

    // The RAM read register can retain the next limb throughout a ladder word.
    // A simultaneous issue and RAM read replaces that limb without a bubble.
    always @(posedge clk) begin
        if (i_ce) begin
            if (prefetch_push) begin
                prefetch_fifo[prefetch_wr[PREFETCH_ADDR_W-1:0]] <= scalar_words[fetch_address];
                prefetch_wr <= prefetch_wr + 1'b1;
            end
            if (prefetch_pop) begin
                prefetch_rd <= prefetch_rd + 1'b1;
            end
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (accept) begin
                fetch_remaining <= SCALAR_WORDS;
                operand_valid <= 1'b0;
            end else begin
                if (prefetch_push) begin
                    fetch_remaining <= fetch_remaining - 1'b1;
                end
                if (operand_take) begin
                    operand_valid <= 1'b0;
                end
                if (prefetch_pop) begin
                    operand_word <= prefetch_fifo[prefetch_rd[PREFETCH_ADDR_W-1:0]];
                    operand_valid <= 1'b1;
                end
            end
        end
    end

    // Prefetch and operand loading can wait without spending a ladder round.
    // The budget and scalar shifts advance together once an operand is loaded.
    // Clock enable also freezes the memory ports and all pipeline state.
    always @(posedge clk) begin
        if (i_ce)
            pv <= 1'b1;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (accept) begin
                busy <= 1'b1;
                done <= 1'b0;
                word_index <= LAST_WORD;
                bit_index <= 32'd31;
                deadline <= TOTAL_BITS;
                pending_words <= SCALAR_WORDS;
                scalar_reg <= 32'd0;
                scalar_loaded <= 1'b0;
                point_lo <= 32'd0;
                point_hi <= 32'd1;
                word_valid <= {SCALAR_WORDS{1'b1}};
            end else begin
                if (operand_take) begin
                    scalar_reg <= operand_word;
                    scalar_loaded <= 1'b1;
                end else if (ladder_step) begin
                deadline <= deadline - 32'd1;
                scalar_reg <= scalar_reg << 32'd1;
                point_lo <= next_lo;
                point_hi <= next_hi;
                if (bit_index != 32'd0) begin
                    bit_index <= bit_index - 32'd1;
                end else begin
                    pending_words <= pending_words - 32'd1;
                    scalar_loaded <= 1'b0;
                    word_valid[word_index] <= 1'b0;
                    if (word_index != 32'd0) begin
                        word_index <= word_index - 32'd1;
                        bit_index <= 32'd31;
                    end else begin
                        busy <= 1'b0;
                        done <= 1'b1;
                        result <= next_lo;
                    end
                end
            end
            end
        end
    end

    always @(posedge clk) begin
        if (pv && operand_take)
            assert (operand_word == scalar_words[word_index]);
    end

    // Globally scoped bounded response, expressed about the previous tick:
    // if the outstanding request used its last budget cycle, it must now
    // be complete.  Result and done remain available until the next request.
    always @(posedge clk) begin
        if (pv && $past(i_ce && busy))
            assert (!busy || ($past(deadline) > 32'd1));
    end
endmodule

module metric_exp2_pipe #(
    parameter integer PIPE_DEPTH = 32'd32,
    parameter integer LUT_ENTRIES = 32'd32
) (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        i_valid,
    input  wire [63:0] i_x,
    output wire        o_ready,
    output wire        o_valid,
    output wire [63:0] o_exp2,
    input  wire        i_out_ready,
    output wire [159:0] o_debug_stats,
    output wire [607:0] o_service_monitor
);
    // PIPE_DEPTH >= 3. LUT_ENTRIES is a power of two from 2 through 32.
    // Binary64 input and output; a table plus linear residual polynomial
    // approximates exp2. Inputs outside [0,32) are clamped before evaluation.
    localparam integer LUT_BITS = $clog2(LUT_ENTRIES);
    localparam [63:0] PIPE_CAPACITY = PIPE_DEPTH;
    localparam [63:0] LUT_SIZE = LUT_ENTRIES;
    localparam [63:0] Q30_ONE = 64'h0000000040000000;
    localparam [63:0] LN2_Q30 = 64'd744261118;
    localparam [63:0] RESIDUAL_MASK =
        (64'd1 << (32'd30 - LUT_BITS)) - 64'd1;

    reg [63:0] coeff_rom [0:LUT_ENTRIES-1];
    reg [LUT_ENTRIES-1:0] coeff_valid;
    reg [63:0] data_pipe [0:PIPE_DEPTH-1];
    reg [PIPE_DEPTH-1:0] pipe_valid;
    reg [63:0] integer_s0, integer_s1, residual_s0;
    reg [63:0] outstanding;

    // Q1.31 samples of 2^(j/32). Smaller supported tables subsample this ROM.
    function [63:0] rom_word;
        input [63:0] slot;
        reg [63:0] sample;
        begin
            sample = (slot * 64'd32) / LUT_SIZE;
            case (sample)
                64'd0:  rom_word = 64'h0000000080000000;
                64'd1:  rom_word = 64'h0000000082cd8699;
                64'd2:  rom_word = 64'h0000000085aac368;
                64'd3:  rom_word = 64'h0000000088980e81;
                64'd4:  rom_word = 64'h000000008b95c1e4;
                64'd5:  rom_word = 64'h000000008ea4398b;
                64'd6:  rom_word = 64'h0000000091c3d373;
                64'd7:  rom_word = 64'h0000000094f4efa9;
                64'd8:  rom_word = 64'h000000009837f052;
                64'd9:  rom_word = 64'h000000009b8d39ba;
                64'd10: rom_word = 64'h000000009ef53261;
                64'd11: rom_word = 64'h00000000a2704303;
                64'd12: rom_word = 64'h00000000a5fed6aa;
                64'd13: rom_word = 64'h00000000a9a15ab5;
                64'd14: rom_word = 64'h00000000ad583eea;
                64'd15: rom_word = 64'h00000000b123f582;
                64'd16: rom_word = 64'h00000000b504f334;
                64'd17: rom_word = 64'h00000000b8fbaf47;
                64'd18: rom_word = 64'h00000000bd08a39f;
                64'd19: rom_word = 64'h00000000c12c4cca;
                64'd20: rom_word = 64'h00000000c5672a11;
                64'd21: rom_word = 64'h00000000c9b9bd86;
                64'd22: rom_word = 64'h00000000ce248c15;
                64'd23: rom_word = 64'h00000000d2a81d91;
                64'd24: rom_word = 64'h00000000d744fcca;
                64'd25: rom_word = 64'h00000000dbfbb798;
                64'd26: rom_word = 64'h00000000e0ccdeec;
                64'd27: rom_word = 64'h00000000e5b906e7;
                64'd28: rom_word = 64'h00000000eac0c6e8;
                64'd29: rom_word = 64'h00000000efe4b99c;
                64'd30: rom_word = 64'h00000000f5257d15;
                64'd31: rom_word = 64'h00000000fa83b2db;
                default: rom_word = 64'h0000000080000000;
            endcase
        end
    endfunction

    initial begin
        coeff_valid = {LUT_ENTRIES{1'b1}};
        pipe_valid = {PIPE_DEPTH{1'b0}};
        integer_s0 = 64'd0;
        integer_s1 = 64'd0;
        residual_s0 = 64'd0;
        outstanding = 64'd0;
        for (integer n = 32'd0; n < LUT_ENTRIES; n = n + 32'd1)
            coeff_rom[n] = rom_word(n);
        for (integer n = 32'd0; n < PIPE_DEPTH; n = n + 32'd1)
            data_pipe[n] = 64'd0;
    end

    // Convert binary64 to unsigned Q5.59, saturating at the upper endpoint.
    wire [63:0] input_exponent = {53'd0, i_x[62:52]};
    wire [63:0] input_significand = {11'd0, 1'b1, i_x[51:0]};
    wire [63:0] x_fixed = i_x[63] ? 64'd0 :
        ((input_exponent >= 64'd1028) ? 64'hffffffffffffffff :
         ((input_exponent >= 64'd1016) ?
          (input_significand << (input_exponent - 64'd1016)) :
          (input_significand >> (64'd1016 - input_exponent))));

    wire [63:0] table_index =
        (x_fixed >> (32'd59 - LUT_BITS)) & (LUT_SIZE - 64'd1);
    wire [63:0] input_integer = x_fixed >> 64'd59;
    wire [63:0] input_residual = (x_fixed >> 64'd29) & RESIDUAL_MASK;

    // The entire pipeline freezes behind a blocked output. Thus an occupied
    // stage is never overwritten before its item advances or is consumed.
    wire advance = i_ce && (!pipe_valid[PIPE_DEPTH-1] || i_out_ready);
    wire take = i_valid && coeff_valid[table_index];
    assign o_ready = advance && coeff_valid[table_index];
    assign o_valid = i_ce && pipe_valid[PIPE_DEPTH-1];
    assign o_exp2 = data_pipe[PIPE_DEPTH-1];

    // Read-only diagnostic bank; all counters saturate rather than wrap.
    reg [15:0] dbg_cycles;
    reg [15:0] dbg_accept_count;
    reg [15:0] dbg_retire_count;
    reg [15:0] dbg_blocked_cycles;
    reg [15:0] dbg_paused_cycles;
    reg [15:0] dbg_clamp_count;
    reg [15:0] dbg_special_count;
    reg [15:0] dbg_subnormal_count;
    reg [15:0] dbg_stall_run;
    reg [15:0] dbg_stall_peak;
    wire dbg_accept = i_valid && o_ready;
    wire dbg_retire = o_valid && i_out_ready;
    wire dbg_blocked = i_ce && pipe_valid[PIPE_DEPTH-1] && !i_out_ready;
    wire dbg_clamped = i_x[63] || (input_exponent >= 64'd1028);
    initial begin
        dbg_cycles = 16'd0;
        dbg_accept_count = 16'd0;
        dbg_retire_count = 16'd0;
        dbg_blocked_cycles = 16'd0;
        dbg_paused_cycles = 16'd0;
        dbg_clamp_count = 16'd0;
        dbg_special_count = 16'd0;
        dbg_subnormal_count = 16'd0;
        dbg_stall_run = 16'd0;
        dbg_stall_peak = 16'd0;
    end
    assign o_debug_stats = {
        dbg_cycles, dbg_accept_count,
        dbg_retire_count, dbg_blocked_cycles,
        dbg_paused_cycles, dbg_clamp_count,
        dbg_special_count, dbg_subnormal_count,
        dbg_stall_run, dbg_stall_peak
    };
    always @(posedge clk) begin
        if (dbg_cycles != 16'hffff)
            dbg_cycles <= dbg_cycles + 16'd1;
        if (dbg_accept) begin
            if (dbg_accept_count != 16'hffff)
                dbg_accept_count <= dbg_accept_count + 16'd1;
            if (dbg_clamped && dbg_clamp_count != 16'hffff)
                dbg_clamp_count <= dbg_clamp_count + 16'd1;
            if (input_exponent == 64'd2047 && dbg_special_count != 16'hffff)
                dbg_special_count <= dbg_special_count + 16'd1;
            if (input_exponent == 64'd0 && i_x[51:0] != 52'd0 &&
                dbg_subnormal_count != 16'hffff)
                dbg_subnormal_count <= dbg_subnormal_count + 16'd1;
        end
        if (dbg_retire && dbg_retire_count != 16'hffff)
            dbg_retire_count <= dbg_retire_count + 16'd1;
        if (!i_ce && dbg_paused_cycles != 16'hffff)
            dbg_paused_cycles <= dbg_paused_cycles + 16'd1;
        if (dbg_blocked) begin
            if (dbg_blocked_cycles != 16'hffff)
                dbg_blocked_cycles <= dbg_blocked_cycles + 16'd1;
            if (dbg_stall_run != 16'hffff) begin
                dbg_stall_run <= dbg_stall_run + 16'd1;
                if (dbg_stall_run >= dbg_stall_peak)
                    dbg_stall_peak <= dbg_stall_run + 16'd1;
            end
        end else begin
            dbg_stall_run <= 16'd0;
        end
    end

    // Stage 1: table_base * (1 + ln(2)*residual).
    // The table is Q1.31 and the residual polynomial is Q2.30.
    wire [63:0] linear_product = LN2_Q30 * residual_s0;
    wire [63:0] residual_polynomial =
        Q30_ONE + (linear_product >> 64'd30);
    wire [63:0] fractional_product = data_pipe[0] * residual_polynomial;
    wire [63:0] fractional_q30 = fractional_product >> 64'd31;
    wire [63:0] result_exponent = 64'd1023 + integer_s1;

    always @(posedge clk) begin
        if (advance) begin
            pipe_valid <= {pipe_valid[PIPE_DEPTH-2:0], take};
            data_pipe[0] <= coeff_rom[table_index];
            integer_s0 <= input_integer;
            residual_s0 <= input_residual;
            data_pipe[1] <= fractional_q30;
            integer_s1 <= integer_s0;
            // Stage 2: put the integer part in the binary64 exponent.
            data_pipe[2] <= {
                1'b0, result_exponent[10:0], data_pipe[1][29:0], 22'd0
            };
            for (integer s = 32'd3; s < PIPE_DEPTH; s = s + 32'd1)
                data_pipe[s] <= data_pipe[s-1];

            case ({take, pipe_valid[PIPE_DEPTH-1]})
                2'b10: outstanding <= outstanding + 64'd1;
                2'b01: outstanding <= outstanding - 64'd1;
                default: outstanding <= outstanding;
            endcase
        end
    end

    // Fixed stage positions encode order; no arbitration or age tags are used.
    reg [63:0] occupied_slots;
    always @(*) begin
        occupied_slots = 64'd0;
        for (integer p = 32'd0; p < PIPE_DEPTH; p = p + 32'd1)
            occupied_slots = occupied_slots + {63'd0, pipe_valid[p]};
    end

    // Passive watchdog and circular event history; never controls the pipe.
    reg [31:0] mon_timestamp;
    reg [15:0] mon_wait_age;
    reg [15:0] mon_block_age;
    reg [15:0] mon_block_peak;
    reg [15:0] mon_timeout_count;
    reg [15:0] mon_event_count;
    reg [7:0] mon_sticky_events;
    reg [1:0] mon_trace_head;
    reg [3:0] mon_trace_valid;
    reg [95:0] mon_trace [0:3];
    reg [31:0] mon_signature;
    reg [63:0] mon_first_timeout;
    wire mon_timeout_event = i_ce && !dbg_retire &&
        (outstanding != 64'd0) && (mon_wait_age == 16'd1023);
    wire mon_stall_event = dbg_blocked && (mon_block_age == 16'd255);
    wire [7:0] mon_events = {
        (dbg_accept && input_exponent == 64'd2047 &&
         i_x[51:0] != 52'd0),
        (dbg_accept && input_exponent == 64'd2047 &&
         i_x[51:0] == 52'd0),
        (dbg_accept && i_x[63]),
        (dbg_accept && !i_x[63] &&
         input_exponent >= 64'd1028),
        mon_stall_event,
        mon_timeout_event,
        (dbg_retire && mon_wait_age >= 16'd1024),
        (dbg_accept && outstanding == 64'd0)
    };
    wire [95:0] mon_event_record = {
        mon_timestamp, mon_events, i_x[63:52],
        mon_block_age, mon_wait_age, occupied_slots[11:0]
    };

    initial begin
        mon_timestamp = 32'd0;
        mon_wait_age = 16'd0;
        mon_block_age = 16'd0;
        mon_block_peak = 16'd0;
        mon_timeout_count = 16'd0;
        mon_event_count = 16'd0;
        mon_sticky_events = 8'd0;
        mon_trace_head = 2'd0;
        mon_trace_valid = 4'd0;
        mon_signature = 32'd0;
        mon_first_timeout = 64'd0;
        for (integer e = 32'd0; e < 32'd4; e = e + 32'd1)
            mon_trace[e] = 96'd0;
    end

    assign o_service_monitor = {
        mon_trace[3], mon_trace[2],
        mon_trace[1], mon_trace[0],
        mon_first_timeout,
        mon_signature, mon_timestamp, mon_wait_age,
        mon_block_age, mon_block_peak, mon_timeout_count,
        mon_event_count, mon_sticky_events,
        mon_trace_valid, mon_trace_head, 2'b00
    };

    always @(posedge clk) begin
        mon_timestamp <= mon_timestamp + 32'd1;
        if (dbg_accept || dbg_retire)
            mon_signature <= {mon_signature[26:0], mon_signature[31:27]} ^
                (dbg_accept ? (i_x[31:0] ^ i_x[63:32]) : 32'd0) ^
                (dbg_retire ? (o_exp2[31:0] ^ o_exp2[63:32]) : 32'd0);
        if (i_ce) begin
            if (dbg_retire || outstanding == 64'd0)
                mon_wait_age <= 16'd0;
            else if (mon_wait_age != 16'hffff)
                mon_wait_age <= mon_wait_age + 16'd1;
            if (dbg_blocked) begin
                if (mon_block_age != 16'hffff) begin
                    mon_block_age <= mon_block_age + 16'd1;
                    if (mon_block_age >= mon_block_peak)
                        mon_block_peak <= mon_block_age + 16'd1;
                end
            end else begin
                mon_block_age <= 16'd0;
            end
        end
        if (mon_timeout_event) begin
            if (!mon_sticky_events[2])
                mon_first_timeout <= {
                    mon_timestamp, mon_wait_age, mon_block_age
                };
            if (mon_timeout_count != 16'hffff)
                mon_timeout_count <= mon_timeout_count + 16'd1;
        end
        if (|mon_events) begin
            mon_trace[mon_trace_head] <= mon_event_record;
            mon_trace_head <= mon_trace_head + 2'd1;
            mon_trace_valid[mon_trace_head] <= 1'b1;
            mon_sticky_events <= mon_sticky_events | mon_events;
            if (mon_event_count != 16'hffff)
                mon_event_count <= mon_event_count + 16'd1;
        end
    end

    assert property (outstanding <= PIPE_CAPACITY);
endmodule

module metric_exp2_pipe #(
    parameter integer PIPE_DEPTH = 32'd32,
    parameter integer LUT_ENTRIES = 32'd32
) (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        i_valid,
    input  wire [63:0] i_x,
    input  wire        i_peer_valid,
    input  wire [63:0] i_peer_x,
    output wire        o_peer_ready,
    output wire        o_lane,
    output wire        o_ready,
    output wire        o_valid,
    output wire [63:0] o_exp2,
    input  wire        i_out_ready
);
    // PIPE_DEPTH >= 3. LUT_ENTRIES is a power of two from 2 through 32.
    // Binary64 input and output; a table plus linear residual polynomial
    // approximates exp2. Inputs outside [0,32) are clamped before evaluation.
    localparam integer LUT_BITS = $clog2(LUT_ENTRIES);
    localparam [63:0] PIPE_CAPACITY = PIPE_DEPTH;
    localparam [63:0] LUT_SIZE = LUT_ENTRIES;
    localparam [63:0] Q30_ONE = 64'h0000000040000000;
    localparam [63:0] LN2_Q30 = 64'd744261118;
    localparam [63:0] RESIDUAL_MASK =
        (64'd1 << (32'd30 - LUT_BITS)) - 64'd1;
    localparam integer CHANNELS = 2;
    localparam integer PEER_DEPTH = 4;
    localparam integer PEER_PTR_BITS = $clog2(PEER_DEPTH);

    reg [63:0] coeff_rom [0:LUT_ENTRIES-1];
    reg [LUT_ENTRIES-1:0] coeff_valid;
    reg [63:0] data_pipe [0:PIPE_DEPTH-1];
    reg [PIPE_DEPTH-1:0] pipe_valid;
    reg [63:0] integer_s0, integer_s1, residual_s0;
    reg [63:0] outstanding;
    reg [63:0] peer_q [0:PEER_DEPTH-1];
    reg [PEER_PTR_BITS-1:0] peer_rd, peer_wr;
    reg [$clog2(PEER_DEPTH+1)-1:0] peer_count;
    reg prefer_peer, port_locked;
    reg [$clog2(CHANNELS)-1:0] port_owner;

    // Q1.31 samples of 2^(j/32). Smaller supported tables subsample this ROM.
    function [63:0] rom_word;
        input [63:0] slot;
        reg [63:0] sample;
        begin
            sample = (slot * 64'd32) / LUT_SIZE;
            case (sample)
                64'd0:  rom_word = 64'h0000000080000000;
                64'd1:  rom_word = 64'h0000000082cd8699;
                64'd2:  rom_word = 64'h0000000085aac368;
                64'd3:  rom_word = 64'h0000000088980e81;
                64'd4:  rom_word = 64'h000000008b95c1e4;
                64'd5:  rom_word = 64'h000000008ea4398b;
                64'd6:  rom_word = 64'h0000000091c3d373;
                64'd7:  rom_word = 64'h0000000094f4efa9;
                64'd8:  rom_word = 64'h000000009837f052;
                64'd9:  rom_word = 64'h000000009b8d39ba;
                64'd10: rom_word = 64'h000000009ef53261;
                64'd11: rom_word = 64'h00000000a2704303;
                64'd12: rom_word = 64'h00000000a5fed6aa;
                64'd13: rom_word = 64'h00000000a9a15ab5;
                64'd14: rom_word = 64'h00000000ad583eea;
                64'd15: rom_word = 64'h00000000b123f582;
                64'd16: rom_word = 64'h00000000b504f334;
                64'd17: rom_word = 64'h00000000b8fbaf47;
                64'd18: rom_word = 64'h00000000bd08a39f;
                64'd19: rom_word = 64'h00000000c12c4cca;
                64'd20: rom_word = 64'h00000000c5672a11;
                64'd21: rom_word = 64'h00000000c9b9bd86;
                64'd22: rom_word = 64'h00000000ce248c15;
                64'd23: rom_word = 64'h00000000d2a81d91;
                64'd24: rom_word = 64'h00000000d744fcca;
                64'd25: rom_word = 64'h00000000dbfbb798;
                64'd26: rom_word = 64'h00000000e0ccdeec;
                64'd27: rom_word = 64'h00000000e5b906e7;
                64'd28: rom_word = 64'h00000000eac0c6e8;
                64'd29: rom_word = 64'h00000000efe4b99c;
                64'd30: rom_word = 64'h00000000f5257d15;
                64'd31: rom_word = 64'h00000000fa83b2db;
                default: rom_word = 64'h0000000080000000;
            endcase
        end
    endfunction

    initial begin
        coeff_valid = {LUT_ENTRIES{1'b1}};
        pipe_valid = {PIPE_DEPTH{1'b0}};
        integer_s0 = 64'd0;
        integer_s1 = 64'd0;
        residual_s0 = 64'd0;
        outstanding = 64'd0;
        peer_rd = {PEER_PTR_BITS{1'b0}};
        peer_wr = {PEER_PTR_BITS{1'b0}};
        peer_count = 3'd0;
        prefer_peer = 1'b0;
        port_locked = 1'b0;
        port_owner = 1'b0;
        for (integer n = 32'd0; n < PEER_DEPTH; n = n + 32'd1)
            peer_q[n] = 64'd0;
        for (integer n = 32'd0; n < LUT_ENTRIES; n = n + 32'd1)
            coeff_rom[n] = rom_word(n);
        for (integer n = 32'd0; n < PIPE_DEPTH; n = n + 32'd1)
            data_pipe[n] = 64'd0;
    end

    // Convert binary64 to unsigned Q5.59, saturating at the upper endpoint.
    wire [63:0] input_exponent = {53'd0, i_x[62:52]};
    wire [63:0] input_significand = {11'd0, 1'b1, i_x[51:0]};
    wire [63:0] x_fixed = i_x[63] ? 64'd0 :
        ((input_exponent >= 64'd1028) ? 64'hffffffffffffffff :
         ((input_exponent >= 64'd1016) ?
          (input_significand << (input_exponent - 64'd1016)) :
          (input_significand >> (64'd1016 - input_exponent))));

    wire [63:0] table_index =
        (x_fixed >> (32'd59 - LUT_BITS)) & (LUT_SIZE - 64'd1);
    wire [63:0] input_integer = x_fixed >> 64'd59;
    wire [63:0] input_residual = (x_fixed >> 64'd29) & RESIDUAL_MASK;

    // The low-rate peer evaluates locally and queues completed results.
    wire [63:0] peer_exponent = {53'd0, i_peer_x[62:52]};
    wire [63:0] peer_significand = {11'd0, 1'b1, i_peer_x[51:0]};
    wire [63:0] peer_fixed = i_peer_x[63] ? 64'd0 :
        ((peer_exponent >= 64'd1028) ? 64'hffffffffffffffff :
         ((peer_exponent >= 64'd1016) ?
          (peer_significand << (peer_exponent - 64'd1016)) :
          (peer_significand >> (64'd1016 - peer_exponent))));
    wire [63:0] peer_index =
        (peer_fixed >> (32'd59 - LUT_BITS)) & (LUT_SIZE - 64'd1);
    wire [63:0] peer_linear =
        LN2_Q30 * ((peer_fixed >> 64'd29) & RESIDUAL_MASK);
    wire [63:0] peer_fraction =
        rom_word(peer_index) * (Q30_ONE + (peer_linear >> 64'd30));
    wire [63:0] peer_q30 = peer_fraction >> 64'd31;
    wire [63:0] peer_result_exponent = 64'd1023 + (peer_fixed >> 64'd59);
    wire [63:0] peer_result =
        {1'b0, peer_result_exponent[10:0], peer_q30[29:0], 22'd0};
    wire peer_pending = peer_count != 3'd0;
    wire select_peer = port_locked ? port_owner :
        (peer_pending && (!pipe_valid[PIPE_DEPTH-1] || prefer_peer));
    wire peer_push = i_peer_valid && o_peer_ready;
    wire peer_pop = o_valid && i_out_ready && select_peer;
    assign o_peer_ready = i_ce && (peer_count < PEER_DEPTH);
    assign o_lane = select_peer;

    // The entire pipeline freezes behind a blocked output. Thus an occupied
    // stage is never overwritten before its item advances or is consumed.
    wire advance = i_ce && !select_peer &&
        (!pipe_valid[PIPE_DEPTH-1] || i_out_ready);
    wire take = i_valid && coeff_valid[table_index];
    assign o_ready = advance && coeff_valid[table_index];
    assign o_valid = i_ce && (select_peer ? peer_pending : pipe_valid[PIPE_DEPTH-1]);
    assign o_exp2 = select_peer ? peer_q[peer_rd] : data_pipe[PIPE_DEPTH-1];

    // Stage 1: table_base * (1 + ln(2)*residual).
    // The table is Q1.31 and the residual polynomial is Q2.30.
    wire [63:0] linear_product = LN2_Q30 * residual_s0;
    wire [63:0] residual_polynomial =
        Q30_ONE + (linear_product >> 64'd30);
    wire [63:0] fractional_product = data_pipe[0] * residual_polynomial;
    wire [63:0] fractional_q30 = fractional_product >> 64'd31;
    wire [63:0] result_exponent = 64'd1023 + integer_s1;

    always @(posedge clk) begin
        if (advance) begin
            pipe_valid <= {pipe_valid[PIPE_DEPTH-2:0], take};
            data_pipe[0] <= coeff_rom[table_index];
            integer_s0 <= input_integer;
            residual_s0 <= input_residual;
            data_pipe[1] <= fractional_q30;
            integer_s1 <= integer_s0;
            // Stage 2: put the integer part in the binary64 exponent.
            data_pipe[2] <= {
                1'b0, result_exponent[10:0], data_pipe[1][29:0], 22'd0
            };
            for (integer s = 32'd3; s < PIPE_DEPTH; s = s + 32'd1)
                data_pipe[s] <= data_pipe[s-1];

            case ({take, pipe_valid[PIPE_DEPTH-1]})
                2'b10: outstanding <= outstanding + 64'd1;
                2'b01: outstanding <= outstanding - 64'd1;
                default: outstanding <= outstanding;
            endcase
        end
    end

    always @(posedge clk) begin
        if (peer_push) begin
            peer_q[peer_wr] <= peer_result;
            peer_wr <= peer_wr + 1'b1;
        end
        if (peer_pop) peer_rd <= peer_rd + 1'b1;
        case ({peer_push, peer_pop})
            2'b10: peer_count <= peer_count + 1'b1;
            2'b01: peer_count <= peer_count - 1'b1;
            default: peer_count <= peer_count;
        endcase
        if (i_ce) begin
            if (o_valid) begin
                port_locked <= !i_out_ready;
                port_owner <= select_peer;
                if (i_out_ready) prefer_peer <= !select_peer;
            end else port_locked <= 1'b0;
        end
    end

    always @(*) begin
        if (i_ce && port_locked)
            assert (port_owner ? (peer_count != 3'd0) : (outstanding != 64'd0));
    end

    // Fixed stage positions encode order; no arbitration or age tags are used.
    reg [63:0] occupied_slots;
    always @(*) begin
        occupied_slots = 64'd0;
        for (integer p = 32'd0; p < PIPE_DEPTH; p = p + 32'd1)
            occupied_slots = occupied_slots + {63'd0, pipe_valid[p]};
    end

    assert property (outstanding <= PIPE_CAPACITY);
endmodule

module schmitt_ramp_monitor #(
parameter integer DATA_W = 16,
parameter integer CONFIG_DEPTH = 4
) (
    input wire clk,
    input wire i_ce,
    input wire i_config,
    input wire [DATA_W-1:0] i_upper_threshold,
    input wire i_begin_window,
    input wire i_end_window,
    output wire o_inverted,
    output wire [DATA_W-1:0] o_ramp,
output reg [3:0] o_debug_status,
output wire o_config_ready,
output wire [$clog2(CONFIG_DEPTH):0] o_config_pending,
output wire [DATA_W-1:0] o_pending_high,
output wire o_pending_valid,
output wire o_ramp_wait
);
    // DATA_W must be at least two. Default thresholds are 0x4000/0xc000.
    localparam [DATA_W-1:0] ONE_CODE = {{(DATA_W-1){1'b0}}, 1'b1};
    localparam [DATA_W-1:0] LOW_CODE = {2'b01, {(DATA_W-2){1'b0}}};
    localparam [DATA_W-1:0] DEFAULT_HIGH_CODE = {2'b11, {(DATA_W-2){1'b0}}};
// CONFIG_DEPTH is a power of two, with at least four entries.
localparam integer CONFIG_AW = $clog2(CONFIG_DEPTH);

    reg [DATA_W-1:0] capacitor_code;
    reg [DATA_W-1:0] high_threshold;
    reg schmitt_n;
    reg window;
    reg [7:0] idle_cycles;
    reg [7:0] config_count;
    reg [7:0] transition_count;
    reg previous_schmitt;

reg [DATA_W-1:0] config_mem [0:CONFIG_DEPTH-1];
reg [CONFIG_AW:0] config_wr;
reg [CONFIG_AW:0] config_rd;
reg [DATA_W-1:0] config_stage_high;
reg config_stage_valid;
wire [CONFIG_AW:0] queued_count;
wire config_empty;
wire config_full;
wire config_push;
wire config_pop;
wire config_apply;
integer config_init;

    wire [DATA_W-1:0] configured_high;
    wire [DATA_W-1:0] next_code;

    assign configured_high = (i_upper_threshold > LOW_CODE)
                           ? i_upper_threshold : (LOW_CODE + ONE_CODE);

    // The inverter output controls charging versus discharging.
    assign next_code = schmitt_n ? (capacitor_code + ONE_CODE)
                                 : (capacitor_code - ONE_CODE);
    assign o_inverted = schmitt_n;
    assign o_ramp = capacitor_code;
assign queued_count = config_wr - config_rd;
assign config_empty = (config_wr == config_rd);
assign config_full = (config_wr[CONFIG_AW] != config_rd[CONFIG_AW])
                  && (config_wr[CONFIG_AW-1:0] == config_rd[CONFIG_AW-1:0]);
assign o_config_ready = i_ce && !config_full;
assign config_push = i_config && o_config_ready;
assign config_pop = i_ce && !config_empty;
assign config_apply = i_ce && config_stage_valid;
assign o_config_pending = queued_count + config_stage_valid;
assign o_ramp_wait = config_stage_valid || !config_empty
                  || config_push;
assign o_pending_high = config_stage_high;
assign o_pending_valid = config_stage_valid;

    initial begin
        idle_cycles = 8'd0;
        config_count = 8'd0;
        transition_count = 8'd0;
        previous_schmitt = 1'b1;
        o_debug_status = 4'b0000;
    end
    always @(posedge clk) begin
        previous_schmitt <= schmitt_n;
        if (i_ce)
            idle_cycles <= 8'd0;
        else if (idle_cycles != 8'hff)
            idle_cycles <= idle_cycles + 8'd1;
if (config_push && (config_count != 8'hff))
            config_count <= config_count + 8'd1;
        if ((previous_schmitt != schmitt_n) && (transition_count != 8'hff))
            transition_count <= transition_count + 8'd1;
        o_debug_status <= {window, (config_count == 8'hff),
                           (transition_count == 8'hff), (idle_cycles == 8'hff)};
    end

    initial begin
        capacitor_code = LOW_CODE;
        high_threshold = DEFAULT_HIGH_CODE;
        schmitt_n = 1'b1;
        window = 1'b0;
    end

initial begin
    config_wr = 0;
    config_rd = 0;
    config_stage_high = DEFAULT_HIGH_CODE;
    config_stage_valid = 1'b0;
    for (config_init = 0; config_init < CONFIG_DEPTH; config_init = config_init + 1)
        config_mem[config_init] = DEFAULT_HIGH_CODE;
end

always @(posedge clk) begin
    if (config_push) begin
        config_mem[config_wr[CONFIG_AW-1:0]] <=
            (configured_high >= capacitor_code) ? configured_high : capacitor_code;
        config_wr <= config_wr + 1'b1;
    end
    if (i_ce) begin
        config_stage_valid <= config_pop;
        if (config_pop) begin
            config_stage_high <= config_mem[config_rd[CONFIG_AW-1:0]];
            config_rd <= config_rd + 1'b1;
        end
    end
end


    always @(posedge clk) begin
        if (i_ce) begin
            // The observation window stays open until explicitly ended.
            if (i_end_window)
                window <= 1'b0;
            else if (i_begin_window)
                window <= 1'b1;

if (config_apply) begin
    high_threshold <= config_stage_high;
    if (capacitor_code >= config_stage_high)
        schmitt_n <= 1'b0;
end else if (!o_ramp_wait) begin
                capacitor_code <= next_code;

                // Schmitt-trigger inverter: retain its output in the band.
                if (next_code >= high_threshold)
                    schmitt_n <= 1'b0;
                else if (next_code <= LOW_CODE)
                    schmitt_n <= 1'b1;
            end
        end
    end

    always @(posedge clk)
        if (window)
            assert (capacitor_code <= high_threshold);
endmodule

module metric_operand_quantizer #(
    parameter integer CONTEXTS = 32'd4
) (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        i_valid,
    input  wire [63:0] i_x,
    output wire        o_ready,
    output wire        o_valid,
    output wire [63:0] o_fixed,
    input  wire        i_out_ready,
    output wire [$clog2(CONTEXTS+1)-1:0] o_count,
    output wire [$clog2(CONTEXTS)-1:0] o_read_ptr,
    output wire [$clog2(CONTEXTS)-1:0] o_write_ptr,
    output wire [$clog2(CONTEXTS)-1:0] o_work_ptr,
    output reg [64*CONTEXTS-1:0] o_storage,
    output reg [6*CONTEXTS-1:0] o_steps,
    output reg [2*CONTEXTS-1:0] o_phase,
    output wire [3*CONTEXTS-1:0] o_rounding
);
    // Four or eight contexts hide the latency of a shared one-bit shifter.
    // Results are unsigned Q5.59, rounded to nearest with ties to even.
    localparam integer PTR_BITS = $clog2(CONTEXTS);
    localparam integer COUNT_BITS = $clog2(CONTEXTS+1);
    localparam [COUNT_BITS-1:0] CAPACITY = CONTEXTS;
    localparam [1:0] EMPTY = 2'd0;
    localparam [1:0] SHIFT = 2'd1;
    localparam [1:0] ROUND = 2'd2;
    localparam [1:0] DONE = 2'd3;

    reg [63:0] magnitude [0:CONTEXTS-1];
    reg [5:0] steps [0:CONTEXTS-1];
    reg [1:0] phase [0:CONTEXTS-1];
    reg [CONTEXTS-1:0] right_shift;
    reg [CONTEXTS-1:0] guard_bit;
    reg [CONTEXTS-1:0] sticky_bit;
    reg [PTR_BITS-1:0] read_ptr, write_ptr, work_ptr;
    reg [COUNT_BITS-1:0] used_count;

    wire pop = i_ce && o_valid && i_out_ready;
    wire push = i_valid && o_ready;
    wire [10:0] exponent = i_x[62:52];
    wire [10:0] left_distance = exponent - 11'd1016;
    wire [10:0] right_distance = 11'd1016 - exponent;
    wire [63:0] significand = {11'd0, 1'b1, i_x[51:0]};

    assign o_ready = i_ce && ((used_count < CAPACITY) || pop);
    assign o_valid = (used_count != 0) && (phase[read_ptr] == DONE);
    assign o_fixed = magnitude[read_ptr];
    assign o_count = used_count;
    assign o_read_ptr = read_ptr;
    assign o_write_ptr = write_ptr;
    assign o_work_ptr = work_ptr;
    assign o_rounding = {right_shift, guard_bit, sticky_bit};

    reg [63:0] seed_magnitude;
    reg [5:0] seed_steps;
    reg [1:0] seed_phase;
    reg seed_right;
    always @(*) begin
        seed_magnitude = 64'd0;
        seed_steps = 6'd0;
        seed_phase = DONE;
        seed_right = 1'b0;
        // Negative operands clamp to zero. Positive overflow clamps high.
        // Subnormals and very small normals are below half a Q5.59 ulp.
        if (!i_x[63]) begin
            if (exponent >= 11'd1028) begin
                seed_magnitude = 64'hffffffffffffffff;
            end else if (exponent >= 11'd1016) begin
                seed_magnitude = significand;
                seed_steps = left_distance[5:0];
                if (exponent != 11'd1016)
                    seed_phase = SHIFT;
            end else if (exponent >= 11'd953) begin
                seed_magnitude = significand;
                seed_steps = right_distance[5:0];
                seed_right = 1'b1;
                seed_phase = SHIFT;
            end
        end
    end

    always @(*) begin
        o_storage = {64*CONTEXTS{1'b0}};
        o_steps = {6*CONTEXTS{1'b0}};
        o_phase = {2*CONTEXTS{1'b0}};
        for (integer e = 32'd0; e < CONTEXTS; e = e + 32'd1) begin
            o_storage[64*e +: 64] = magnitude[e];
            o_steps[6*e +: 6] = steps[e];
            o_phase[2*e +: 2] = phase[e];
        end
    end

    initial begin
        read_ptr = {PTR_BITS{1'b0}};
        write_ptr = {PTR_BITS{1'b0}};
        work_ptr = {PTR_BITS{1'b0}};
        used_count = {COUNT_BITS{1'b0}};
        right_shift = {CONTEXTS{1'b0}};
        guard_bit = {CONTEXTS{1'b0}};
        sticky_bit = {CONTEXTS{1'b0}};
        for (integer e = 32'd0; e < CONTEXTS; e = e + 32'd1) begin
            magnitude[e] = 64'd0;
            steps[e] = 6'd0;
            phase[e] = EMPTY;
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            // Circular indices wrap naturally for supported context counts.
            // Completed contexts are immutable until their ordered retirement.
            work_ptr <= work_ptr + 1'b1;
            case (phase[work_ptr])
                SHIFT: begin
                    if (steps[work_ptr] != 6'd0) begin
                        if (right_shift[work_ptr]) begin
                            magnitude[work_ptr] <= magnitude[work_ptr] >> 1;
                            guard_bit[work_ptr] <= magnitude[work_ptr][0];
                            sticky_bit[work_ptr] <=
                                sticky_bit[work_ptr] || guard_bit[work_ptr];
                        end else begin
                            magnitude[work_ptr] <= magnitude[work_ptr] << 1;
                        end
                        steps[work_ptr] <= steps[work_ptr] - 1'b1;
                        if (steps[work_ptr] == 6'd1)
                            phase[work_ptr] <= ROUND;
                    end else begin
                        phase[work_ptr] <= ROUND;
                    end
                end
                ROUND: begin
                    if (right_shift[work_ptr] && guard_bit[work_ptr] &&
                        (sticky_bit[work_ptr] || magnitude[work_ptr][0]))
                        magnitude[work_ptr] <= magnitude[work_ptr] + 64'd1;
                    phase[work_ptr] <= DONE;
                end
                default: begin
                end
            endcase
        end

        if (pop) begin
            phase[read_ptr] <= EMPTY;
            read_ptr <= read_ptr + 1'b1;
        end
        // A full ring may replace the retiring DONE context in this cycle.
        // The worker only writes SHIFT or ROUND contexts, so cannot collide.
        if (push) begin
            magnitude[write_ptr] <= seed_magnitude;
            steps[write_ptr] <= seed_steps;
            phase[write_ptr] <= seed_phase;
            right_shift[write_ptr] <= seed_right;
            guard_bit[write_ptr] <= 1'b0;
            sticky_bit[write_ptr] <= 1'b0;
            write_ptr <= write_ptr + 1'b1;
        end
        case ({push, pop})
            2'b10: used_count <= used_count + 1'b1;
            2'b01: used_count <= used_count - 1'b1;
            default: used_count <= used_count;
        endcase
    end
endmodule

module metric_request_gather #(
    parameter integer QUEUE_DEPTH = 32'd4,
    parameter integer GATHER_CYCLES = 32'd4
) (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        i_valid,
    input  wire [63:0] i_x,
    output wire        o_ready,
    output wire        o_valid,
    output wire [63:0] o_x,
    input  wire        i_out_ready,
    output wire [$clog2(QUEUE_DEPTH+1)-1:0] o_count,
    output wire [$clog2(QUEUE_DEPTH)-1:0] o_read_ptr,
    output wire [$clog2(QUEUE_DEPTH)-1:0] o_write_ptr,
    output wire        o_draining,
    output wire [$clog2(GATHER_CYCLES)-1:0] o_wait,
    output reg [64*QUEUE_DEPTH-1:0] o_storage
);
    // Supported queue and gathering sizes are powers of two, 4 or 8.
    // A timeout launches isolated requests without requiring a full batch.
    localparam integer PTR_BITS = $clog2(QUEUE_DEPTH);
    localparam integer COUNT_BITS = $clog2(QUEUE_DEPTH+1);
    localparam integer WAIT_BITS = $clog2(GATHER_CYCLES);
    localparam [PTR_BITS-1:0] LAST_ENTRY = QUEUE_DEPTH - 1;
    localparam [COUNT_BITS-1:0] QUEUE_LIMIT = QUEUE_DEPTH;
    localparam [WAIT_BITS-1:0] GATHER_LAST = GATHER_CYCLES - 1;

    reg [63:0] request_mem [0:QUEUE_DEPTH-1];
    reg [PTR_BITS-1:0] read_ptr, write_ptr;
    reg [COUNT_BITS-1:0] used_count;
    reg [63:0] issue_x;
    reg issue_valid;
    reg draining;
    reg [WAIT_BITS-1:0] gather_wait;

    // The registered read port isolates queue storage from evaluator stalls.
    wire issue_advance = i_ce && (!issue_valid || i_out_ready);
    wire launch_batch = draining || (used_count == QUEUE_LIMIT) ||
        (gather_wait == GATHER_LAST);
    wire refill = issue_advance && launch_batch && (used_count != 0);
    wire push = i_valid && o_ready;
    assign o_ready = i_ce &&
        ((used_count < QUEUE_LIMIT) || refill);
    assign o_valid = issue_valid;
    assign o_x = issue_x;
    assign o_count = used_count;
    assign o_read_ptr = read_ptr;
    assign o_write_ptr = write_ptr;
    assign o_draining = draining;
    assign o_wait = gather_wait;

    always @(*) begin
        o_storage = {64*QUEUE_DEPTH{1'b0}};
        for (integer e = 32'd0; e < QUEUE_DEPTH; e = e + 32'd1)
            o_storage[64*e +: 64] = request_mem[e];
    end

    initial begin
        read_ptr = {PTR_BITS{1'b0}};
        write_ptr = {PTR_BITS{1'b0}};
        used_count = {COUNT_BITS{1'b0}};
        issue_x = 64'd0;
        issue_valid = 1'b0;
        draining = 1'b0;
        gather_wait = {WAIT_BITS{1'b0}};
        for (integer e = 32'd0; e < QUEUE_DEPTH; e = e + 32'd1)
            request_mem[e] = 64'd0;
    end

    always @(posedge clk) begin
        if (push) begin
            request_mem[write_ptr] <= i_x;
            if (write_ptr == LAST_ENTRY)
                write_ptr <= {PTR_BITS{1'b0}};
            else
                write_ptr <= write_ptr + 1'b1;
        end
        if (refill) begin
            if (read_ptr == LAST_ENTRY)
                read_ptr <= {PTR_BITS{1'b0}};
            else
                read_ptr <= read_ptr + 1'b1;
        end
        case ({push, refill})
            2'b10: used_count <= used_count + 1'b1;
            2'b01: used_count <= used_count - 1'b1;
            default: used_count <= used_count;
        endcase

        // Once launched, drain continuously until the queued batch empties.
        // Backpressure holds both the issue register and the queue read port.
        if (i_ce) begin
            if (used_count == 0) begin
                draining <= 1'b0;
                gather_wait <= {WAIT_BITS{1'b0}};
            end else if (!draining) begin
                if (launch_batch) begin
                    draining <= 1'b1;
                    gather_wait <= {WAIT_BITS{1'b0}};
                end else begin
                    gather_wait <= gather_wait + 1'b1;
                end
            end
        end

        if (issue_advance) begin
            issue_valid <= refill;
            if (refill)
                issue_x <= request_mem[read_ptr];
        end
    end
endmodule

module metric_exp2_pipe #(
    parameter integer PIPE_DEPTH = 32'd32,
    parameter integer LUT_ENTRIES = 32'd32,
    parameter integer FRONT_DEPTH = 32'd4,
    parameter integer GATHER_CYCLES = 32'd4,
    parameter integer RANGE_CONTEXTS = 32'd4
) (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        i_valid,
    input  wire [63:0] i_x,
    output wire        o_ready,
    output wire        o_valid,
    output wire [63:0] o_exp2,
    input  wire        i_out_ready,
    output wire [159:0] o_debug_stats,
    output wire [64*FRONT_DEPTH-1:0] o_front_storage,
    output wire [63:0] o_front_x,
    output wire [2*$clog2(FRONT_DEPTH)+$clog2(FRONT_DEPTH+1)+$clog2(GATHER_CYCLES)+1:0] o_front_status,
    output wire [64*RANGE_CONTEXTS-1:0] o_range_storage,
    output wire [6*RANGE_CONTEXTS-1:0] o_range_steps,
    output wire [2*RANGE_CONTEXTS-1:0] o_range_phase,
    output wire [3*RANGE_CONTEXTS-1:0] o_range_rounding,
    output wire [3*$clog2(RANGE_CONTEXTS)+$clog2(RANGE_CONTEXTS+1)-1:0] o_range_status
);
    // PIPE_DEPTH >= 3. LUT_ENTRIES is a power of two from 2 through 32.
    // FRONT_DEPTH and GATHER_CYCLES are 4 or 8; PIPE_DEPTH > FRONT_DEPTH+1.
    // Reserve front-end capacity in the transaction window, keeping ingress
    // readiness independent of the evaluator's output backpressure cone.
    // Binary64 input and output; a table plus linear residual polynomial
    // approximates exp2. Inputs outside [0,32) are clamped before evaluation.
    localparam integer LUT_BITS = $clog2(LUT_ENTRIES);
    localparam [63:0] PIPE_CAPACITY = PIPE_DEPTH;
    localparam [63:0] LUT_SIZE = LUT_ENTRIES;
    localparam integer FRONT_PTR_BITS = $clog2(FRONT_DEPTH);
    localparam integer FRONT_COUNT_BITS = $clog2(FRONT_DEPTH+1);
    localparam integer FRONT_WAIT_BITS = $clog2(GATHER_CYCLES);
    localparam [63:0] FRONT_CAPACITY = FRONT_DEPTH + 1;
    localparam [63:0] PIPE_ISSUE_LIMIT = PIPE_CAPACITY - FRONT_CAPACITY;
    // RANGE_CONTEXTS is 4 or 8; PIPE_DEPTH exceeds both upstream capacities.
    localparam integer RANGE_PTR_BITS = $clog2(RANGE_CONTEXTS);
    localparam integer RANGE_COUNT_BITS = $clog2(RANGE_CONTEXTS+1);
    localparam [63:0] RANGE_CAPACITY = RANGE_CONTEXTS;
    localparam [63:0] RANGE_ISSUE_LIMIT = PIPE_ISSUE_LIMIT - RANGE_CAPACITY;
    localparam [63:0] Q30_ONE = 64'h0000000040000000;
    localparam [63:0] LN2_Q30 = 64'd744261118;
    localparam [63:0] RESIDUAL_MASK =
        (64'd1 << (32'd30 - LUT_BITS)) - 64'd1;

    reg [63:0] coeff_rom [0:LUT_ENTRIES-1];
    reg [LUT_ENTRIES-1:0] coeff_valid;
    reg [63:0] data_pipe [0:PIPE_DEPTH-1];
    reg [PIPE_DEPTH-1:0] pipe_valid;
    reg [63:0] integer_s0, integer_s1, residual_s0;
    reg [63:0] outstanding;
    reg [63:0] occupied_slots;

    wire front_in_ready, front_valid, front_issue_ready;
    wire [63:0] front_x;
    wire [FRONT_PTR_BITS-1:0] front_read_ptr, front_write_ptr;
    wire [FRONT_COUNT_BITS-1:0] front_count;
    wire front_draining;
    wire [FRONT_WAIT_BITS-1:0] front_wait;

    metric_request_gather #(
        .QUEUE_DEPTH(FRONT_DEPTH),
        .GATHER_CYCLES(GATHER_CYCLES)
    ) request_frontend (
        .clk(clk),
        .i_ce(i_ce),
        .i_valid(i_valid),
        .i_x(i_x),
        .o_ready(front_in_ready),
        .o_valid(front_valid),
        .o_x(front_x),
        .i_out_ready(front_issue_ready),
        .o_count(front_count),
        .o_read_ptr(front_read_ptr),
        .o_write_ptr(front_write_ptr),
        .o_draining(front_draining),
        .o_wait(front_wait),
        .o_storage(o_front_storage)
    );
    assign o_front_x = front_x;
    assign o_front_status = {front_write_ptr, front_read_ptr, front_count,
        front_valid, front_draining, front_wait};

    wire range_in_ready, range_valid, range_issue_ready;
    wire [63:0] range_fixed;
    wire [RANGE_COUNT_BITS-1:0] range_count;
    wire [RANGE_PTR_BITS-1:0] range_read_ptr, range_write_ptr, range_work_ptr;

    metric_operand_quantizer #(
        .CONTEXTS(RANGE_CONTEXTS)
    ) operand_quantizer (
        .clk(clk),
        .i_ce(i_ce),
        .i_valid(front_valid),
        .i_x(front_x),
        .o_ready(range_in_ready),
        .o_valid(range_valid),
        .o_fixed(range_fixed),
        .i_out_ready(range_issue_ready),
        .o_count(range_count),
        .o_read_ptr(range_read_ptr),
        .o_write_ptr(range_write_ptr),
        .o_work_ptr(range_work_ptr),
        .o_storage(o_range_storage),
        .o_steps(o_range_steps),
        .o_phase(o_range_phase),
        .o_rounding(o_range_rounding)
    );
    assign front_issue_ready = range_in_ready;
    assign o_range_status = {range_work_ptr, range_write_ptr,
        range_read_ptr, range_count};

    // Q1.31 samples of 2^(j/32). Smaller supported tables subsample this ROM.
    function [63:0] rom_word;
        input [63:0] slot;
        reg [63:0] sample;
        begin
            sample = (slot * 64'd32) / LUT_SIZE;
            case (sample)
                64'd0:  rom_word = 64'h0000000080000000;
                64'd1:  rom_word = 64'h0000000082cd8699;
                64'd2:  rom_word = 64'h0000000085aac368;
                64'd3:  rom_word = 64'h0000000088980e81;
                64'd4:  rom_word = 64'h000000008b95c1e4;
                64'd5:  rom_word = 64'h000000008ea4398b;
                64'd6:  rom_word = 64'h0000000091c3d373;
                64'd7:  rom_word = 64'h0000000094f4efa9;
                64'd8:  rom_word = 64'h000000009837f052;
                64'd9:  rom_word = 64'h000000009b8d39ba;
                64'd10: rom_word = 64'h000000009ef53261;
                64'd11: rom_word = 64'h00000000a2704303;
                64'd12: rom_word = 64'h00000000a5fed6aa;
                64'd13: rom_word = 64'h00000000a9a15ab5;
                64'd14: rom_word = 64'h00000000ad583eea;
                64'd15: rom_word = 64'h00000000b123f582;
                64'd16: rom_word = 64'h00000000b504f334;
                64'd17: rom_word = 64'h00000000b8fbaf47;
                64'd18: rom_word = 64'h00000000bd08a39f;
                64'd19: rom_word = 64'h00000000c12c4cca;
                64'd20: rom_word = 64'h00000000c5672a11;
                64'd21: rom_word = 64'h00000000c9b9bd86;
                64'd22: rom_word = 64'h00000000ce248c15;
                64'd23: rom_word = 64'h00000000d2a81d91;
                64'd24: rom_word = 64'h00000000d744fcca;
                64'd25: rom_word = 64'h00000000dbfbb798;
                64'd26: rom_word = 64'h00000000e0ccdeec;
                64'd27: rom_word = 64'h00000000e5b906e7;
                64'd28: rom_word = 64'h00000000eac0c6e8;
                64'd29: rom_word = 64'h00000000efe4b99c;
                64'd30: rom_word = 64'h00000000f5257d15;
                64'd31: rom_word = 64'h00000000fa83b2db;
                default: rom_word = 64'h0000000080000000;
            endcase
        end
    endfunction

    initial begin
        coeff_valid = {LUT_ENTRIES{1'b1}};
        pipe_valid = {PIPE_DEPTH{1'b0}};
        integer_s0 = 64'd0;
        integer_s1 = 64'd0;
        residual_s0 = 64'd0;
        outstanding = 64'd0;
        for (integer n = 32'd0; n < LUT_ENTRIES; n = n + 32'd1)
            coeff_rom[n] = rom_word(n);
        for (integer n = 32'd0; n < PIPE_DEPTH; n = n + 32'd1)
            data_pipe[n] = 64'd0;
    end

    // Quantization is shared across contexts instead of using a barrel shifter.
    wire [63:0] input_exponent = {53'd0, i_x[62:52]};
    wire [63:0] x_fixed = range_fixed;

    wire [63:0] table_index =
        (x_fixed >> (32'd59 - LUT_BITS)) & (LUT_SIZE - 64'd1);
    wire [63:0] input_integer = x_fixed >> 64'd59;
    wire [63:0] input_residual = (x_fixed >> 64'd29) & RESIDUAL_MASK;

    // The entire pipeline freezes behind a blocked output. Thus an occupied
    // stage is never overwritten before its item advances or is consumed.
    // An empty evaluator also sleeps while the front end gathers its batch.
    wire advance = i_ce && (!pipe_valid[PIPE_DEPTH-1] || i_out_ready) &&
        ((occupied_slots != 64'd0) || range_valid);
    assign range_issue_ready = advance && coeff_valid[table_index] &&
        ((occupied_slots < RANGE_ISSUE_LIMIT) || pipe_valid[PIPE_DEPTH-1]);
    wire take = range_valid && range_issue_ready;
    assign o_ready = front_in_ready;
    assign o_valid = i_ce && pipe_valid[PIPE_DEPTH-1];
    assign o_exp2 = data_pipe[PIPE_DEPTH-1];

    // Read-only diagnostic bank; all counters saturate rather than wrap.
    reg [15:0] dbg_cycles;
    reg [15:0] dbg_accept_count;
    reg [15:0] dbg_retire_count;
    reg [15:0] dbg_blocked_cycles;
    reg [15:0] dbg_paused_cycles;
    reg [15:0] dbg_clamp_count;
    reg [15:0] dbg_special_count;
    reg [15:0] dbg_subnormal_count;
    reg [15:0] dbg_stall_run;
    reg [15:0] dbg_stall_peak;
    wire dbg_accept = i_valid && o_ready;
    wire dbg_retire = o_valid && i_out_ready;
    wire dbg_blocked = i_ce && pipe_valid[PIPE_DEPTH-1] && !i_out_ready;
    wire dbg_clamped = i_x[63] || (input_exponent >= 64'd1028);
    initial begin
        dbg_cycles = 16'd0;
        dbg_accept_count = 16'd0;
        dbg_retire_count = 16'd0;
        dbg_blocked_cycles = 16'd0;
        dbg_paused_cycles = 16'd0;
        dbg_clamp_count = 16'd0;
        dbg_special_count = 16'd0;
        dbg_subnormal_count = 16'd0;
        dbg_stall_run = 16'd0;
        dbg_stall_peak = 16'd0;
    end
    assign o_debug_stats = {
        dbg_cycles, dbg_accept_count,
        dbg_retire_count, dbg_blocked_cycles,
        dbg_paused_cycles, dbg_clamp_count,
        dbg_special_count, dbg_subnormal_count,
        dbg_stall_run, dbg_stall_peak
    };
    always @(posedge clk) begin
        if (dbg_cycles != 16'hffff)
            dbg_cycles <= dbg_cycles + 16'd1;
        if (dbg_accept) begin
            if (dbg_accept_count != 16'hffff)
                dbg_accept_count <= dbg_accept_count + 16'd1;
            if (dbg_clamped && dbg_clamp_count != 16'hffff)
                dbg_clamp_count <= dbg_clamp_count + 16'd1;
            if (input_exponent == 64'd2047 && dbg_special_count != 16'hffff)
                dbg_special_count <= dbg_special_count + 16'd1;
            if (input_exponent == 64'd0 && i_x[51:0] != 52'd0 &&
                dbg_subnormal_count != 16'hffff)
                dbg_subnormal_count <= dbg_subnormal_count + 16'd1;
        end
        if (dbg_retire && dbg_retire_count != 16'hffff)
            dbg_retire_count <= dbg_retire_count + 16'd1;
        if (!i_ce && dbg_paused_cycles != 16'hffff)
            dbg_paused_cycles <= dbg_paused_cycles + 16'd1;
        if (dbg_blocked) begin
            if (dbg_blocked_cycles != 16'hffff)
                dbg_blocked_cycles <= dbg_blocked_cycles + 16'd1;
            if (dbg_stall_run != 16'hffff) begin
                dbg_stall_run <= dbg_stall_run + 16'd1;
                if (dbg_stall_run >= dbg_stall_peak)
                    dbg_stall_peak <= dbg_stall_run + 16'd1;
            end
        end else begin
            dbg_stall_run <= 16'd0;
        end
    end

    // Stage 1: table_base * (1 + ln(2)*residual).
    // The table is Q1.31 and the residual polynomial is Q2.30.
    wire [63:0] linear_product = LN2_Q30 * residual_s0;
    wire [63:0] residual_polynomial =
        Q30_ONE + (linear_product >> 64'd30);
    wire [63:0] fractional_product = data_pipe[0] * residual_polynomial;
    wire [63:0] fractional_q30 = fractional_product >> 64'd31;
    wire [63:0] result_exponent = 64'd1023 + integer_s1;

    always @(posedge clk) begin
        if (advance) begin
            pipe_valid <= {pipe_valid[PIPE_DEPTH-2:0], take};
            data_pipe[0] <= coeff_rom[table_index];
            integer_s0 <= input_integer;
            residual_s0 <= input_residual;
            data_pipe[1] <= fractional_q30;
            integer_s1 <= integer_s0;
            // Stage 2: put the integer part in the binary64 exponent.
            data_pipe[2] <= {
                1'b0, result_exponent[10:0], data_pipe[1][29:0], 22'd0
            };
            for (integer s = 32'd3; s < PIPE_DEPTH; s = s + 32'd1)
                data_pipe[s] <= data_pipe[s-1];

        end
        // Admission includes requests still waiting for burst launch.
        case ({dbg_accept, dbg_retire})
            2'b10: outstanding <= outstanding + 64'd1;
            2'b01: outstanding <= outstanding - 64'd1;
            default: outstanding <= outstanding;
        endcase
    end

    // Fixed stage positions encode order; no arbitration or age tags are used.
    always @(*) begin
        occupied_slots = 64'd0;
        for (integer p = 32'd0; p < PIPE_DEPTH; p = p + 32'd1)
            occupied_slots = occupied_slots + {63'd0, pipe_valid[p]};
    end

    assert property (outstanding <= PIPE_CAPACITY);
endmodule
